export default {
  tourOptions: {
    useModalOverlay: true,
    confirmCancelMessage: 'tour.confirmCancelSales',
  },
  steps: [
    {
      id: 'tourSaleFirstStep',
      textRef: 'tourSaleFirstStep',
      classes: 'tour-step tour-first-sale-first-step',
      buttons: [
        {
          text: 'tour.confirmCancelTitle',
          classes: 'tour-button-back',
          action: 'confirmCancelTour',
        },
        {
          text: 'shared.continue',
          classes: 'tour-button',
          tourAction: 'next',
        },
      ],
      cancelIcon: true,
    },
    {
      id: 'onboardingFirstSaleThirdStep',
      title: 'tour.firstSaleTour.thirdStep.title',
      textRef: 'tourFirstSaleThirdStep',
      classes: 'tour-step tour-header tour-third-step',
      attachTo: {
        element: '#sales-input-search-div',
        on: 'right',
      },
      popperOptions: {
        modifiers: [
          {
            name: 'offset',
            options: {
              offset: [0, 40],
            },
          },
        ],
      },
      cancelIcon: true,
    },
    {
      id: 'onboardingFirstSaleFourthStep',
      title: 'tour.firstSaleTour.fourthStep.title',
      text: 'tour.firstSaleTour.fourthStep.text',
      classes: 'tour-step tour-header tour-fourth-step',
      attachTo: {
        element: '#current-sale-container',
        on: 'top',
      },
      popperOptions: {
        modifiers: [
          {
            name: 'offset',
            options: {
              offset: ({ reference }) => {
                const listProductsWidth = document.getElementById(
                  'sales-products-list'
                ).offsetWidth
                const skiddingValue =
                  listProductsWidth / 2 -
                  (reference.width / 2 - (reference.width - listProductsWidth))
                return [-skiddingValue, 20]
              },
            },
          },
          {
            name: 'arrow',
            options: {
              padding: ({ popper }) => popper.width / 2,
            },
          },
        ],
      },
      cancelIcon: true,
    },
    {
      id: 'onboardingFirstSaleFifthStep',
      title: 'tour.firstSaleTour.fifthStep.title',
      text: 'tour.firstSaleTour.fifthStep.text',
      classes: 'tour-step tour-header tour-fifth-step',
      attachTo: {
        element: '#current-sale-container',
        on: 'top',
      },
      advanceOn: { selector: '#pay-button', event: 'click' },
      popperOptions: {
        modifiers: [
          {
            name: 'offset',
            options: {
              offset: ({ popper, reference }) => {
                const skiddingValue = reference.width / 2 - popper.width / 2
                return [skiddingValue, 20]
              },
            },
          },
          {
            name: 'arrow',
            options: {
              padding: ({ popper, reference }) => {
                const listProductsWidth = document.getElementById(
                  'sales-products-list'
                ).offsetWidth
                const padding =
                  popper.width - (reference.width - listProductsWidth) / 2
                return padding
              },
            },
          },
        ],
      },
      cancelIcon: true,
    },
    {
      id: 'onboardingFirstSaleSixthStep',
      title: 'tour.firstSaleTour.sixthStep.title',
      text: 'tour.firstSaleTour.sixthStep.text',
      classes: 'tour-step tour-header tour-sixth-step',
      attachTo: {
        element: '#calculate-change-dialog',
        on: 'top',
      },
      advanceOn: {
        selector: '#dialog-accept-calculate-change-dialog',
        event: 'click',
      },
      popperOptions: {
        modifiers: [
          {
            name: 'offset',
            options: {
              offset: [0, 170],
            },
          },
        ],
      },
      cancelIcon: true,
    },
    {
      id: 'onboardingFirstSaleSeventhStep',
      textRef: 'tourFirstSaleSeventhStep',
      classes: 'tour-step tour-seventh-step',
      buttons: [
        {
          text: 'tour.firstSaleTour.seventhStep.firstButton',
          classes: 'tour-button-back',
          action: 'goToHelpCenter',
        },
        {
          text: 'tour.firstSaleTour.seventhStep.secondButton',
          classes: 'tour-button',
          tourAction: 'next',
        },
      ],
    },
  ],
}
