<template>
  <div class="fill-height">
    <PaginatedCards :config="paginatedCardsConfig" id="sales-products-list" />
    <SimilarProductsUpc v-if="similarProductsUpcDialog.isOpen" />
    <v-dialog
      v-model="productDetailDialog.isOpen"
      max-width="715"
      :overlay-opacity="0.15"
      content-class="default-dialog"
      @click:outside="onClickOutside"
      @keydown.esc="onClickOutside"
    >
      <!-- Detail view -->
      <ProductDetail v-if="productDetailDialog.isOpen" />
    </v-dialog>
  </div>
</template>

<script>
import { mapState, mapGetters, mapActions } from 'vuex'
import { isNil, find, concat, filter } from 'ramda'
import uniqid from 'uniqid'

import { testMode } from '@/config/env'
import ADD_PRODUCT_EVENTS from '@/config/events/addProduct'
import ENTITIES_EVENTS from '@/config/events/databaseAPI/entitiesEvents'

import { getNow } from '@/tools/dates'
import productsTools from '@/tools/products'
import { getObjectCopy } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import salesActions from '@/store/sales/actions.types'
import salesViewActions from '@/store/salesView/actions.types'
import appActions from '@/store/app/actions.types'
import productsActions from '@/store/products/actions.types'

import PaginatedCards from '@/components/shared/PaginatedCards'
import ProductDetail from '@/components/ProductDetail'
import setConfig from '@/components/SalesView/MultiSalesTabs/ProductsList/PaginatedCards/config'
import SimilarProductsUpc from '@/components/ProductsView/ProductsList/SimilarProductsUpc'

export default {
  name: 'PaginatedCardsList',
  components: {
    SimilarProductsUpc,
    PaginatedCards,
    ProductDetail,
  },
  computed: {
    ...mapState('app', ['windowSize', 'sidebarOpened']),
    ...mapState('app', {
      isScannerActive: state => state.scanner.isActive,
      defaultProductsFilter: state => state.defaultProductsFilter,
    }),
    ...mapState('products', ['data', 'fetching']),
    ...mapState('sales', {
      sales: state => state.sales,
    }),
    ...mapState('salesView', {
      currentSale: state => state.currentSale.saleIndex,
      filters: state => state.filters,
      selectedProduct: state => state.selectedProduct,
      currentCardComponent: state => state.cardComponent,
      tourEnabled: state => state.tourEnabled,
    }),
    ...mapState('products', {
      products: state => state.data.products,
    }),
    ...mapState('airtimeServices', {
      airtimeBalance: state => state.balance.amount,
      airtimeBalanceFetching: state => state.balance.fetching,
    }),
    ...mapState({
      productDetailDialog(state) {
        return state[this.getViewStore()].productDetailDialog
      },
    }),
    ...mapGetters('salesView', ['getFilteredProducts']),
    ...mapState('productsView', ['similarProductsUpcDialog']),
    filteredData() {
      const filteredData = concat(this.getFilteredProducts, this.data.mlp)
      const searchTerm = this.filters.searchTerm
      if (
        !isNil(searchTerm) &&
        this.isScannerActive === true &&
        filteredData.length === 0 &&
        !this.tourEnabled
      ) {
        if (searchTerm.length > 24) {
          this.$root.$emit('reset')
          this.resetScannerStatus(this.defaultProductsFilter)
          this[salesViewActions.setSearchTermFilter](null)
          return this.getFilteredProducts
        }
        this.tryAddProductFromMLP(searchTerm)
      }
      return filteredData
    },
    paginatedCardsConfig() {
      return setConfig(
        {
          items: this.filteredData,
          selectedCard: this.selectedProduct,
          filters: this.filters,
          windowHeight: this.windowSize.y,
          windowWidth: this.windowSize.x,
          fetching: this.fetching,
          sidebarOpened: this.sidebarOpened,
          currentSale: this.currentSale,
          currentCardComponent: this.currentCardComponent,
          byWeightTree: this.data.byWeightTree,
          products: this.products,
          sales: this.sales,
          airtimeBalance: this.airtimeBalance,
          airtimeBalanceFetching: this.airtimeBalanceFetching,
        },
        {
          track: this.$track,
          onSectionWidthChange: this.onSectionWidthChange,
          setSelectedProduct: this[salesViewActions.setSelectedProduct],
          toggleDetailPanel: this[salesViewActions.toggleDetailDialog],
          addProductToCurrentSale: this[salesActions.addProductToCurrentSale],
          setGroup: this[salesViewActions.setGroupFilter],
          setSelectedSuperCategories: this[
            salesViewActions.setSuperCategoriesFilter
          ],
          context: this,
          setNotificationDialogStatus: this[
            salesViewActions.setNotificationDialogStatus
          ],
          toggleGenericProductDialogStatus: this[
            salesViewActions.toggleGenericProductDialogStatus
          ],
          toggleByWeightProductDialogStatus: this[
            salesViewActions.toggleByWeightProductDialogStatus
          ],
          resetScannerStatus: this.resetScannerStatus,
          setSelectedByWeightCategory: this[
            salesViewActions.setSelectedByWeightCategory
          ],
          toggleProductTriangulationDialogStatus: this[
            salesViewActions.toggleProductTriangulationDialogStatus
          ],
          onCLickCard: this.onCLickCard,
        }
      )
    },
    existsAirtimeSaleItem() {
      const result = this.sales.every(sale => {
        const airtimeProducts = sale.items.some(item => item.isAirtime === 1)
        return !airtimeProducts
      })
      return !result
    },
  },
  methods: {
    ...mapActions('app', [appActions.updateScannerStatus]),
    ...mapActions('sales', [salesActions.addProductToCurrentSale]),
    ...mapActions('salesView', [
      salesViewActions.setNotificationDialogStatus,
      salesViewActions.toggleDetailDialog,
      salesViewActions.setSelectedProduct,
      salesViewActions.setGroupFilter,
      salesViewActions.setSuperCategoriesFilter,
      salesViewActions.toggleGenericProductDialogStatus,
      salesViewActions.toggleByWeightProductDialogStatus,
      salesViewActions.setSelectedByWeightCategory,
      salesViewActions.toggleProductTriangulationDialogStatus,
      salesViewActions.setSearchTermFilter,
      salesViewActions.toggleAddProductDialog,
      salesViewActions.toggleAirtimeProductDialogStatus,
    ]),
    ...mapActions('products', [
      productsActions.addProductFromMLP,
      productsActions.setProductsOrSuperCategoriesFetching,
    ]),
    getViewStore() {
      return this.$route.name === 'Products' ? 'productsView' : 'salesView'
    },
    onClickOutside() {
      this[salesViewActions.toggleDetailDialog]()
      this[salesViewActions.setSelectedProduct](null)
      document.getElementById('clear-button-control').click()
    },
    async tryAddProductFromMLP(searchTerm) {
      if (this.fetching) return
      this[productsActions.setProductsOrSuperCategoriesFetching](true)
      rendererEventsService.send(ADD_PRODUCT_EVENTS.channel, {
        event: ADD_PRODUCT_EVENTS.events.addProductFromMLP.name,
        data: { item: { property: 'upc_code', value: searchTerm, limit: 1 } },
      })
    },
    onProductAddedFromMLP(data) {
      const { newProduct } = data
      this[productsActions.addProductFromMLP]({
        newProduct: newProduct,
        currentView: 'salesView',
      })
      const product = getObjectCopy(newProduct)
      this.$root.$emit('reset')
      this.resetScannerStatus(this.defaultProductsFilter)
      this[salesViewActions.setSearchTermFilter](null)
      if (!this.tourEnabled)
        notificationsService.showInfo(
          'productsView.listView.messages.newProductAdded',
          this.$vuetify.lang,
          { timeout: 8000 }
        )
      if (
        product.isGramaje === 0 &&
        product.id > 0 &&
        product.factor > 0 &&
        product.factorSalesBy === 2
      ) {
        this.$track({
          type: 'system',
          action: 'add_product_mlp',
          category: 'Sales',
          screen: 'ProductsList',
          name: 'Show product triangulation dialog',
        })
        this[salesViewActions.setSelectedProduct]({
          ticketIndex: this.currentSale,
          product: {
            ...product,
            openProductDbPrices: {
              package: product.price,
              piece: product.unitProdPrice,
            },
            factorSalesBy: 0,
            promotionTypeId: 0,
          },
        })
        this[salesViewActions.toggleProductTriangulationDialogStatus]()
        return
      }
      if (product.isGramaje === 0 && product.factor < 0) {
        this.$track({
          type: 'system',
          action: 'add_product_mlp',
          category: 'Sales',
          screen: 'ProductsList',
          name: 'Add product',
        })
        if (product.price <= 0) {
          this[salesViewActions.setSelectedProduct]({
            ticketIndex: this.currentSale,
            product: { ...product },
          })
          this[salesViewActions.toggleProductTriangulationDialogStatus]()
          return
        }
        const ticketItem = this.buildItem(
          {
            currentSale: this.currentSale,
            products: this.data.products,
          },
          product
        )
        this[salesActions.addProductToCurrentSale](ticketItem)
        return
      }
      this.$track({
        type: 'system',
        action: 'add_product_mlp',
        category: 'Sales',
        screen: 'ProductsList',
        name: 'Show product triangulation dialog',
      })
      this[salesViewActions.setSelectedProduct]({
        ticketIndex: this.currentSale,
        product: { ...product, promotionTypeId: 0 },
      })
      this[salesViewActions.toggleProductTriangulationDialogStatus]()
      this[productsActions.setProductsOrSuperCategoriesFetching](false)
    },
    onAddingProductFromMLPError(data) {
      if (data.error.message === 'newProduct') {
        this.$track({
          type: 'system',
          action: 'add_product_mlp',
          category: 'Sales',
          screen: 'ProductsList',
          name: `Show add custom product dialog`,
        })
        this[salesViewActions.toggleAddProductDialog]()
        return
      }
      notificationsService.showError(data.errorMsg, this.$vuetify.lang, {
        timeout: 8000,
      })
      this.$root.$emit('reset')
      this.resetScannerStatus(this.defaultProductsFilter)
      this[salesViewActions.setSearchTermFilter](null)
      if (data.error.message === 'invalid-barcode') {
        this[productsActions.setProductsOrSuperCategoriesFetching](false)
        return
      }
      rendererEventsService.send(ENTITIES_EVENTS.channel, {
        event: ENTITIES_EVENTS.events.getAllByEntities.name,
        data: {
          entitiesToGet: [
            'storeInventory',
            'superCategories',
            'genericCategories',
            'byWeightHomeCodes',
            'airtimeProviders',
            'airtimeServices',
          ],
          replyName: 'fetchProducts',
        },
      })
    },
    resetScannerStatus(group) {
      switch (group) {
        case 'search-control':
          if (this.isScannerActive === false)
            this[appActions.updateScannerStatus]()
          break
        case 'clear':
          this[salesViewActions.setSearchTermFilter](null)
          this[salesViewActions.setGroupFilter](this.defaultProductsFilter)
          if (!this.isScannerActive) this[appActions.updateScannerStatus]()
          break
        default:
          group === 'superCategories'
            ? this[salesViewActions.setGroupFilter]('superCategories')
            : this[salesViewActions.setGroupFilter](group)
          if (!this.isScannerActive) this[appActions.updateScannerStatus]()
          break
      }
    },
    buildItem(state, scannedProduct) {
      return {
        currentSale: state.currentSale,
        product: {
          uniqueId: uniqid(),
          id: scannedProduct.id,
          stock: scannedProduct.quantity,
          isGramaje: scannedProduct.isGramaje === 1 ? 1 : 0,
          isOpenProduct: scannedProduct.factor > 0 ? 1 : 0,
          openProductType: 0,
          isGeneric: scannedProduct.isGeneric === 1 ? 1 : 0,
          isPriceChanged: scannedProduct.isPriceChanged,
          isPiecePriceChanged: scannedProduct.isPiecePriceChanged,
          name: scannedProduct.name,
          quantity: 1,
          unitPrice: scannedProduct.price,
          cost: scannedProduct.cost,
          upc: scannedProduct.upc,
          timeAdded: getNow(false),
          priceFrom: productsTools.getAddedFrom(scannedProduct),
          dbPrice: find(item => item.upc === scannedProduct.upc, state.products)
            .price,
          factor: scannedProduct.factor,
          description: scannedProduct.alternativeName,
          promotionTypeId: 0,
        },
      }
    },
    addProductFromMLPListener(event, payload) {
      const events = ADD_PRODUCT_EVENTS.events
      const replies = {
        [events.addProductFromMLP.replies.success]: () =>
          this.onProductAddedFromMLP(payload.data),
        [events.addProductFromMLP.replies.error]: () =>
          this.onAddingProductFromMLPError(payload.data),
      }
      if (payload.event in replies) replies[payload.event]()
    },
    getTypeProduct(item) {
      return item.isGramaje === 1
        ? ' by weight'
        : item.isGeneric === 1
        ? ' generic'
        : item.airTime === 1
        ? ' airtime'
        : item.factor > 1
        ? ' open'
        : ''
    },
    onCLickCard(item) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Sales',
        screen: 'ProductCard',
        name: `Add${this.getTypeProduct(item)} product`,
      })
      if (this.tourEnabled) {
        if (item.isGeneric === 1 || item.factor > 0 || item.isGramaje === 1) {
          notificationsService.showError(
            'tour.productNotAvailable',
            this.$vuetify.lang,
            { timeout: 4000 }
          )
          return
        } else {
          this.$root.$emit('product-added-tour')
        }
      }
      if (item.airTime === 1) {
        if (this.airtimeBalance <= 0) {
          return
        }
        if (this.existsAirtimeSaleItem) {
          notificationsService.showError(
            'salesView.airtimeProductDialog.errorMessages.alreadyExistsProduct',
            this.$vuetify.lang,
            {
              timeout: 8000,
            }
          )
          return
        }
      }
      if (isNil(item.isStoreInventory) || item.isStoreInventory === 1) {
        const product = getObjectCopy(item)
        // Check if item exists in the current sale
        const productsExistInCurrenSale = !isNil(
          find(
            item => item.id === product.id,
            this.sales[this.currentSale].items
          )
        )
        if (product.isGeneric === 1) {
          this[salesViewActions.toggleGenericProductDialogStatus](product)
        } else if (
          product.isGramaje === 0 &&
          product.id > 0 &&
          product.factor > 0 &&
          product.factorSalesBy === 2 &&
          !productsExistInCurrenSale
        ) {
          if (this.productExistInCurrentSaleCombos(product)) {
            this[salesActions.addProductToCurrentSale]({
              currentSale: this.currentSale,
              product: productsTools.getProductForSale(
                { ...product, factorSalesBy: 0 },
                this.products
              ),
            })
            return
          }
          this[salesViewActions.setSelectedProduct]({
            ticketIndex: this.currentSale,
            product: {
              ...product,
              openProductDbPrices: {
                package: product.price,
                piece: product.unitProdPrice,
              },
              factorSalesBy: 0,
            },
          })
          this[salesViewActions.toggleProductTriangulationDialogStatus]()
          return
        } else if (product.airTime === 1) {
          this[salesViewActions.setSelectedProduct](product)
          this[salesViewActions.toggleAirtimeProductDialogStatus](product)
          return
        } else if (product.isGramaje === 0 && product.id > 0) {
          if (product.price <= 0) {
            this[salesViewActions.setSelectedProduct]({
              ticketIndex: this.currentSale,
              product: { ...product },
            })
            this[salesViewActions.toggleProductTriangulationDialogStatus]()
            return
          }
          this[salesActions.addProductToCurrentSale]({
            currentSale: this.currentSale,
            product: productsTools.getProductForSale(product, this.products),
          })
          return
        } else if (product.isGramaje === 1) {
          this[salesViewActions.setSelectedProduct]({
            ticketIndex: this.currentSale,
            product: product,
          })
          this[salesViewActions.toggleProductTriangulationDialogStatus]()
        } else if (product.id < -1) {
          const category = filter(category => category.name === product.name)(
            this.data.byWeightTree
          )[0]
          this[salesViewActions.setSelectedByWeightCategory](category)
          this[salesViewActions.toggleByWeightProductDialogStatus]()
        } else {
          this[salesViewActions.setNotificationDialogStatus]()
        }
        return
      }
      this.tryAddProductFromMLP(item.upc)
    },
    productExistInCurrentSaleCombos(product) {
      return this.sales[this.currentSale].promotions.some(
        promo =>
          promo.promotions.firstProduct.id === product.id ||
          promo.promotions.secondProduct.id === product.id
      )
    },
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      ADD_PRODUCT_EVENTS.replyChannel,
      this.addProductFromMLPListener
    )
  },
  beforeDestroy() {
    this.resetScannerStatus('clear')
    rendererEventsService.removeListener(
      ADD_PRODUCT_EVENTS.replyChannel,
      this.addProductFromMLPListener
    )
  },
}
</script>
