<template>
  <DialogCard :config="dialogConfig.dialogData" />
</template>

<script>
import { mapState, mapActions } from 'vuex'

import salesViewActions from '@/store/salesView/actions.types'

import setDialogConfig from '@/components/SalesView/MultiSalesTabs/OverCreditLimitDialog/config'
import DialogCard from '@/components/shared/DialogCard'

export default {
  name: 'OverCreditLimitDialog',
  components: { DialogCard },
  props: {
    paySaleCallback: {
      type: Function,
      required: true,
    },
  },
  computed: {
    ...mapState('salesView', ['overCreditLimitDialog']),
    dialogConfig() {
      return setDialogConfig(
        {
          opened: this.overCreditLimitDialog.isOpen,
        },
        {
          closeDialog: this.closeDialog,
          paySale: () => {
            this.$track({
              type: 'interaction',
              action: 'click',
              category: 'Sales',
              screen: 'OverCreditLimitDialog',
              name: 'Finish sale',
            })
            this.paySaleCallback()
          },
          setSaleStatus: this[salesViewActions.setSaleStatus],
        }
      )
    },
  },
  methods: {
    ...mapActions('salesView', [
      salesViewActions.setOverCreditLimitDialogStatus,
      salesViewActions.setSaleStatus,
    ]),
    closeDialog() {
      this[salesViewActions.setOverCreditLimitDialogStatus](false)
    },
  },
}
</script>
