<template>
  <div>
    <p class="mb-0 font-weight-medium black--text">
      <v-icon color="black" small>mdi-plus-minus-variant</v-icon>
      {{
        getTranslatedText(
          'customPromotionsView.inSale.dialogPromotion.moreForLess.title'
        )
      }}
    </p>
    <p>
      {{
        getTranslatedText(
          'customPromotionsView.inSale.dialogPromotion.moreForLess.info'
        )
      }}
    </p>
    <ScrollContainer
      height="auto"
      max-height="150px"
      :scroll-active-style="{
        'margin-right': '-22px',
        'padding-right': '2px',
      }"
    >
      <v-list-item
        v-for="promotion in promotions"
        :key="promotion.id"
        class="px-0 justify-space-between d-flex"
      >
        <v-list-item-title class="d-flex align-center">
          <span
            v-html="
              getTranslatedText(
                'customPromotionsView.inSale.dialogPromotion.moreForLess.promotion',
                [
                  promotion.quantity,
                  formatNumberFromDbToCurrency(promotion.total),
                ]
              )
            "
          />
          <v-spacer />
          <span class="text-subtitle-2 font-weight-regular">
            {{
              getTranslatedText(
                'customPromotionsView.inSale.dialogPromotion.moreForLess.unitPrice',
                formatNumberFromDbToCurrency(promotion.promotionUnitPrice)
              )
            }}
          </span>
        </v-list-item-title>
      </v-list-item>
    </ScrollContainer>
    <div class="mt-4">
      <p class="mb-4 text-subtitle-2">
        {{
          getTranslatedText(
            'customPromotionsView.inSale.dialogPromotion.moreForLess.numOfPieces'
          )
        }}
      </p>
      <v-text-field
        v-model="quantity"
        class="custom-text-field"
        filled
        rounded
        dense
        type="number"
        hide-details
        hide-spin-buttons
        ref="quantityPromotion"
        @blur="updateInput"
      >
        <template v-slot:prepend>
          <v-btn
            icon
            color="primary"
            class="mt-n2 mx-2"
            @click="changeQuantity(quantityProductSale - 1)"
          >
            <v-icon>mdi-minus</v-icon>
          </v-btn>
        </template>
        <template v-slot:append-outer>
          <v-btn
            icon
            color="primary"
            class="mt-n2 mx-2"
            @click="changeQuantity(quantityProductSale + 1)"
          >
            <v-icon>mdi-plus</v-icon>
          </v-btn>
        </template>
      </v-text-field>
    </div>
  </div>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import { getTranslatedText } from '@/tools/data'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'
import productsTools from '@/tools/products'

import salesActions from '@/store/sales/actions.types'
import salesViewActions from '@/store/salesView/actions.types'

import ScrollContainer from '@/components/shared/ScrollContainer'

export default {
  name: 'MoreForLessList',
  components: { ScrollContainer },
  props: {
    ticketIndex: {
      type: Number,
      required: true,
    },
    promotions: {
      type: Array,
      required: true,
    },
  },
  computed: {
    ...mapState('sales', ['sales']),
    ...mapState('salesView', ['listProductPromotionsDialog']),
    ...mapState('products', {
      products: state => state.data.products,
    }),
    indexProductFromSale() {
      return this.sales[this.ticketIndex].items.findIndex(
        item => item.id === this.listProductPromotionsDialog.product.id
      )
    },
    quantityProductSale() {
      if (this.indexProductFromSale < 0) return 0
      return this.sales[this.ticketIndex].items[this.indexProductFromSale]
        .quantity
    },
    quantityForForm() {
      if (this.indexProductFromSale < 0) return 1
      const quantityFromSale = this.sales[this.ticketIndex].items[
        this.indexProductFromSale
      ].quantity
      return quantityFromSale > 0 ? quantityFromSale : 1
    },
    quantity: {
      get() {
        if (this.indexProductFromSale < 0) return 1
        return this.quantityForForm
      },
      set(value) {
        this.changeQuantity(value)
      },
    },
  },
  methods: {
    formatNumberFromDbToCurrency,
    getTranslatedText,
    ...mapActions('sales', [
      salesActions.updateProductFromSale,
      salesActions.addProductToCurrentSale,
    ]),
    ...mapActions('salesView', [
      salesViewActions.setListProductPromotionsDialogStatus,
    ]),
    async changeQuantity(value) {
      const quantity =
        value > 0 ? Number(Math.floor(value)) : this.quantityForForm
      if (value === '') return
      this.$refs.quantityPromotion.lazyValue = quantity
      if (value <= 0 && value !== '') return
      const productUpdated = {
        ...this.listProductPromotionsDialog.product,
        quantity,
      }
      this.updateProductInSale(productUpdated)
    },
    updateInput(event) {
      if (event.target.value === '') {
        this.$refs.quantityPromotion.lazyValue = this.quantityForForm
        return
      }
      if (event.target.value <= 0) {
        this.$refs.quantityPromotion.lazyValue = this.quantityForForm
      }
    },
    updateProductInSale(productUpdated) {
      if (this.indexProductFromSale >= 0) {
        this[salesActions.updateProductFromSale]({
          ticketIndex: this.ticketIndex,
          newData: {
            ...this.sales[this.ticketIndex].items[this.indexProductFromSale],
            quantity: productUpdated.quantity,
          },
          productIndex: this.indexProductFromSale,
        })
        return
      }
      this[salesActions.addProductToCurrentSale]({
        currentSale: this.ticketIndex,
        product: productsTools.getProductForSale(
          {
            ...productUpdated,
            factorSalesBy: productUpdated.factor > 0 ? 0 : 2,
          },
          this.products
        ),
      })
    },
  },
}
</script>
