<template>
  <DialogCard :config="dialogConfig.dialogData">
    <StepperSelector :config="stepperConfig.stepper" />
  </DialogCard>
</template>

<script>
import { mapActions, mapState } from 'vuex'
import { filter, find, isEmpty, map } from 'ramda'
import uniqid from 'uniqid'

import { testMode } from '@/config/env'
import STORE_INVENTORY_DB_API_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'
import ADD_PRODUCT_EVENTS from '@/config/events/addProduct'
import { storeInventory } from '@/config/storeMapper'
import priceFrom from '@/config/itemAddedFrom'
import { promotions } from '@/config/promotions'

import { mapStoreObject } from '@/tools/data'
import { getNow } from '@/tools/dates'
import { getObjectCopy } from '@/tools/data'
import { formatNumberToDb } from '@/tools/numbersFormat'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import appActions from '@/store/app/actions.types'
import productsActions from '@/store/products/actions.types'
import salesActions from '@/store/sales/actions.types'
import salesViewActions from '@/store/salesView/actions.types'

import DialogCard from '@/components/shared/DialogCard'
import StepperSelector from '@/components/SalesView/MultiSalesTabs/ByWeightProductDialog/ByWeightProductSector'
import setDialogConfig from '@/components/SalesView/MultiSalesTabs/ByWeightProductDialog/dialogConfig'
import setStepperConfig from '@/components/SalesView/MultiSalesTabs/ByWeightProductDialog/stepperConfig'

export default {
  name: 'ByWeightProductDialog',
  components: { DialogCard, StepperSelector },
  data() {
    return {
      formPayload: {
        productPromotionTypeId: promotions.NONE,
      },
      newByWeightProducts: [],
      isAcceptButtonDisabled: true,
      product: null,
      productError: false,
      addingProduct: false,
    }
  },
  byWeightProducts: [],
  computed: {
    ...mapState('app', ['defaultProductsFilter']),
    ...mapState('salesView', [
      'byWeightProductDialog',
      'selectedByWeightCategory',
      'currentSale',
    ]),
    ...mapState('products', {
      products: state => state.data.products,
    }),
    dialogConfig() {
      return setDialogConfig(
        {
          dialog: {
            isOpen: this.byWeightProductDialog.isOpen,
            isAcceptButtonDisabled: this.isAcceptButtonDisabled,
          },
          selectedByWeightCategory: this.selectedByWeightCategory,
          products: this.products,
        },
        {
          dialog: {
            onCloseDialog: this.onCloseDialog,
            onSubmitForm: this.onSubmitForm,
          },
          setGroupFilter: this[salesViewActions.setGroupFilter],
        }
      )
    },
    stepperConfig() {
      return setStepperConfig(
        {
          selectedByWeightCategory: this.selectedByWeightCategory,
          products: this.products,
          product: this.product,
          productError: this.productError,
          formPayload: this.formPayload,
          ticketIndex: this.currentSale.saleIndex,
        },
        {
          products: {
            getProductByUpc: this.getProductByUpc,
          },
          dialog: {
            onSubmitForm: this.onSubmitForm,
          },
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.updateScannerStatus]),
    ...mapActions('salesView', [
      salesViewActions.toggleByWeightProductDialogStatus,
      salesViewActions.setGroupFilter,
      salesViewActions.setSearchTermFilter,
    ]),
    ...mapActions('products', [
      productsActions.addProductFromMLP,
      productsActions.setProductsState,
      productsActions.setProductsOrSuperCategoriesFetching,
    ]),
    ...mapActions('sales', [salesActions.addProductToCurrentSale]),
    getProductByUpc(upc) {
      const inventorySearchResult = filter(
        item => item.upc === upc,
        this.byWeightProducts
      )
      if (!isEmpty(inventorySearchResult)) {
        this.product = inventorySearchResult[0]
        return
      }
      this[productsActions.setProductsOrSuperCategoriesFetching](true)
      rendererEventsService.send(ADD_PRODUCT_EVENTS.channel, {
        event: ADD_PRODUCT_EVENTS.events.addProductFromMLP.name,
        data: {
          item: { property: 'upc_code', value: upc, limit: 1 },
          fromByWeightDialog: true,
        },
      })
    },
    onProductAddedFromMLP(data) {
      this.productError = false
      const { newProduct } = data
      this[productsActions.addProductFromMLP]({
        newProduct: newProduct,
        currentView: 'salesView',
      })
      notificationsService.showInfo(
        'productsView.listView.messages.newProductAdded',
        this.$vuetify.lang,
        { timeout: 8000 }
      )
      this[productsActions.setProductsOrSuperCategoriesFetching](false)
      this.byWeightProducts.push(newProduct)
      this.newByWeightProducts.push(newProduct)
      this.product = newProduct
    },
    addToCurrentSale(item) {
      this[salesActions.addProductToCurrentSale]({
        currentSale: this.currentSale.saleIndex,
        product: {
          uniqueId: uniqid(),
          id: item.product.id,
          stock: item.product.quantity,
          isGramaje: 1,
          isOpenProduct: 0,
          isGeneric: 0,
          isPriceChanged: 1,
          name: item.product.name,
          description: item.product.alternativeName,
          quantity: parseInt(item.inputs.quantity, 10),
          unitPrice: formatNumberToDb(item.inputs.price),
          cost: item.product.cost,
          upc: item.product.upc,
          timeAdded: getNow(false),
          priceFrom: priceFrom.FROM_WEIGHT,
          dbPrice:
            item.isPriceChanged === 1
              ? find(product => product.upc === item.product.upc, this.products)
                  .price
              : formatNumberToDb(item.inputs.price),
          levelWarning: item.product.levelWarning,
          promotionTypeId: item.productPromotionTypeId,
        },
      })
    },
    onCloseDialog() {
      this[salesViewActions.toggleByWeightProductDialogStatus]()
      this.addNewProductsToStore()
    },
    async onSubmitForm() {
      if (this.isAcceptButtonDisabled === true || this.addingProduct === true)
        return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Sales',
        screen: 'ByWeightProductDialog',
        name: 'Add by weight product',
      })
      this.addingProduct = true
      this[salesViewActions.setGroupFilter](this.defaultProductsFilter)
      this[salesViewActions.toggleByWeightProductDialogStatus]()
      await this.addToCurrentSale(this.formPayload)
      this.checkIfPriceChange(this.formPayload)
      this.addingProduct = false
    },
    getByWeightStoredProducts() {
      return filter(item => item.isGramaje === 1, this.products)
    },
    addNewProductsToStore() {
      map(
        product => this[productsActions.setProductsState](product),
        this.newByWeightProducts
      )
    },
    checkIfPriceChange(item) {
      if (item.product.isPriceChanged === 0) {
        rendererEventsService.send(STORE_INVENTORY_DB_API_EVENTS.channel, {
          event: STORE_INVENTORY_DB_API_EVENTS.events.updateById.name,
          data: {
            productToUpdated: {
              id: item.product.id,
              data: mapStoreObject(
                {
                  isPriceChanged: 1,
                  price: formatNumberToDb(item.inputs.price),
                },
                storeInventory,
                true
              ),
            },
          },
        })
      }
    },
    resetScannerStatus(group) {
      switch (group) {
        case 'search-control':
          if (this.isScannerActive === false)
            this[appActions.updateScannerStatus]()
          break
        case 'clear':
          this[salesViewActions.setSearchTermFilter](null)
          this[salesViewActions.setGroupFilter](this.defaultProductsFilter)
          if (!this.isScannerActive) this[appActions.updateScannerStatus]()
          break
        default:
          group === 'superCategories'
            ? this[salesViewActions.setGroupFilter]('superCategories')
            : this[salesViewActions.setGroupFilter](group)
          if (!this.isScannerActive) this[appActions.updateScannerStatus]()
          break
      }
    },
    addProductFromMLPListener(event, payload) {
      const events = ADD_PRODUCT_EVENTS.events
      const replies = {
        [events.addProductFromMLP.replies.successFromByWeightDialog]: () =>
          this.onProductAddedFromMLP(payload.data),
        [events.addProductFromMLP.replies.errorFromByWeightDialog]: () => {
          this[productsActions.setProductsOrSuperCategoriesFetching](false)
          this.product = null
          this.productError = true
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      ADD_PRODUCT_EVENTS.replyChannel,
      this.addProductFromMLPListener
    )
  },
  mounted() {
    this.formPayload.productPromotionTypeId = promotions.NONE
    this.$barcodeScanner.destroy()
    this.byWeightProducts = getObjectCopy(this.getByWeightStoredProducts())
    this.$root.$on('by-weight-selected-product', payload => {
      const { isValid } = payload
      if (isValid === false) {
        this.isAcceptButtonDisabled = true
        return
      }
      this.formPayload = { ...this.formPayload, ...payload }
      this.isAcceptButtonDisabled = false
    })
  },
  beforeDestroy() {
    this.$root.$emit('enable-scanner', {})
    rendererEventsService.removeListener(
      ADD_PRODUCT_EVENTS.replyChannel,
      this.addProductFromMLPListener
    )
  },
}
</script>
