import uniqid from 'uniqid'

import { storeInventory } from '@/config/storeMapper'
import priceFrom from '@/config/itemAddedFrom'
import { promotions } from '@/config/promotions'

import { mapStoreObject } from '@/tools/data'
import { formatNumberToDb } from '@/tools/numbersFormat'
import { getNow } from '@/tools/dates'

const OPEN_PRODUCT_PIECE_TYPE = 'isOpenProductPiece'
const OPEN_PRODUCT_PACKAGE_TYPE = 'isOpenProductPackage'

const getProductToUpdateInStoreInventory = function() {
  const data = {
    [getPriceChangeKeyByType(this.formPayload.productType)]: 1,
    [getPriceKeyByType(this.formPayload.productType)]: formatNumberToDb(
      this.formPayload.inputs.price
    ),
  }
  return {
    id: this.selectedProduct.product.id,
    data: mapStoreObject(data, storeInventory, true),
  }
}

const getProductToUpdateFromSale = function() {
  const { ticketIndex, product } = this.selectedProduct
  return {
    ticketIndex,
    newData: {
      ...getBaseProductTicket(this.formPayload, product),
      dbPrice: formatNumberToDb(this.formPayload.inputs.price),
      openProductDbPrices: {
        package: formatNumberToDb(this.formPayload.inputs.price),
        piece: this.formPayload.product.openProductDbPrices?.piece || null,
      },
      [getPriceChangeKeyByType(this.formPayload.productType)]: 1,
    },
  }
}

const getProductUpdatedFromSale = function() {
  const { ticketIndex, product } = this.selectedProduct
  let baseNewData = getBaseProductTicket(this.formPayload, product)
  const openProductTypes = [OPEN_PRODUCT_PACKAGE_TYPE, OPEN_PRODUCT_PIECE_TYPE]
  if (openProductTypes.includes(this.formPayload.productType)) {
    baseNewData.dbPrice =
      this.formPayload.productType === OPEN_PRODUCT_PACKAGE_TYPE
        ? this.formPayload.product.openProductDbPrices.package
        : this.formPayload.product.openProductDbPrices.pieces
  }
  return { ticketIndex, newData: baseNewData }
}

const getNewProductOfSale = function() {
  const { ticketIndex, product } = this.selectedProduct
  const productFound = this.products.find(item => item.upc === product.upc)
  const { dbPrice, openProductDbPrices } = getDbPriceAndOpenProductDbPrices(
    this.formPayload,
    product,
    productFound
  )
  return {
    currentSale: ticketIndex,
    product: {
      uniqueId: uniqid(),
      ...getDefaultProductData(product),
      ...getBaseProductTicket(this.formPayload, product),
      stock: product.quantity,
      isGramaje: product.isGramaje === 1 ? 1 : 0,
      isOpenProduct: product.factor > 0 ? 1 : 0,
      openProductType: product.factorSalesBy,
      isGeneric: product.isGeneric === 1 ? 1 : 0,
      isPriceChanged:
        this.formPayload.productType !== OPEN_PRODUCT_PIECE_TYPE
          ? 1
          : productFound.isPriceChanged,
      isPiecePriceChanged:
        this.formPayload.productType === OPEN_PRODUCT_PIECE_TYPE
          ? 1
          : productFound.isPiecePriceChanged,
      timeAdded: getNow(false),
      priceFrom: priceFrom.FROM_SCANNER,
      dbPrice,
      openProductDbPrices,
      promotionTypeId: this.formPayload.productPromotionTypeId
        ? this.formPayload.productPromotionTypeId
        : promotions.NONE,
    },
  }
}

const getPriceChangeKeyByType = productType => {
  return isOpenProduct(productType) ? 'isPiecePriceChanged' : 'isPriceChanged'
}

const getPriceKeyByType = productType => {
  return isOpenProduct(productType) ? 'unitProdPrice' : 'price'
}

const isOpenProduct = productType => {
  return productType === OPEN_PRODUCT_PIECE_TYPE
}

const getDbPriceAndOpenProductDbPrices = (payload, product, productFound) => {
  const isOpenProductPiece = isOpenProduct(payload.productType)
  const dbPrice = getDbPrice(payload, isOpenProductPiece, productFound)
  return {
    dbPrice,
    openProductDbPrices: {
      package: isOpenProductPiece ? productFound.price : dbPrice,
      piece: isOpenProductPiece ? dbPrice : productFound.unitProdPrice,
    },
  }
}

const getDbPrice = (payload, product, productFound) => {
  const isOpenProductPiece = isOpenProduct(payload.productType)
  if (isOpenProductPiece && product.isPiecePriceChanged === 1) {
    return (
      payload.product.openProductDbPrices?.piece || productFound.unitProdPrice
    )
  }
  if (!isOpenProductPiece && product.isPriceChanged === 1) {
    return payload.product.openProductDbPrices?.package || productFound.price
  }
  return formatNumberToDb(payload.inputs.price)
}

const getDefaultProductData = product => {
  return {
    id: product.id,
    name: product.name,
    cost: product.cost,
    levelWarning: product.levelWarning,
    factor: product.factor,
    description: product.alternativeName,
  }
}

const getBaseProductTicket = (payload, product) => {
  return {
    unitPrice: formatNumberToDb(payload.inputs.price),
    quantity: parseInt(payload.inputs.quantity, 10),
    upc: product.upc,
    openProductType: payload.openProductType,
    promotionTypeId: payload.productPromotionTypeId,
  }
}

const alertDisabledCustomPromosMustBeShowed = function() {
  if (!this.isEditForm) return false
  return (
    (this.selectedProduct.product.promotions &&
      this.selectedProduct.product.promotions.length > 0) ||
    (this.sales[this.selectedProduct.ticketIndex].promotions &&
      this.sales[this.selectedProduct.ticketIndex].promotions.length > 0 &&
      hasSomePromotionWithProduct(
        this.sales[this.selectedProduct.ticketIndex].promotions,
        this.selectedProduct.product.id
      ))
  )
}
const hasSomePromotionWithProduct = (promotions, productId) => {
  return promotions.some(
    promo =>
      promo.promotions.firstProduct.id === productId ||
      promo.promotions.secondProduct.id === productId
  )
}

export default {
  getProductToUpdateInStoreInventory,
  getProductToUpdateFromSale,
  getProductUpdatedFromSale,
  getNewProductOfSale,
  getPriceChangeKeyByType,
  getPriceKeyByType,
  isOpenProduct,
  alertDisabledCustomPromosMustBeShowed,
}
