import { isEmpty, isNil } from 'ramda'
import { integer, required } from 'vuelidate/lib/validators'

import WEIGHT_SCALE_EVENTS from '@/config/events/weightScaleEvents'

import {
  convertByWeightQuantity,
  decimal,
  formatNumberFromDb,
  formatNumberToDb,
  getDecimalsCount,
  moneyTextFieldCountryConfig,
} from '@/tools/numbersFormat'
import { validate } from '@/tools/validations'

import rendererEventsService from '@/services/renderer/rendererEvents'

export default {
  setDefaultValidators: function(limit) {
    return {
      required,
      minValue: value => value > 0,
      maxValue: value => value < limit,
      integer,
    }
  },
  setMoneyValidator: function(valueLimit, decimalsLimit) {
    return {
      required,
      minValue: value => value > 0,
      maxValue: value => value < valueLimit,
      maxDecimals: value => getDecimalsCount(value) <= decimalsLimit,
    }
  },
  setFormValidators: function() {
    return {
      inputs: {
        price: this.setMoneyValidator(1000000, 4),
        total: this.setMoneyValidator(1000000, 4),
        quantity: this.setDefaultValidators(10000),
      },
    }
  },
  onValidateFields: function(input) {
    return validate(this.$v.inputs, input, {
      fn: this.getTranslatedText,
    })
  },
  checkIfShowDbPrice: function() {
    return formatNumberToDb(this.inputs.price) !== this.productDbPrice
  },
  onQuantityInput: function() {
    if (this.currentFocus !== 'quantity') return
    rendererEventsService.send(WEIGHT_SCALE_EVENTS.channel, {
      event: WEIGHT_SCALE_EVENTS.events.stop.name,
    })
    this.$v.inputs.quantity.$touch()
    this.showDBPrice = this.checkIfShowDbPrice()

    this.inputs.total = decimal(
      this.product.isGramaje === 1
        ? ((this.inputs.quantity || 0) / 1000) * this.inputs.price
        : (this.inputs.quantity || 0) * this.inputs.price,
      4
    )

    setTimeout(() => {
      this.showAlerts()
    }, 0)
    this.emitValues()
  },
  onPriceInput: function() {
    if (this.currentFocus !== 'price') return
    this.$emit('priceWasChanged', formatNumberToDb(this.inputs.price))
    this.$v.inputs.price.$touch()
    this.showDBPrice = this.checkIfShowDbPrice()
    this.inputs.total = decimal(
      this.product.isGramaje === 1
        ? ((this.inputs.quantity || 0) / 1000) * this.inputs.price
        : (this.inputs.price || 0) * this.inputs.quantity,
      4
    )
    this.priceChanged = true
    setTimeout(() => {
      this.showAlerts()
    }, 0)
    this.emitValues()
  },
  onTotalInput: function() {
    if (this.currentFocus !== 'total') return
    this.$v.inputs.total.$touch()
    this.showDBPrice = this.checkIfShowDbPrice()
    if (this.product.isGramaje === 1) {
      rendererEventsService.send(WEIGHT_SCALE_EVENTS.channel, {
        event: WEIGHT_SCALE_EVENTS.events.stop.name,
      })
      this.inputs.quantity = Math.floor(
        decimal(((this.inputs.total || 0) / this.inputs.price) * 1000, 4)
      )
    } else {
      this.inputs.price = (this.inputs.total || 0) / this.inputs.quantity
      this.priceChanged = true
    }
    setTimeout(() => {
      this.showAlerts()
    }, 0)
    this.emitValues()
  },
  onTotalInputBlur: function() {
    this.getInitialFocus()
    this.$v.inputs.total.$touch()
  },
  setAlert: function(type) {
    switch (type) {
      case 'promotion':
        this.alertConfig = {
          icon: 'mdi-alert-circle',
          type: 'warning',
          textColor: 'textPrimary',
          title: 'salesView.byWeightSelector.alerts.priceChanged.title',
          subTitle: 'salesView.byWeightSelector.alerts.priceChanged.subTitle',
        }
        break
      case 'suggested-price':
        this.alertConfig = {
          icon: 'mdi-alert-circle',
          type: 'warning',
          textColor: 'textPrimary',
          title: 'salesView.byWeightSelector.alerts.suggestedPrice.title',
          subTitle: 'salesView.byWeightSelector.alerts.suggestedPrice.subTitle',
        }
        break
      case 'price-increase':
        this.alertConfig = {
          icon: 'mdi-alert-circle',
          type: 'warning',
          textColor: 'textPrimary',
          title: 'salesView.byWeightSelector.alerts.priceIncrease.title',
          subTitle: 'salesView.byWeightSelector.alerts.priceIncrease.subTitle',
        }
        break
      case 'rebase-limit':
        this.alertConfig = {
          icon: 'mdi-alert-circle',
          type: 'error',
          textColor: 'white',
          title: 'salesView.byWeightSelector.alerts.rebaseLimit.title',
          subTitle: 'salesView.byWeightSelector.alerts.rebaseLimit.subTitle',
        }
        break
    }
  },
  showAlerts: function() {
    const isPromotion =
      this.productType === 'isOpenProductPiece'
        ? formatNumberToDb(this.inputs.price) <
          (this.productDbPrice || this.product.unitProdPrice)
        : formatNumberToDb(this.inputs.price) <
          (this.productDbPrice || this.product.price)
    const isPriceIncrease =
      this.productType === 'isOpenProductPiece'
        ? formatNumberToDb(this.inputs.price) >
          (this.productDbPrice || this.product.unitProdPrice)
        : formatNumberToDb(this.inputs.price) >
          (this.productDbPrice || this.product.price)
    this.alertConfig = {}
    switch (this.productType) {
      case 'isOpenProductPiece':
        if (this.product.isPiecePriceChanged === 0) {
          this.setAlert('suggested-price')
        }
        if (
          this.product.isPiecePriceChanged === 1 &&
          this.priceChanged === true
        ) {
          if (isPromotion === true) this.setAlert('promotion')
          if (isPriceIncrease === true) this.setAlert('price-increase')
        }
        break
      default:
        if (this.product.isPriceChanged === 0) {
          this.setAlert('suggested-price')
        }
        if (this.product.isPriceChanged === 1 && this.priceChanged === true) {
          if (isPromotion === true) this.setAlert('promotion')
          if (isPriceIncrease === true) this.setAlert('price-increase')
        }
    }
    if (this.checkIfValuesRebaseLimits() === true) {
      this.showDBPrice = false
      this.setAlert('rebase-limit')
    }
    this.showAlert = !isEmpty(this.alertConfig)
  },
  checkIfValuesRebaseLimits: function() {
    return (
      !this.$v.inputs.quantity.maxValue ||
      !this.$v.inputs.quantity.integer ||
      !this.$v.inputs.price.maxValue ||
      !this.$v.inputs.price.maxDecimals ||
      !this.$v.inputs.total.maxValue ||
      !this.$v.inputs.total.maxDecimals
    )
  },
  setProductType: function(product) {
    const isOpenProduct = product.factor > 0 || product.isOpenProduct === 1
    const isOpenProductPackage =
      isOpenProduct && this.salesByRadioOption === '0'
    const isOpenProductPiece = isOpenProduct && this.salesByRadioOption === '1'
    const isPieceProduct = isOpenProduct === false && product.isGramaje === 0
    const isByWeightProduct = isOpenProduct === false && product.isGramaje === 1

    if (isPieceProduct) return 'isPieceProduct'
    if (isByWeightProduct) return 'isByWeightProduct'
    if (isOpenProductPackage) return 'isOpenProductPackage'
    if (isOpenProductPiece) return 'isOpenProductPiece'
  },
  getPriceLabel: function() {
    switch (this.productType) {
      case 'isPieceProduct':
        return this.getTranslatedText('salesView.byWeightSelector.pricePiece')
      case 'isByWeightProduct':
        return this.getTranslatedText('salesView.byWeightSelector.priceUnit')
      case 'isOpenProductPackage':
        return this.getTranslatedText('salesView.byWeightSelector.pricePackage')
      case 'isOpenProductPiece':
        return this.getTranslatedText('salesView.byWeightSelector.pricePiece')
    }
  },
  getInitialFocus: function() {
    const priceInput = this.$refs.price.$el.querySelector('input')
    setTimeout(() => {
      priceInput.select()
    }, 100)
  },
  initTotal: function() {
    this.inputs.total = Number(
      this.product.isGramaje === 1
        ? (
            convertByWeightQuantity(this.inputs.quantity, false) *
            this.inputs.price
          ).toFixed(2)
        : this.inputs.quantity * this.inputs.price
    )
  },
  showOpenProductOptions: function(product) {
    return product.factor > 0
  },
  getFormValues: function() {
    return {
      inputs: this.inputs,
      product: this.product,
      isValid: !this.$v.$invalid,
      priceChanged: this.priceChanged,
      productType: this.productType,
      openProductType: this.openProductType,
    }
  },
  emitValues: function() {
    this.$root.$emit('by-weight-selected-product', this.getFormValues())
  },
  setPriceFromDB: function() {
    this.inputs.price = formatNumberFromDb(this.productDbPrice)
    this.onPriceInput()
    this.showDBPrice = false
    this.showAlert = false
    this.getInitialFocus()
  },
  initQuantity: function() {
    if (isNil(this.product.uniqueId)) {
      this.inputs.quantity = this.product.isGramaje === 1 ? 100 : 1
      return
    }
    this.inputs.quantity = this.product.quantity > 0 ? this.product.quantity : 1
  },
  resetForm: function() {
    if (isNil(this.product.uniqueId)) {
      this.inputs.quantity = this.product.isGramaje === 1 ? 100 : 1
    } else {
      this.inputs.quantity =
        this.product.quantity > 0 ? this.product.quantity : 1
    }
    this.inputs.price = formatNumberFromDb(this.productDbPrice)
    this.initTotal()
    this.getInitialFocus()
    this.showAlert = false
    this.showDBPrice = false
    this.alertConfig = {}
  },
  getMoneyInputsConfig: function() {
    return moneyTextFieldCountryConfig() || { precision: 2 }
  },
}
