<template>
  <DialogCard :config="dialogConfig.dialogData">
    <template #titleRight v-if="selectedProduct.product.isGramaje === 1">
      <v-spacer />
      <WeightScaleStatus />
    </template>
    <ProductTriangulationForm
      :product="selectedProduct.product"
      :onEnterEvent="onSubmitForm"
      :alert-promotion="alerts.changePrice"
      :has-product-promotion="hasProductPromotion"
      @priceWasChanged="
        value => {
          priceFromForm = value
        }
      "
    />
    <ProductPromotion
      v-if="'productPromotionTypeId' in formPayload"
      v-model="formPayload.productPromotionTypeId"
      :ticket-index="selectedProduct.ticketIndex"
    />
    <v-alert
      v-if="!!alerts.freeProduct"
      dense
      color="secondary"
      text
      icon="mdi-alert-outline"
      class="mb-0 mt-2"
    >
      {{ getTranslatedText(`${alerts.freeProduct}`) }}
    </v-alert>
  </DialogCard>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import STORE_INVENTORY_DB_API_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'
import { promotions } from '@/config/promotions'

import { getTranslatedText } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'

import appActions from '@/store/app/actions.types'
import salesViewActions from '@/store/salesView/actions.types'
import salesActions from '@/store/sales/actions.types'

import DialogCard from '@/components/shared/DialogCard'
import ProductTriangulationForm from '@/components/SalesView/MultiSalesTabs/ProductTriangulationForm'
import setDialogConfig from '@/components/SalesView/MultiSalesTabs/ProductTriangulationDialog/config'
import ProductPromotion from '@/components/SalesView/MultiSalesTabs/ProductTriangulationDialog/ProductPromotion'
import tools from '@/components/SalesView/MultiSalesTabs/ProductTriangulationDialog/productTriangulationDialog.tools'
import WeightScaleStatus from '@/components/MainView/WeightScaleStatus.vue'

export default {
  name: 'ProductTriangulationDialog',
  components: {
    WeightScaleStatus,
    ProductPromotion,
    DialogCard,
    ProductTriangulationForm,
  },
  data() {
    return {
      formPayload: {},
      isAcceptButtonDisabled: true,
      addingProduct: false,
      priceFromForm: 0,
    }
  },
  computed: {
    ...mapState('app', {
      isScannerActive: state => state.scanner.isActive,
      defaultProductsFilter: state => state.defaultProductsFilter,
    }),
    ...mapState('salesView', ['productTriangulationDialog', 'selectedProduct']),
    ...mapState('sales', ['sales']),
    ...mapState('products', { products: state => state.data.products }),
    hasProductPromotion() {
      return (
        this.formPayload.productPromotionTypeId ===
        promotions.SALE_ITEM_FREE_PRODUCT
      )
    },
    dialogConfig() {
      return setDialogConfig(
        {
          dialog: {
            isOpen: this.productTriangulationDialog.isOpen,
            isAcceptButtonDisabled: this.isAcceptButtonDisabled,
          },
          isEditForm: this.isEditForm,
        },
        {
          dialog: {
            onCloseDialog: this.onCloseDialog,
            onSubmitForm: this.onSubmitForm,
          },
        }
      )
    },
    isEditForm() {
      return this.sales[this.selectedProduct.ticketIndex].items.some(
        item => item.upc === this.selectedProduct.product.upc
      )
    },
    alerts() {
      let alerts = {
        freeProduct: null,
        changePrice: null,
      }
      if (
        this.formPayload.productPromotionTypeId ===
        promotions.SALE_ITEM_FREE_PRODUCT
      ) {
        alerts.freeProduct =
          'customPromotionsView.inSale.productTriangulationAlert.freeProduct'
      }
      if (this.priceFromForm !== this.selectedProduct.product.unitPrice) {
        alerts.changePrice =
          'customPromotionsView.inSale.productTriangulationAlert.changePrice'
      }
      if (!tools.alertDisabledCustomPromosMustBeShowed.call(this)) {
        alerts.freeProduct = null
        alerts.changePrice = null
      }
      return alerts
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('app', [appActions.updateScannerStatus]),
    ...mapActions('salesView', [
      salesViewActions.toggleProductTriangulationDialogStatus,
      salesViewActions.setSelectedProduct,
      salesViewActions.setGroupFilter,
      salesViewActions.setSearchTermFilter,
    ]),
    ...mapActions('sales', [
      salesActions.updateProductFromSale,
      salesActions.addProductToCurrentSale,
    ]),
    resetScannerStatus(group) {
      if (group === 'clear') {
        this[salesViewActions.setSearchTermFilter](null)
      }
      this[salesViewActions.setGroupFilter](this.defaultProductsFilter)
      if (!this.isScannerActive) this[appActions.updateScannerStatus]()
    },
    onCloseDialog(group = null) {
      this.$root.$emit('reset')
      this.resetScannerStatus(group || this.defaultProductsFilter)
      this.setSelectedProduct(null)
      this.addingProduct = false
      this[salesViewActions.toggleProductTriangulationDialogStatus]()
    },
    async onSubmitForm() {
      if (this.isAcceptButtonDisabled === true || this.addingProduct === true) {
        return
      }
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Sales',
        screen: 'ProductTriangulationDialog',
        name: `${this.isEditForm ? 'Edit' : 'Add'}${
          this.selectedProduct.product.factor > 1
            ? ' open'
            : this.selectedProduct.product.isGramaje
            ? ' by weight'
            : ''
        } product`,
      })
      this.addingProduct = true
      await this[salesViewActions.setSearchTermFilter](null)
      if (this.isEditForm) {
        this.editProductFromTicket()
        this.onCloseDialog('clear')
        return
      }
      this.addProductToTicket()
      this.onCloseDialog('clear')
    },
    editProductFromTicket() {
      const { product } = this.selectedProduct
      const { productType } = this.formPayload
      if (this.isProductPriceNotChanged(productType, product)) {
        const productToUpdated = tools.getProductToUpdateInStoreInventory.call(
          this
        )
        this.updateStoreInventory({ productToUpdated })
        this[salesActions.updateProductFromSale](
          tools.getProductToUpdateFromSale.call(this)
        )
        return
      }
      if (product.isPriceChanged === 1 || product.isPiecePriceChanged === 1) {
        this[salesActions.updateProductFromSale](
          tools.getProductUpdatedFromSale.call(this)
        )
      }
    },
    addProductToTicket() {
      const { product } = this.selectedProduct
      const { productType } = this.formPayload
      if (this.isProductPriceNotChanged(productType, product)) {
        const productToUpdated = tools.getProductToUpdateInStoreInventory.call(
          this
        )
        this.updateStoreInventory({ productToUpdated })
      }
      const newTicketItem = tools.getNewProductOfSale.call(this)
      this[salesActions.addProductToCurrentSale](newTicketItem)
    },
    isProductPriceNotChanged(productType, product) {
      return (
        (!tools.isOpenProduct(productType) && product.isPriceChanged === 0) ||
        (tools.isOpenProduct(productType) && product.isPiecePriceChanged === 0)
      )
    },
    updateStoreInventory(data) {
      rendererEventsService.send(STORE_INVENTORY_DB_API_EVENTS.channel, {
        event: STORE_INVENTORY_DB_API_EVENTS.events.updateById.name,
        data,
      })
    },
  },
  mounted() {
    this.priceFromForm = this.selectedProduct.product.unitPrice
    this.formPayload.productPromotionTypeId =
      this.selectedProduct?.product?.promotionTypeId || 0
    this.$barcodeScanner.destroy()
    this.$root.$on('by-weight-selected-product', payload => {
      if (payload.isValid === false) {
        this.isAcceptButtonDisabled = true
        return
      }
      this.formPayload = { ...this.formPayload, ...payload }
      this.isAcceptButtonDisabled = false
    })
  },
  beforeDestroy() {
    this.$root.$emit('enable-scanner', {})
    if (this.productTriangulationDialog.isOpen) {
      this[salesViewActions.toggleProductTriangulationDialogStatus]()
    }
  },
}
</script>
