<template>
  <v-container fluid class="sales-view" id="sales-view">
    <!-- Multi sales tab -->
    <v-row no-gutters>
      <v-col class="sales-view__tickets-tabs">
        <MultiSalesTabs :config="componentConfig" />
      </v-col>
    </v-row>
    <!-- Notification Dialog -->
    <NotificationDialog v-if="notificationDialog.isOpen" />
    <ScanYourProductsDialog v-if="scanYourProductsDialog" />
  </v-container>
</template>

<script>
import uniqid from 'uniqid'
import { mapState, mapActions, mapGetters } from 'vuex'

import priceFrom from '@/config/itemAddedFrom'
import ENTITIES_EVENTS from '@/config/events/databaseAPI/entitiesEvents'
import MLP_DB_API_EVENTS from '@/config/events/databaseAPI/mlpEvents'
import USER_INFORMATION_DB_API_EVENTS from '@/config/events/databaseAPI/userInformationEvents'

import { getObjectCopy } from '@/tools/data'
import { getNow } from '@/tools/dates'
import salesTools from '@/tools/sales'
import productsTools from '@/tools/products'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import appActions from '@/store/app/actions.types'
import salesViewActions from '@/store/salesView/actions.types'
import productsActions from '@/store/products/actions.types'
import customersActions from '@/store/customers/actions.types'
import salesActions from '@/store/sales/actions.types'

import config from '@/components/SalesView/config'
import MultiSalesTabs from '@/components/SalesView/MultiSalesTabs'
import NotificationDialog from '@/components/SalesView/MultiSalesTabs/NotificationDialog'
import ScanYourProductsDialog from '@/components/SalesView/ScanYourProductsDialog'

export default {
  name: 'SalesView',
  components: { MultiSalesTabs, NotificationDialog, ScanYourProductsDialog },
  data() {
    return {
      config,
    }
  },
  searchInput: null,
  computed: {
    ...mapState('app', {
      isScannerActive: state => state.scanner.isActive,
      defaultProductsFilter: state => state.defaultProductsFilter,
      showScanYourProductsDialog: state => state.showScanYourProductsDialog,
    }),
    ...mapState('products', {
      products: state => state.data.products,
    }),
    ...mapState('sales', {
      sales: state => state.sales,
    }),
    ...mapState('customers', {
      customers: state => state.data.customers,
    }),
    ...mapState('salesView', {
      currentSale: state => state.currentSale.saleIndex,
      filters: state => state.filters,
      notificationDialog: state => state.notificationDialog,
      addProductDialogIsOpen: state => state.newProductDialog.isOpen,
      scanYourProductsDialog: state => state.scanYourProductsDialog.isOpen,
      tourEnabled: state => state.tourEnabled,
    }),
    ...mapState('usersView', ['selectedUser']),
    ...mapGetters('salesView', ['getFilteredProducts']),
    componentConfig() {
      return config()
    },
  },
  methods: {
    ...mapActions('app', [
      appActions.updateScannerStatus,
      appActions.setShowScanYourProductsDialogStatus,
    ]),
    ...mapActions('products', [
      productsActions.fetchProducts,
      productsActions.setProductsOrSuperCategoriesFetching,
      productsActions.setProductsOrSuperCategoriesError,
      productsActions.setMlpFilteredProducts,
    ]),
    ...mapActions('sales', [salesActions.addProductToCurrentSale]),
    ...mapActions('customers', [
      customersActions.fetchCustomers,
      customersActions.setCustomersFetching,
      customersActions.setCustomersError,
    ]),
    ...mapActions('salesView', [
      salesViewActions.setGroupFilter,
      salesViewActions.setSuperCategoriesFilter,
      salesViewActions.setSearchTermFilter,
      salesViewActions.setSelectedProduct,
      salesViewActions.toggleProductTriangulationDialogStatus,
      salesViewActions.setScanYourProductsDialogStatus,
    ]),
    mlpApiListener(event, payload) {
      const replies = {
        [MLP_DB_API_EVENTS.events.findByPropertiesLikes.replies
          .success]: () => {
          this[productsActions.setMlpFilteredProducts](payload.data)
        },
        [MLP_DB_API_EVENTS.events.findByPropertiesLikes.replies.error]: () => {
          notificationsService.showError(payload.error, this.$vuetify.lang, {
            timeout: 8000,
          })
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    userInformationApiListener(event, payload) {
      const replies = {
        [USER_INFORMATION_DB_API_EVENTS.events
          .updateScanYourProductsDialogCounter.replies.success]: () =>
          this[appActions.setShowScanYourProductsDialogStatus](
            payload.data.keepShowing
          ),
      }
      if (payload.event in replies) replies[payload.event]()
    },
    buildItem(state, scannedProduct) {
      const productPrices = productsTools.getPrices(
        scannedProduct,
        state.products
      )
      return {
        currentSale: state.currentSale,
        product: {
          uniqueId: uniqid(),
          id: scannedProduct.id,
          stock: scannedProduct.quantity,
          isGramaje: scannedProduct.isGramaje === 1 ? 1 : 0,
          isOpenProduct: scannedProduct.factor > 0 ? 1 : 0,
          openProductType: scannedProduct.factorSalesBy,
          openProductDbPrices: productPrices.openProductDbPrices,
          isGeneric: scannedProduct.isGeneric === 1 ? 1 : 0,
          isPriceChanged: productPrices.isPriceChanged,
          isPiecePriceChanged: productPrices.isPiecePriceChanged,
          name: scannedProduct.name,
          quantity: 1,
          unitPrice: productPrices.unitPrice,
          cost: scannedProduct.cost,
          upc: scannedProduct.upc,
          timeAdded: getNow(false),
          priceFrom: priceFrom.FROM_SCANNER,
          dbPrice: productPrices.dbPrice,
          levelWarning: scannedProduct.levelWarning,
          factor: scannedProduct.factor,
          promotionTypeId: 0,
        },
      }
    },
    onBarcodeScanned(barcode) {
      this.$track({
        type: 'interaction',
        action: 'scan',
        category: 'Sales',
        screen: 'ProductsList',
        name: `Product scanned`,
      })
      this[salesViewActions.setSearchTermFilter](barcode)
      if (this.tourEnabled) {
        this.$root.$emit('product-scanned-sale-tour', barcode.trim())
        return
      }
      this.searchInput.blur()
      if (
        this.filters.group !== 'search' &&
        this.getFilteredProducts.length > 1
      ) {
        this[salesViewActions.setSearchTermFilter](null)
        this.$root.$emit('reset')
      }
      if (this.isScannerActive === false) {
        this.$root.$emit('reset')
        this[salesViewActions.setSuperCategoriesFilter]([])
        this[appActions.updateScannerStatus]()
      }
      if (this.filters.group === 'search') {
        this[salesViewActions.setGroupFilter](this.defaultProductsFilter)
      }
      if (this.getFilteredProducts.length === 1) {
        this[salesViewActions.setSelectedProduct](this.getFilteredProducts[0])
        const scannedProduct = getObjectCopy(this.getFilteredProducts[0])
        this.$root.$emit('reset')
        this[salesViewActions.setGroupFilter](this.defaultProductsFilter)
        this[salesViewActions.setSearchTermFilter](null)
        const productsExistInCurrenSale = salesTools.checkIfProductsExistInCurrentSale(
          this.sales[this.currentSale].items,
          scannedProduct
        )
        // Ask for open product type
        if (
          scannedProduct.isGramaje === 0 &&
          scannedProduct.id > 0 &&
          scannedProduct.factor > 0 &&
          scannedProduct.factorSalesBy === 2 &&
          !productsExistInCurrenSale
        ) {
          this.$track({
            type: 'system',
            action: 'scan',
            category: 'Sales',
            screen: 'ProductsList',
            name: 'Show product triangulation dialog',
          })
          this[salesViewActions.setSelectedProduct]({
            ticketIndex: this.currentSale,
            product: {
              ...scannedProduct,
              openProductDbPrices: {
                package: scannedProduct.price,
                piece: scannedProduct.unitProdPrice,
              },
              factorSalesBy: 0,
              promotionTypeId: 0,
            },
          })
          this[salesViewActions.toggleProductTriangulationDialogStatus]()
          return
        }
        // Piece product or open product with default type setted
        if (scannedProduct.isGramaje === 0) {
          if (
            scannedProduct.factor < 0 &&
            scannedProduct.isGeneric === 0 &&
            scannedProduct.price <= 0
          ) {
            this[salesViewActions.setSelectedProduct]({
              ticketIndex: this.currentSale,
              product: {
                ...scannedProduct,
                promotionTypeId: 0,
              },
            })
            this[salesViewActions.toggleProductTriangulationDialogStatus]()
            return
          }
          this.$track({
            type: 'system',
            action: 'scan',
            category: 'Sales',
            screen: 'ProductsList',
            name: 'Add product',
          })
          const item = this.buildItem(
            { currentSale: this.currentSale, products: this.products },
            scannedProduct
          )
          this[salesActions.addProductToCurrentSale](item)
          this[salesViewActions.setSelectedProduct](null)
          return
        }
        // By weight products
        this[salesViewActions.setSelectedProduct]({
          ticketIndex: this.currentSale,
          product: {
            ...scannedProduct,
            openProductDbPrices: {
              package: scannedProduct.price,
              piece: scannedProduct.unitProdPrice,
            },
            promotionTypeId: 0,
          },
        })
        this.$track({
          type: 'system',
          action: 'scan',
          category: 'Sales',
          screen: 'ProductsList',
          name: 'Show product triangulation dialog',
        })
        this[salesViewActions.toggleProductTriangulationDialogStatus]()
      }
    },
    async entitiesListener(event, payload) {
      const getAllReplies = ENTITIES_EVENTS.events.getAllByEntities.replies
      const replies = {
        [`${getAllReplies.success}-fetchProducts`]: () =>
          this[productsActions.fetchProducts](payload.data),
        [`${getAllReplies.success}-fetchCustomers`]: () =>
          this[customersActions.fetchCustomers](payload.data),
        [`${getAllReplies.error}-fetchProducts`]: () => {
          this[productsActions.setProductsOrSuperCategoriesError](payload.data)
          this[productsActions.setProductsOrSuperCategoriesFetching](false)
        },
        [`${getAllReplies.error}-fetchCustomers`]: () => {
          this[customersActions.setCustomersError](payload.data)
          this[customersActions.setCustomersFetching](false)
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  mounted() {
    this.$root.$on('productAddedFromMatch', this.onBarcodeScanned)
    rendererEventsService.subscribe(
      ENTITIES_EVENTS.replyChannel,
      this.entitiesListener
    )
    this.$barcodeScanner.init(this.onBarcodeScanned)
    this.searchInput = document.getElementById('sales-input-search')
    if (this.products.length === 0) {
      this[productsActions.setProductsOrSuperCategoriesFetching](true)
      rendererEventsService.send(ENTITIES_EVENTS.channel, {
        event: ENTITIES_EVENTS.events.getAllByEntities.name,
        data: {
          entitiesToGet: [
            'storeInventory',
            'superCategories',
            'genericCategories',
            'byWeightHomeCodes',
            'airtimeProviders',
            'airtimeServices',
          ],
          replyName: 'fetchProducts',
        },
      })
    }
    if (this.customers.length === 0) {
      this[customersActions.setCustomersFetching](true)
      rendererEventsService.send(ENTITIES_EVENTS.channel, {
        event: ENTITIES_EVENTS.events.getAllByEntities.name,
        data: {
          entitiesToGet: ['sales', 'customers', 'receivables'],
          replyName: 'fetchCustomers',
        },
      })
    }
    this[salesViewActions.setSearchTermFilter](null)
    this[salesViewActions.setGroupFilter](this.defaultProductsFilter)
    if (this.isScannerActive === false) this[appActions.updateScannerStatus]()
    rendererEventsService.subscribe('sales-menu-channel', (event, arg) => {
      switch (arg) {
        case 'sales-scan':
          this[appActions.updateScannerStatus]()
          this[salesViewActions.setGroupFilter](
            this.isScannerActive ? this.defaultProductsFilter : 'search'
          )
          !this.isScannerActive
            ? this.searchInput.focus()
            : this.searchInput.blur()
          this[salesViewActions.setSearchTermFilter](null)
          this.$root.$emit('reset')
          this[salesViewActions.setSuperCategoriesFilter]([])
          break
      }
    })
    this.$root.$on('enable-scanner', () =>
      this.$barcodeScanner.init(this.onBarcodeScanned)
    )
    rendererEventsService.subscribe(
      MLP_DB_API_EVENTS.replyChannel,
      this.mlpApiListener
    )
    if (this.showScanYourProductsDialog && !this.tourEnabled) {
      rendererEventsService.subscribe(
        USER_INFORMATION_DB_API_EVENTS.replyChannel,
        this.userInformationApiListener
      )
      this[salesViewActions.setScanYourProductsDialogStatus](true)
      rendererEventsService.send(USER_INFORMATION_DB_API_EVENTS.channel, {
        event:
          USER_INFORMATION_DB_API_EVENTS.events
            .updateScanYourProductsDialogCounter.name,
        data: { stopShow: false },
      })
    }
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners('sales-menu-channel')
    rendererEventsService.removeListener(
      ENTITIES_EVENTS.replyChannel,
      this.entitiesListener
    )
    rendererEventsService.removeListener(
      MLP_DB_API_EVENTS.replyChannel,
      this.mlpApiListener
    )
    rendererEventsService.removeListener(
      USER_INFORMATION_DB_API_EVENTS.replyChannel,
      this.userInformationApiListener
    )
  },
  destroyed() {
    this.$root.$off('productAddedFromMatch', this.onBarcodeScanned)
    this.$barcodeScanner.destroy()
    this[salesViewActions.setSuperCategoriesFilter]([])
  },
}
</script>

<style lang="scss" scoped>
.sales-view {
  height: 100%;
  .sales-view__view__tickets-tabs {
    background-color: var(--v-viewBackground-base);
  }
}
</style>
