<template>
  <DialogCard :config="dialogConfig.dialogData">
    <Form :config="dialogConfig" />
  </DialogCard>
</template>

<script>
import uniqid from 'uniqid'
import { find, isNil } from 'ramda'
import { mapActions, mapState } from 'vuex'

import priceFrom from '@/config/itemAddedFrom'

import { getNow } from '@/tools/dates'
import { cleanObjectObserver } from '@/tools/data'
import { formatNumberFromDb, formatNumberToDb } from '@/tools/numbersFormat'

import salesActions from '@/store/sales/actions.types'
import salesViewActions from '@/store/salesView/actions.types'

import setConfig from '@/components/SalesView/MultiSalesTabs/GenericProductDialog/config'
import DialogCard from '@/components/shared/DialogCard'
import Form from '@/components/shared/Form'

export default {
  name: 'GenericProductDialog',
  components: { DialogCard, Form },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
      isEditForm: false,
    }
  },
  computed: {
    ...mapState('salesView', [
      'genericProductDialog',
      'currentSale',
      'selectedProduct',
    ]),
    ...mapState('sales', ['sales']),
    ...mapState('app', ['defaultProductsFilter']),
    dialogConfig() {
      return setConfig(
        {
          isOpen: this.genericProductDialog.isOpen,
          genericName:
            this.genericProductDialog.product != null &&
            'name' in this.genericProductDialog.product
              ? this.genericProductDialog.product.name
              : '',
          inputs: this.inputs,
          v: this.$v.inputs,
          isEditForm: this.isEditForm,
        },
        {
          closeDialog: () => this.closeDialog(),
          addToCurrentSale: () => this.addToCurrentSale(),
        }
      )
    },
  },
  methods: {
    initAmount() {},
    ...mapActions('salesView', [
      salesViewActions.toggleGenericProductDialogStatus,
      salesViewActions.setGroupFilter,
      salesViewActions.setSuperCategoriesFilter,
      salesViewActions.setSelectedProduct,
    ]),
    ...mapActions('sales', [
      salesActions.addProductToCurrentSale,
      salesActions.updateProductFromSale,
    ]),
    setProperties: function() {
      this.dialogConfig.fields.forEach(field => {
        this.$set(this.inputs, field.id, '')
        if (field.validators)
          this.$set(this.validators.inputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
      })
    },
    addToCurrentSale() {
      const productExistsInTicket = !isNil(this.selectedProduct)
        ? find(item => item.uniqueId === this.selectedProduct.product.uniqueId)(
            this.sales[this.currentSale.saleIndex].items
          )
        : false
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Sales',
        screen: 'GenericProductDialog',
        name: `${productExistsInTicket ? 'Edit' : 'Add'} generic product`,
      })
      const newProduct = this.genericProductDialog.product

      if (this.$v.inputs.$invalid) {
        Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$touch())
        return
      }

      if (!productExistsInTicket) {
        this[salesActions.addProductToCurrentSale]({
          currentSale: this.currentSale.saleIndex,
          product: {
            uniqueId: uniqid(),
            id: newProduct.id,
            stock: newProduct.quantity,
            isGramaje: 0,
            isOpenProduct: 0,
            isGeneric: 1,
            name: newProduct.name,
            quantity: 1,
            unitPrice: formatNumberToDb(this.inputs.amount),
            cost: newProduct.cost,
            upc: newProduct.upc,
            timeAdded: getNow(false),
            priceFrom: priceFrom.FROM_PRICE,
            levelWarning: newProduct.levelWarning,
            promotionTypeId: 0,
          },
        })
      } else {
        this[salesActions.updateProductFromSale]({
          ticketIndex: this.selectedProduct.ticketIndex,
          newData: {
            unitPrice: formatNumberToDb(this.inputs.amount),
            uniqueId: this.selectedProduct.product.uniqueId,
          },
        })
      }
      this.closeDialog()
      this.initStatus()
    },
    closeDialog() {
      Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$reset())
      Object.keys(this.inputs).forEach(key => (this.inputs[key] = ''))
      this[salesViewActions.toggleGenericProductDialogStatus]()
      this.initStatus()
    },
    initStatus() {
      this.$root.$emit('reset')
      this[salesViewActions.setGroupFilter](this.defaultProductsFilter)
      this[salesViewActions.setSuperCategoriesFilter]([])
      this[salesViewActions.setSelectedProduct](null)
    },
  },
  validations() {
    return this.validators
  },
  mounted() {
    this.$barcodeScanner.destroy()
    this.setProperties()
    this.isEditForm = !isNil(this.selectedProduct)
    this.inputs.amount =
      !isNil(this.selectedProduct) && this.isEditForm === true
        ? formatNumberFromDb(this.selectedProduct.product.unitPrice)
        : ''
  },
  beforeDestroy() {
    this.$root.$emit('enable-scanner', {})
  },
}
</script>
