<template>
  <div>
    <p class="mb-0 font-weight-medium black--text">
      <v-icon color="black" small>mdi mdi-food</v-icon>
      {{
        getTranslatedText(
          'customPromotionsView.inSale.dialogPromotion.combo.title'
        )
      }}
    </p>
    <p>
      {{
        getTranslatedText(
          'customPromotionsView.inSale.dialogPromotion.combo.info'
        )
      }}
    </p>
    <ScrollContainer height="auto" max-height="150px">
      <v-list-item
        v-for="promotion in promotions"
        :key="promotion.id"
        class="px-0 justify-space-between d-flex"
      >
        <v-list-item-title class="combo-list">
          <div class="pr-4">
            <p class="mb-0">{{ promotion.promotions.firstProduct.name }}</p>
            <p class="mb-0">{{ promotion.promotions.secondProduct.name }}</p>
          </div>
          <p class="mb-0 text-right font-weight-bold">
            {{ formatNumberFromDbToCurrency(promotion.promotions.total) }}
          </p>
        </v-list-item-title>
        <v-list-item-action>
          <v-btn
            class="add-button"
            color="primary"
            small
            text
            @click="addCombo(promotion)"
          >
            {{
              getTranslatedText(
                'customPromotionsView.inSale.dialogPromotion.combo.add'
              )
            }}
          </v-btn>
        </v-list-item-action>
      </v-list-item>
    </ScrollContainer>
  </div>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import { getTranslatedText } from '@/tools/data'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'
import { comboPromotion } from '@/tools/customPromotions'
import productsTools from '@/tools/products'

import salesActions from '@/store/sales/actions.types'

import ScrollContainer from '@/components/shared/ScrollContainer'

export default {
  name: 'ComboList',
  components: { ScrollContainer },
  props: {
    ticketIndex: {
      type: Number,
      required: true,
    },
    promotions: {
      type: Array,
      required: true,
    },
  },
  computed: {
    ...mapState('sales', ['sales']),
    ...mapState('salesView', ['listProductPromotionsDialog']),
    ...mapState('products', {
      products: state => state.data.products,
    }),
  },
  methods: {
    ...mapActions('sales', [salesActions.addProductToCurrentSale]),
    formatNumberFromDbToCurrency,
    getTranslatedText,
    addCombo(promotion) {
      let comboAdded = false
      comboPromotion.getProductsKey().forEach(key => {
        if (comboAdded) return
        if (this.productExistInSale(promotion, key)) {
          this[salesActions.addProductToCurrentSale]({
            currentSale: this.ticketIndex,
            product: productsTools.getProductForSale(
              {
                ...promotion.promotions[comboPromotion.getAnotherKey(key)],
                factorSalesBy:
                  promotion.promotions[comboPromotion.getAnotherKey(key)]
                    .factor > 0
                    ? 0
                    : 2,
              },
              this.products
            ),
          })
          comboAdded = true
        }
      })
      if (comboAdded) return
      comboPromotion.getProductsKey().forEach(key => {
        this[salesActions.addProductToCurrentSale]({
          currentSale: this.ticketIndex,
          product: productsTools.getProductForSale(
            {
              ...promotion.promotions[key],
              factorSalesBy: promotion.promotions[key].factor > 0 ? 0 : 2,
            },
            this.products
          ),
        })
      })
    },
    productExistInSale(promotion, key) {
      return (
        promotion.promotions[key].id ===
          this.listProductPromotionsDialog.product.id &&
        this.sales[this.ticketIndex].items.some(
          item => item.id === promotion.promotions[key].id
        )
      )
    },
  },
}
</script>

<style scoped lang="scss">
.combo-list {
  display: grid;
  grid-template-columns: 75% 20%;
  gap: 6px;
  align-items: center;
  > div > p {
    text-overflow: ellipsis;
    white-space: nowrap;
    overflow: hidden;
    max-width: 100%;
    box-sizing: border-box;
  }
}
.add-button {
  border-radius: 10px;
  padding: 0 8px;
  margin: 0 12px 0 0;
}
</style>
