import AIRTIME_EVENTS from '@/config/events/airtime'
import betaTester, { useFeature } from '@/config/betaTesters'

import rendererEventsService from '@/services/renderer/rendererEvents'

const config = (state, methods) => ({
  state,
  methods,
  groupClass: 'pr-4',
  groups: [
    {
      id: 'filters-group-01',
      controls: [
        {
          id: 'search-control',
          type: 'input',
          label: 'productsView.toolbar.searchField.label',
          placeholder: 'productsView.toolbar.searchField.placeholder',
          icon: 'mdi-magnify',
          backgroundColor: 'cardBackgroundSecondary',
          color: 'salesPrimary',
          ref: 'sales-input-search',
          group: 'search',
          onChange: value => methods.onChange(value),
          onEnter: value => methods.onEnter(value),
          onClick: resetSelector => {
            state.isScannerActive === true
              ? methods.updateScannerStatus()
              : null
            resetSelector()
            methods.setGroup('search')
            methods.setSelectedSuperCategories([])
          },
        },
      ],
    },
    {
      id: 'filters-group-02',
      controls: [
        {
          id: 'all-button-control',
          type: 'button',
          label: 'productsView.toolbar.buttons.all',
          icon: 'mdi-view-module',
          group: 'all',
          color:
            state.filters.group === 'all' ? 'accent lighten-1' : 'salesPrimary',
          onClick: (resetSelector, resetSearchTerm) => {
            buttonEffect('all', methods, resetSelector, resetSearchTerm)
          },
        },
        {
          id: 'prices-button-control',
          type: 'button',
          label: 'productsView.toolbar.buttons.generics',
          icon: 'mdi-calculator',
          group: 'generics',
          color:
            state.filters.group === 'generics'
              ? 'accent lighten-1'
              : 'salesPrimary',
          onClick: (resetSelector, resetSearchTerm) => {
            buttonEffect('generics', methods, resetSelector, resetSearchTerm)
          },
        },
        {
          id: 'air-time-button-control',
          type: 'button',
          label: 'productsView.toolbar.buttons.airTime',
          icon: 'mdi-cellphone-charging',
          group: 'air-time',
          color:
            state.filters.group === 'air-time'
              ? 'accent lighten-1'
              : 'salesPrimary',
          onClick: (resetSelector, resetSearchTerm) => {
            buttonEffect('air-time', methods, resetSelector, resetSearchTerm)
            methods.setBalanceFetching(true)
            rendererEventsService.send(AIRTIME_EVENTS.channel, {
              event: AIRTIME_EVENTS.events.getBalance.name,
              data: { posData: state.posData },
            })
          },
          show: useFeature(state.posData, betaTester.airtime),
        },
        // {
        //   id: 'services-button-control',
        //   type: 'button',
        //   label: 'productsView.toolbar.buttons.services',
        //   icon: 'mdi-cellphone',
        //   group: 'services',
        //   color: 'salesPrimary',
        //   onClick: (resetSelector, resetSearchTerm) => {
        //     buttonEffect('services', methods, resetSelector, resetSearchTerm)
        //   },
        // },
        {
          id: 'weight-button-control',
          type: 'button',
          label: 'productsView.toolbar.buttons.byWeight',
          icon: 'mdi-weight',
          group: 'byWeight',
          color:
            state.filters.group === 'byWeight'
              ? 'accent lighten-1'
              : 'salesPrimary',
          onClick: (resetSelector, resetSearchTerm) => {
            buttonEffect('byWeight', methods, resetSelector, resetSearchTerm)
          },
        },
        {
          id: 'favorites-button-control',
          type: 'button',
          label: 'productsView.toolbar.buttons.favorites',
          icon: 'mdi-cards-heart',
          group: 'favorites',
          color:
            state.filters.group === 'favorites'
              ? 'accent lighten-1'
              : 'salesPrimary',
          onClick: (resetSelector, resetSearchTerm) => {
            buttonEffect('favorites', methods, resetSelector, resetSearchTerm)
          },
        },
        {
          id: 'promotions-button-control',
          type: 'button',
          label: 'productsView.toolbar.buttons.promotions',
          icon: 'mdi-sale',
          group: 'promotions',
          color:
            state.filters.group === 'promotions'
              ? 'accent lighten-1'
              : 'salesPrimary',
          onClick: (resetSelector, resetSearchTerm) => {
            buttonEffect('promotions', methods, resetSelector, resetSearchTerm)
          },
        },
      ],
    },
    {
      id: 'filters-group-03',
      controls: [
        {
          id: 'superCategories-select-control',
          type: 'select',
          label: 'productsView.toolbar.selectCategoryField.label',
          group: 'superCategories',
          items: state.data.superCategories,
          stringValueSelected:
            'productsView.toolbar.selectCategoryField.categoriesSelected',
          backgroundColor: 'cardBackgroundSecondary',
          limit: 3,
          width: 285,
          onChange: data => {
            return methods.setSelectedSuperCategories(data)
          },
          onClick: (resetSelector, resetSearchTerm) => {
            buttonEffect(
              'superCategories',
              methods,
              resetSelector,
              resetSearchTerm
            )
          },
        },
      ],
    },
    {
      id: 'filters-group-04',
      controls: [
        {
          id: 'clear-button-control',
          type: 'button',
          label: 'productsView.toolbar.buttons.clear',
          icon: 'mdi-close-circle',
          group: 'clear',
          color: 'salesPrimary',
          onClick: (resetSelector, resetSearchTerm) => {
            buttonEffect('clear', methods, resetSelector, resetSearchTerm)
          },
        },
      ],
    },
  ],
})

const buttonEffect = (group, methods, resetSelector, resetSearchTerm) => {
  group === 'clear' ? methods.setGroup('all') : methods.setGroup(group)
  resetSelector()
  resetSearchTerm()
  methods.setSearchTerm(null)
  methods.setSelectedSuperCategories([])
  methods.resetScannerStatus(group)
}

export default config
