<template>
  <DialogCard :config="dialogConfig.dialogData">
    <div class="d-flex justify-space-between align-center">
      <div>
        <v-img
          :src="require('@/assets/winner-loyalty.svg')"
          alt="Winner loyalty"
          max-height="240"
          max-width="300"
        />
      </div>
      <div class="text-container">
        <FormattedText
          type="text-h6"
          class="pb-2"
          :value="
            getTranslatedText(
              'salesView.prizeWonDialog.message',
              prizeWonDialog.customerName
            )
          "
        />
      </div>
    </div>
  </DialogCard>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import { getTranslatedText } from '@/tools/data'

import salesViewActions from '@/store/salesView/actions.types'

import setConfig from '@/components/SalesView/MultiSalesTabs/PrizeWonDialog/config'
import DialogCard from '@/components/shared/DialogCard'
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'PrizeWonDialog',
  components: { DialogCard, FormattedText },
  computed: {
    ...mapState('salesView', ['prizeWonDialog']),
    dialogConfig() {
      return setConfig(
        {
          isOpen: this.prizeWonDialog.isOpen,
        },
        {
          closeDialog: this.closeDialog,
        }
      )
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('salesView', [salesViewActions.setPrizeWonDialogStatus]),
    closeDialog() {
      this[salesViewActions.setPrizeWonDialogStatus]({
        isOpen: false,
        customerName: '',
      })
    },
  },
}
</script>

<style lang="scss" scoped>
.text-container {
  width: 350px;
  max-width: 350px;
  display: flex;
  flex-direction: column;
  gap: 4em;
}
</style>
