<template>
  <DialogCard :config="dialogConfig.dialogData">
    <div class="d-flex flex-column mt-6">
      <div class="d-flex justify-space-between">
        <v-autocomplete
          v-model="customerId"
          :items="data.customers"
          item-text="name"
          item-value="id"
          rounded
          filled
          flat
          clearable
          hide-details
          color="salesPrimary"
          item-color="salesPrimary"
          class="custom-text-field"
          :label="getTranslatedText('salesView.ticket.client')"
          :placeholder="getTranslatedText('salesView.ticket.search')"
          append-icon="mdi-account-multiple"
        />
        <v-tooltip bottom>
          <template v-slot:activator="{ on }">
            <v-icon
              v-on="on"
              class="ml-4"
              color="salesPrimary"
              @click="openAddNewCustomer"
            >
              mdi-plus
            </v-icon>
          </template>
          <FormattedText
            value="customersView.toolbar.buttons.addCustomer"
            intl
            color="textOverWhiteBackground"
          />
        </v-tooltip>
      </div>
      <CustomerInfo
        v-if="customerId !== null && customerId !== undefined"
        :customer="getCustomer"
        :enrolledCustomer="getEnrolledCustomer"
        class="mt-6"
      />
    </div>
  </DialogCard>
</template>

<script>
import { mapState, mapActions, mapGetters } from 'vuex'

import paymentMethods from '@/config/paymentMethods'

import { formatText, getTranslatedText } from '@/tools/data'

import salesActions from '@/store/sales/actions.types'
import salesViewActions from '@/store/salesView/actions.types'
import customersViewActions from '@/store/customersView/actions.types'

import setConfig from '@/components/SalesView/MultiSalesTabs/AssignCustomerDialog/config'
import DialogCard from '@/components/shared/DialogCard'
import FormattedText from '@/components/shared/FormattedText'
import CustomerInfo from '@/components/shared/CustomerInfo'

export default {
  name: 'AssignCustomerDialog',
  components: { DialogCard, FormattedText, CustomerInfo },
  data() {
    return {
      customerId: null,
      creditEnabled: false,
    }
  },
  computed: {
    ...mapState('sales', ['sales']),
    ...mapState('salesView', ['assignCustomerDialog', 'currentSale']),
    ...mapState('customers', ['data']),
    ...mapGetters('account', ['getLoyaltyProgram']),
    ...mapGetters('loyaltyProgram', ['approvedEnrolledCustomers']),
    getCustomer() {
      if (this.customerId === undefined || this.customerId === null) return ''
      return this.data.customers.find(item => item.id === this.customerId)
    },
    getEnrolledCustomer() {
      if (this.customerId === undefined || this.customerId === null) return ''
      return this.approvedEnrolledCustomers.find(
        item => item.customerId === this.customerId
      )
    },
    dialogConfig() {
      return setConfig(
        {
          opened: this.assignCustomerDialog.isOpen,
        },
        {
          closeDialog: this.closeDialog,
          assignCustomer: this.assignCustomer,
        }
      )
    },
  },
  methods: {
    formatText,
    getTranslatedText,
    ...mapActions('salesView', [
      salesViewActions.setAssignCustomerDialogStatus,
    ]),
    ...mapActions('sales', [
      salesActions.updateCustomerSelected,
      salesActions.updatePayOptionStatus,
    ]),
    ...mapActions('customersView', [
      customersViewActions.setAddCustomerDialogStatus,
    ]),
    openAddNewCustomer() {
      this[customersViewActions.setAddCustomerDialogStatus](true)
    },
    closeDialog() {
      var customerId =
        this.sales[this.currentSale.saleIndex].customer !== ''
          ? this.sales[this.currentSale.saleIndex].customer.id
          : null
      this[salesActions.updatePayOptionStatus]({
        ticketIndex: this.currentSale.saleIndex,
        option:
          this.creditEnabled === true &&
          customerId !== undefined &&
          customerId !== null
            ? paymentMethods.creditKey
            : paymentMethods.cashKey,
      })
      this[salesViewActions.setAssignCustomerDialogStatus](false)
    },
    assignCustomer() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Sales',
        screen: 'TicketFooter',
        name: 'Assign client for credit sale',
      })
      this[salesActions.updateCustomerSelected]({
        customer: this.getCustomer,
        enrolledCustomer: this.getEnrolledCustomer,
        ticketIndex: this.currentSale.saleIndex,
      })
      this[salesActions.updatePayOptionStatus]({
        ticketIndex: this.currentSale.saleIndex,
        option:
          this.creditEnabled === true &&
          this.customerId !== undefined &&
          this.customerId !== null
            ? paymentMethods.creditKey
            : paymentMethods.cashKey,
      })
      this[salesViewActions.setAssignCustomerDialogStatus](false)
    },
  },
  mounted() {
    this.customerId =
      this.sales[this.currentSale.saleIndex].customer !== ''
        ? this.sales[this.currentSale.saleIndex].customer.id
        : null
    this.creditEnabled = paymentMethods.isCreditSale(
      this.sales[this.currentSale.saleIndex].payOption
    )
    this.$root.$on(
      'customerAdded',
      customerId => (this.customerId = customerId)
    )
  },
}
</script>

<style lang="scss" scoped>
.customer-item {
  border-bottom-style: solid;
  border-bottom-color: var(--v-secondary-base);
  border-bottom-width: 0.5px;
}
</style>
