<template>
  <v-container fluid fill-height class="multi-sales pa-0" id="multi-sales">
    <!-- Floating toolbar -->
    <div class="multi-sales__floating-toolbar">
      <v-btn
        fab
        absolute
        dark
        top
        left
        small
        elevation="0"
        color="primary"
        class="mt-12 multi-sales__floating-toolbar__add"
        v-track:click="{
          category: 'Sales',
          screen: 'SaleTabs',
          name: 'Add ticket',
        }"
        @click="addTicket"
      >
        <v-icon>mdi-plus</v-icon>
      </v-btn>
    </div>
    <!-- Multi sales tabs -->
    <v-row no-gutters>
      <v-col class="multi-sales__tabs" id="multi-sales__tabs">
        <v-tabs
          v-model="currentSaleIndex"
          icons-and-text
          color="primary"
          background-color="mainBackground"
          ref="tabsComponent"
          @change="changeSlideWidth()"
        >
          <v-tab
            v-for="(sale, index) in sales"
            :key="`${sale.name}${sale.ticketId}`"
            ref="saleTab"
            class="multi-sales__tab"
            @mouseover="hoverTabIndex = index"
            @mouseleave="hoverTabIndex = null"
          >
            <SaleTab
              :sale="sale"
              :hover="hoverTabIndex === index"
              @nameWasEdited="changeSlideWidth()"
            />
          </v-tab>
        </v-tabs>
      </v-col>
    </v-row>
    <div id="current-sale-container" style="width: 100%">
      <!-- Products filter toolbar -->
      <v-row no-gutters>
        <v-col
          class="multi-sales__filter-toolbar px-6 pt-6"
          id="multi-sales__filter-toolbar"
        >
          <ProductsFilterToolbar />
        </v-col>
      </v-row>
      <!-- Sales data container -->
      <v-row
        no-gutters
        class="multi_sales__data-container"
        :style="{
          height: `calc(100vh - ${getProductListStyles}px)`,
        }"
      >
        <!-- Products list -->
        <v-col
          :cols="columns.products"
          id="multi-sales__products-list"
          class="multi-sales__products-list fill-height"
        >
          <ProductsList />
        </v-col>
        <!-- Ticket tab -->
        <v-col :cols="columns.ticket" class="multi-sales__ticket pr-6">
          <v-tabs-items
            v-model="currentSaleIndex"
            style="width: 100%; height:100%;"
          >
            <v-tab-item v-for="sale in sales" :key="sale.ticketId">
              <Ticket
                :ticketIndex="currentSaleIndex"
                :ticketCols="columns.ticket"
                :saleId="sale.ticketId"
              />
            </v-tab-item>
          </v-tabs-items>
        </v-col>
        <!-- Delete confirmation Dialog -->
        <DeleteDialogConfirmation v-if="deleteConfirmationDialog.isOpen" />
        <!-- Generic product Dialog -->
        <GenericProductDialog v-if="genericProductDialog.isOpen" />
        <!-- Grammage Product Dialog -->
        <ByWeightProductDialog v-if="byWeightProductDialog.isOpen" />
        <!-- Assign customer dialog -->
        <AssignCustomerDialog v-if="assignCustomerDialog.isOpen" />
        <!-- Add new product when it does not exist in the MLP  -->
        <AddNewProductDialog v-if="newProductDialog.isOpen" />
        <!-- Add new airtime product -->
        <AirtimeProductDialog v-if="airtimeProductDialog.isOpen" />
        <!-- Customer over credit limit dialog -->
        <OverCreditLimitDialog
          v-if="overCreditLimitDialog.isOpen"
          :paySaleCallback="finishSelectedSale"
        />
        <!-- Cash change dialog -->
        <FinishSaleDialog
          :finalPrice="
            formatNumberFromDb(
              sales[currentSaleIndex] === undefined
                ? 0
                : getPriceWithPromotion()
            )
          "
          :paySaleCallback="finishSelectedSale"
          :fromPayButton="finishSaleDialog.fromPayButton"
        />
        <!-- Prize won dialog -->
        <PrizeWonDialog v-if="prizeWonDialog.isOpen" />
      </v-row>
    </div>
    <SalesViewTour />
  </v-container>
</template>

<script>
import { mapActions, mapGetters, mapState } from 'vuex'
import { last, findIndex, propEq, isNil } from 'ramda'

import { testMode } from '@/config/env'
import STORE_INVENTORY_DB_API_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'
import SALES_DB_API_EVENTS from '@/config/events/databaseAPI/salesEvents'
import PRINTER_EVENTS from '@/config/events/printer'
import ENROLLED_CUSTOMERS_DB_API_EVENTS from '@/config/events/databaseAPI/enrolledCustomersEvents'
import paymentMethods from '@/config/paymentMethods'
import { loyaltyNotificationType } from '@/config/loyaltyProgram'
import { promotions } from '@/config/promotions'

import { getAppLayoutHeaderAndFooterHeight } from '@/tools/view'
import {
  formatNumberFromDb,
  formatNumberFromDbToCurrency,
  formatNumberToDb,
  roundToNearestMultiple,
} from '@/tools/numbersFormat'
import { getTranslatedText, getTruncatedText } from '@/tools/data'
import { getTotalProductPrice } from '@/tools/ticket'
import {
  discountTypes,
  getPromotionTicketToDB,
  getTotalTicketWithPromotion,
} from '@/tools/promotions'
import salesTools from '@/tools/sales'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'
import audioService from '@/services/renderer/audio'

import productsActions from '@/store/products/actions.types'
import salesActions from '@/store/sales/actions.types'
import salesViewActions from '@/store/salesView/actions.types'
import appActions from '@/store/app/actions.types'
import usersViewActions from '@/store/usersView/actions.types'
import loyaltyProgramActions from '@/store/loyaltyProgram/actions.types'

import ProductsFilterToolbar from '@/components/SalesView/MultiSalesTabs/ProductsFilterToolBar'
import ProductsList from '@/components/SalesView/MultiSalesTabs/ProductsList'
import Ticket from '@/components/SalesView/MultiSalesTabs/Ticket'
import DeleteDialogConfirmation from '@/components/SalesView/MultiSalesTabs/DeleteConfirmationDialog'
import GenericProductDialog from '@/components/SalesView/MultiSalesTabs/GenericProductDialog'
import ByWeightProductDialog from '@/components/SalesView/MultiSalesTabs/ByWeightProductDialog'
import AssignCustomerDialog from '@/components/SalesView/MultiSalesTabs/AssignCustomerDialog'
import AddNewProductDialog from '@/components/AddNewProductDialog'
import AirtimeProductDialog from '@/components/SalesView/MultiSalesTabs/AitimeProductsDialog'
import OverCreditLimitDialog from '@/components/SalesView/MultiSalesTabs/OverCreditLimitDialog'
import FinishSaleDialog from '@/components/SalesView/MultiSalesTabs/FinishSaleDialog'
import PrizeWonDialog from '@/components/SalesView/MultiSalesTabs/PrizeWonDialog'
import SaleTab from '@/components/SalesView/MultiSalesTabs/SaleTab'
import SalesViewTour from '@/components/SalesView/SalesViewTour'

export default {
  name: 'MultiSalesTabs',
  components: {
    SalesViewTour,
    SaleTab,
    ProductsList,
    ProductsFilterToolbar,
    Ticket,
    DeleteDialogConfirmation,
    GenericProductDialog,
    ByWeightProductDialog,
    AssignCustomerDialog,
    AddNewProductDialog,
    AirtimeProductDialog,
    OverCreditLimitDialog,
    FinishSaleDialog,
    PrizeWonDialog,
  },
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      currentSaleIndex: 0,
      layoutCommonElementsHeight: 0,
      columns: {
        products: 8,
        ticket: 4,
      },
      finishingSale: false,
      hoverTabIndex: null,
    }
  },
  computed: {
    ...mapState('app', [
      'windowSize',
      'pendingSyncOps',
      'printTicketDefault',
      'addMarginTicket',
    ]),
    ...mapState('usersView', ['selectedUser', 'estimatedCash']),
    ...mapState('sales', ['sales']),
    ...mapState('account', { accountData: state => state.data }),
    ...mapState('salesView', [
      'deleteConfirmationDialog',
      'byWeightProductDialog',
      'assignCustomerDialog',
      'genericProductDialog',
      'newProductDialog',
      'currentSale',
      'airtimeProductDialog',
      'overCreditLimitDialog',
      'finishSaleDialog',
      'filters',
      'prizeWonDialog',
      'paymentProvidersByType',
      'productDetailDialog',
      'tourEnabled',
    ]),
    ...mapState('products', {
      productStored: state => state.data.products,
    }),
    ...mapGetters('account', ['getCountry']),
    getProductListStyles() {
      return this.layoutCommonElementsHeight
    },
  },
  methods: {
    formatNumberFromDb,
    getTranslatedText,
    getTruncatedText,
    ...mapActions('app', [
      appActions.addPendingSyncOperation,
      appActions.setAppSyncing,
    ]),
    ...mapActions('salesView', [
      salesViewActions.setCurrentSale,
      salesViewActions.setGroupFilter,
      salesViewActions.setSuperCategoriesFilter,
      salesViewActions.setSearchTermFilter,
      salesViewActions.setSaleStatus,
      salesViewActions.finishSale,
      salesViewActions.setPrizeWonDialogStatus,
    ]),
    ...mapActions('sales', [
      salesActions.addSale,
      salesActions.removeSale,
      salesActions.resetSale,
      salesActions.updateProductsFieldsFromAllSales,
    ]),
    ...mapActions('products', [productsActions.editProductField]),
    ...mapActions('usersView', [usersViewActions.setSelectedUserHasSales]),
    ...mapActions('loyaltyProgram', [
      loyaltyProgramActions.updateEnrolledCustomer,
    ]),
    addTicket() {
      const newTicketId = this.getNewTicketId()
      this[salesActions.addSale]({
        ticketId: newTicketId,
        items: [],
        print: this.printTicketDefault,
        payOption: paymentMethods.cashKey,
        paySubOption: paymentMethods.cashKey,
        others: [],
        customer: '',
        enrolledCustomer: '',
        promotion: 0,
        promotions: [],
        promotion_type: discountTypes.percent,
        promotionTicketId: promotions.NONE,
        cashAmount: 0,
        name: `Ticket ${newTicketId}`,
      })
      this.$root.$emit('reset')
      this[salesViewActions.setGroupFilter]('all')
      this[salesViewActions.setSuperCategoriesFilter]([])
      this[salesViewActions.setSearchTermFilter](null)
    },
    removeTicket(ticket) {
      const ticketIndex = this.findTicketIndex(ticket)
      this[salesActions.removeSale](ticketIndex)
    },
    getNewTicketId() {
      const lastTicket = last(this.sales)
      return lastTicket.ticketId + 1
    },
    findTicketIndex(ticket) {
      return findIndex(propEq('ticketId', ticket))(this.sales)
    },
    getLayoutHeight() {
      const layoutComponentsHeight = getAppLayoutHeaderAndFooterHeight(
        'sales-view'
      )
      const multiSalesTabHeight = document.getElementById('multi-sales__tabs')
        .offsetHeight
      const multiSalesFilterToolbarHeight = document.getElementById(
        'multi-sales__filter-toolbar'
      ).offsetHeight

      this.layoutCommonElementsHeight =
        layoutComponentsHeight +
        multiSalesTabHeight +
        multiSalesFilterToolbarHeight
    },
    getSalesDataContainerColumns(value) {
      if (value <= 1280) return (this.columns = this.config.columns.half)
      if (value <= 1800) return (this.columns = this.config.columns.fifth)
      return (this.columns = this.config.columns.third)
    },
    updateCurrentSaleIndex() {
      this.currentSaleIndex = this.sales.length - 1
    },
    finishSelectedSale() {
      if (this.finishingSale === true || this.currentSale.isFinished === true)
        return
      this.finishingSale = true
      this[salesViewActions.setSaleStatus](true)
      this.$loading.show('finishSale')
      this.$root.$emit('finish-sale')
      const { items, totalPrice } = salesTools.getTotalPriceAndItemsWithCombos(
        this.sales[this.currentSaleIndex],
        this.getPrice(this.sales[this.currentSaleIndex].items),
        this.productStored
      )
      rendererEventsService.send(SALES_DB_API_EVENTS.channel, {
        event: SALES_DB_API_EVENTS.events.finishSale.name,
        data: {
          saleData: {
            ...this.sales[this.currentSaleIndex],
            promotion: getPromotionTicketToDB({
              ...this.sales[this.currentSaleIndex],
              cost: this.getPrice(this.sales[this.currentSaleIndex].items),
            }),
            items,
          },
          userId: this.selectedUser.id,
          username: this.selectedUser.name,
          totalPrice,
          estimatedCash: this.getEstimatedCash(),
          loyaltyProgram: this.accountData.loyaltyProgram,
          cashOpExtraInfo: this.getSaleCashOpExtraInfo(
            this.sales[this.currentSaleIndex].payOption,
            this.sales[this.currentSaleIndex].paySubOption
          ),
        },
      })
    },
    getSaleCashOpExtraInfo(payOption, paySubOption) {
      if (!paymentMethods.isExternalPaymentSale(payOption)) return null
      const providerFound = this.paymentProvidersByType[payOption].find(
        provider => provider.id === paySubOption
      )
      if (!providerFound) return null
      if (!paymentMethods.defaultPaymentMethods.includes(payOption)) {
        return providerFound.label
      }
      return `${this.getTranslatedText(`salesView.ticket.${payOption}`)} (${
        providerFound.label
      })`
    },
    getPrice(products) {
      const total = products.reduce(
        (total, product) =>
          total +
          getTotalProductPrice(
            {
              ...product,
              unitPrice: salesTools.getProductPrice(
                this.sales[this.currentSaleIndex],
                product
              ),
            },
            'unitPrice'
          ),
        0
      )
      const totalCombos = this.getTotalComboPromotions()
      return roundToNearestMultiple(parseInt((total + totalCombos).toFixed(0)))
    },
    getTotalComboPromotions() {
      return this.sales[this.currentSaleIndex].promotions.reduce(
        (total, promo) => {
          total += promo.quantity * promo.promotions.total
          return total
        },
        0
      )
    },
    getPriceWithPromotion() {
      const totalProductsPrice = getTotalTicketWithPromotion(
        this.getPrice,
        this.sales[this.currentSaleIndex]
      )
      return parseInt(totalProductsPrice).toFixed(0)
    },
    getEstimatedCash() {
      const stateEstimatedCash =
        this.estimatedCash === null || this.estimatedCash === undefined
          ? 0
          : this.estimatedCash
      return formatNumberToDb(stateEstimatedCash)
    },
    async onSaleFinished(data) {
      this.$root.$emit('setSaleTicketDate', data.creationDate)
      await this[appActions.addPendingSyncOperation]()
      if (!this.selectedUser.hasSales)
        this[usersViewActions.setSelectedUserHasSales](true)
      if (this.sales[this.currentSaleIndex].print) {
        rendererEventsService.send(PRINTER_EVENTS.channel, {
          event: PRINTER_EVENTS.events.printSale.name,
          data: {
            ticketToPrint: document.getElementById('ticket-to-print').innerHTML,
            addMarginTicket: this.addMarginTicket,
          },
        })
      }
      if (this.accountData.loyaltyProgram.loyaltyProgramActived) {
        this.onLoyaltyProgramActived(data)
      }
      this.$root.$emit('sendOpsToSync')
      this[salesViewActions.finishSale](data)
      this.finishingSale = false
      audioService.play('beep')
      if (!this.tourEnabled) {
        notificationsService.showSuccess(
          paymentMethods.isOwnerSale(
            this.sales[this.currentSaleIndex].payOption
          )
            ? 'notification.sales.saleOwner'
            : 'notification.sales.saleConfirmed',
          this.$vuetify.lang,
          { timeout: 5000 },
          [formatNumberFromDbToCurrency(data.totalPrice)]
        )
        this.showWarningItems(data)
      }
      this[salesActions.resetSale]({
        customer: data.customer,
        ticketIndex: this.currentSaleIndex,
      })
      this[salesActions.updateProductsFieldsFromAllSales](data.itemsToUpdate)
    },
    onLoyaltyProgramActived(data) {
      const {
        enrolledCustomer,
        notification,
        multiplePrize,
        oldAwardAmount,
        totalPrice,
      } = data
      if (isNil(enrolledCustomer)) return
      this[loyaltyProgramActions.updateEnrolledCustomer](enrolledCustomer)
      if (notification.send) {
        rendererEventsService.send(ENROLLED_CUSTOMERS_DB_API_EVENTS.channel, {
          event: ENROLLED_CUSTOMERS_DB_API_EVENTS.events.sendNotification.name,
          data: {
            notification,
            enrolledCustomer,
            totalPriceFormatted: formatNumberFromDb(totalPrice),
            amountFormatted: formatNumberFromDb(enrolledCustomer.amount),
            amountPendingFormatted: formatNumberFromDb(
              enrolledCustomer.amountPending
            ),
            oldAwardAmountFormatted: formatNumberFromDb(oldAwardAmount),
            securityData: this.accountData.security,
            phoneCode: this.getCountry.phoneCode,
            storeName: this.accountData.storeName,
          },
        })
        if (notification.notificationType === loyaltyNotificationType.WINNER) {
          if (multiplePrize > 1) {
            notificationsService.showInfo(
              'notification.sales.multiplePrize',
              this.$vuetify.lang,
              { timeout: 7000 },
              [multiplePrize]
            )
          }
          this[salesViewActions.setPrizeWonDialogStatus]({
            isOpen: true,
            customerName: getTruncatedText(enrolledCustomer.customer.name, 20),
          })
        }
      }
    },
    showWarningItems(data) {
      if (data.itemsToWarn.length > 0) {
        const productsNames = []
        data.itemsToWarn.forEach(item => productsNames.push(item.name))
        notificationsService.showWarning(
          'notification.sales.itemsToWarnMsg',
          this.$vuetify.lang,
          { timeout: 7000 },
          [productsNames.join(', ')]
        )
      }
      if (data.itemsWithoutStock.length > 0) {
        const productsNames = []
        data.itemsWithoutStock.forEach(item => productsNames.push(item.name))
        notificationsService.showError(
          'notification.sales.itemsWithoutStockMsg',
          this.$vuetify.lang,
          { timeout: 9000 },
          [productsNames.join(', ')]
        )
      }
    },
    createSynchronizationUpdateStock(event, payload) {
      const updateByIdReplies =
        STORE_INVENTORY_DB_API_EVENTS.events.updateById.replies
      const replies = {
        [`${updateByIdReplies.success}`]: () => {
          if (!this.productDetailDialog.isOpen) {
            this[productsActions.editProductField](payload.data)
          }
          this.$root.$emit('productWasEdited', payload.data._id)
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    enrolledCustomerListener(event, payload) {
      const events = ENROLLED_CUSTOMERS_DB_API_EVENTS.events
      const replies = {
        [events.sendNotification.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'send_notification',
            category: 'Sales',
            screen: 'SaleTicket',
            name: 'Update enrolled customer',
          })
          const { enrolledCustomer } = payload.data
          this[loyaltyProgramActions.updateEnrolledCustomer](enrolledCustomer)
          if (
            enrolledCustomer.notificationType === loyaltyNotificationType.WINNER
          ) {
            notificationsService.showSuccess(
              'notification.sales.sendPrizeNotificationSuccess',
              this.$vuetify.lang
            )
          }
        },
        [events.sendNotification.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Sales',
            screen: 'SaleTicket',
            name: 'Error sending notification',
          })
          notificationsService.showError(
            'notification.sales.sendPrizeNotificationError',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    changeSlideWidth() {
      setTimeout(() => {
        if (
          this.currentSaleIndex >= 0 &&
          this.$refs.saleTab[this.currentSaleIndex]
        ) {
          this.$refs.tabsComponent.slider.width = this.$refs.saleTab[
            this.currentSaleIndex
          ].$el.offsetWidth
        }
      }, 300)
    },
    finishSaleListener(event, payload) {
      const events = SALES_DB_API_EVENTS.events
      const replies = {
        [events.finishSale.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'response',
            category: 'Sales',
            screen: 'SaleTicket',
            name: 'Finish sale',
          })
          this.$loading.hide()
          this.onSaleFinished(payload.data)
        },
        [events.finishSale.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Sales',
            screen: 'SaleTicket',
            name: 'Error finishing sale',
          })
          this.$loading.hide()
          notificationsService.showError(
            payload.data.errorMsg,
            this.$vuetify.lang
          )
          this[salesViewActions.setSaleStatus](false)
          this.finishingSale = false
        },
      }
      if (payload.event in replies) replies[payload.event]()
      this.$loading.hide()
    },
  },
  watch: {
    'windowSize.x': function(value) {
      this.getSalesDataContainerColumns(value)
      this.getSalesDataContainerColumns(value)
    },
    sales() {
      setTimeout(() => {
        this.updateCurrentSaleIndex()
      }, 10)
    },
    currentSaleIndex(value) {
      this.setCurrentSale(value)
    },
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      STORE_INVENTORY_DB_API_EVENTS.replyChannel,
      this.createSynchronizationUpdateStock
    )
    rendererEventsService.subscribe(
      SALES_DB_API_EVENTS.replyChannel,
      this.finishSaleListener
    )
    rendererEventsService.subscribe('sales-menu-channel', (event, arg) => {
      switch (arg) {
        case 'pay-sale':
          this.$root.$emit(
            `click-pay-sale-${this.sales[this.currentSaleIndex].ticketId}`
          )
          break
      }
    })
    rendererEventsService.subscribe(
      ENROLLED_CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.enrolledCustomerListener
    )
  },
  mounted() {
    this.getLayoutHeight()
    this.getSalesDataContainerColumns(this.windowSize.x)
    this.currentSaleIndex = this.currentSale.saleIndex
    this.changeSlideWidth()
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      STORE_INVENTORY_DB_API_EVENTS.replyChannel,
      this.createSynchronizationUpdateStock
    )
    rendererEventsService.removeListener(
      SALES_DB_API_EVENTS.replyChannel,
      this.finishSaleListener
    )
    rendererEventsService.removeListener(
      ENROLLED_CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.enrolledCustomerListener
    )
  },
}
</script>

<style lang="scss" scoped>
.multi-sales {
  .multi-sales__floating-toolbar {
    .multi-sales__floating-toolbar__add {
      left: 26px;
    }
    .multi-sales__floating-toolbar__help {
      right: 26px;
    }
  }
  .multi-sales__tabs {
    padding: 0 80px;
  }
  .multi-sales__tab {
    min-width: 100px;
  }
  .multi-sales__filter-toolbar {
    background: var(--v-mainBackground-base);
  }
  .multi-sales__ticket {
    :deep(.v-window-item) {
      height: 100%;
    }
  }
}
</style>
