<template>
  <div class="position-relative">
    <v-chip
      color="primary"
      small
      label
      class="chip-position"
      v-if="enrolledCustomer"
    >
      <FormattedText
        intl
        color="white"
        value="customersView.customerCard.enrolledCustomer"
      />
    </v-chip>
    <v-alert
      class="ma-0 pa-5"
      text
      color="salesPrimary"
      style="border-radius: 8px"
    >
      <div class="d-flex">
        <v-icon color="salesPrimary">mdi-account</v-icon>
        <div class="d-flex flex-column ml-5">
          <FormattedText
            intl
            type="text-body-2"
            color="salesPrimary"
            value="customersView.customerCard.selectedCustomer"
          />
          <FormattedText
            type="text-h6"
            color="salesPrimary"
            :value="customer.name"
          />
        </div>
        <div class="d-flex ml-auto">
          <div class="d-flex flex-column">
            <FormattedText
              intl
              type="text-body-2"
              color="salesPrimary"
              value="customersView.customerCard.debt"
            />
            <FormattedText
              type="text-h6"
              :color="customer.debt > 0 ? 'customerDebt' : 'salesPrimary'"
              :value="formatNumberFromDbToCurrency(customer.debt)"
            />
          </div>
          <div class="d-flex flex-column ml-6">
            <FormattedText
              intl
              type="text-body-2"
              color="salesPrimary"
              value="customersView.customerCard.limit"
            />
            <FormattedText
              type="text-h6"
              color="salesPrimary"
              :value="
                customer.debtLimit > 0
                  ? formatNumberFromDbToCurrencyWithoutDecimals(
                      customer.debtLimit
                    )
                  : '-'
              "
            />
          </div>
        </div>
      </div>
    </v-alert>
  </div>
</template>

<script>
import {
  formatNumberFromDbToCurrency,
  formatNumberFromDbToCurrencyWithoutDecimals,
} from '@/tools/numbersFormat'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'CustomerInfo',
  components: { FormattedText },
  props: {
    customer: {
      type: Object,
      required: true,
    },
    enrolledCustomer: {
      type: Object,
      default: null,
    },
  },
  methods: {
    formatNumberFromDbToCurrency,
    formatNumberFromDbToCurrencyWithoutDecimals,
  },
}
</script>

<style lang="scss" scoped>
.position-relative {
  position: relative;
}
.chip-position {
  position: absolute;
  z-index: 100;
  top: -10px;
  left: 10px;
}
</style>
