import { decimal, minValue } from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    titleBackground: '#white',
    titleColor: 'textPrimary',
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    acceptButtonText: 'salesView.finishSaleDialog.acceptButton',
    height: state.dialogHeight,
    maxWidth: 500,
    id: 'calculate-change-form',
    ref: 'calculate-change-dialog',
    persistent: state.persistent,
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.paySale(),
  },
  fields: [
    {
      id: 'amount',
      type: 'input',
      valueType: 'number',
      label: 'shared.amount',
      errorMessage: 'mainLayout.user.errorAmount',
      color: 'primaryColor',
      required: false,
      autofocus: false,
      validators: {
        decimal,
        minValue: minValue(state.finalPrice),
      },
      changeEvent: methods.amountWasChanged,
    },
  ],
  id: 'calculate-change-form',
})

export default setConfig
