<template>
  <DialogCard :config="dialogConfig.dialogData">
    <div class="d-flex flex-column">
      <FormattedText
        type="text-h5"
        className="font-weight-bold"
        :value="'salesView.scanYourProductsDialog.firstText'"
        intl
      />
      <FormattedText type="text-h6" class="pb-3">
        <span>
          {{ getTranslatedText('salesView.scanYourProductsDialog.secondText') }}
        </span>
        <a :href="openGetScannerWeb" target="_blank">
          <span>{{
            getTranslatedText('salesView.scanYourProductsDialog.secondTextLink')
          }}</span>
        </a>
      </FormattedText>
      <FormattedText
        type="text-h5"
        className="font-weight-bold"
        :value="'salesView.scanYourProductsDialog.thirdText'"
        intl
      />
      <FormattedText
        type="text-h6"
        class="pb-2"
        :value="'salesView.scanYourProductsDialog.fourthText'"
        intl
      />
      <v-checkbox
        v-model="noLongerAppear"
        hide-details
        :label="
          getTranslatedText('salesView.scanYourProductsDialog.dontShowAgain')
        "
      />
    </div>
  </DialogCard>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import USER_INFORMATION_DB_API_EVENTS from '@/config/events/databaseAPI/userInformationEvents'
import buyYourScannerUrls from '@/config/buyYourScannerUrls'

import { getTranslatedText } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'

import salesViewActions from '@/store/salesView/actions.types'
import appActions from '@/store/app/actions.types'

import DialogCard from '@/components/shared/DialogCard'
import FormattedText from '@/components/shared/FormattedText'
import setConfig from '@/components/SalesView/ScanYourProductsDialog/config'

export default {
  name: 'ScanYourProductsDialog',
  components: { DialogCard, FormattedText },
  data() {
    return {
      noLongerAppear: false,
    }
  },
  computed: {
    ...mapState('salesView', ['scanYourProductsDialog']),
    ...mapState('account', ['data']),
    dialogConfig() {
      return setConfig(
        { isOpen: this.scanYourProductsDialog },
        { closeDialog: this.closeDialog, onClickAccept: this.onClickAccept }
      )
    },
    openGetScannerWeb() {
      const countryCode = this.data.country.localeIsoCode
      return countryCode in buyYourScannerUrls
        ? buyYourScannerUrls[countryCode]
        : buyYourScannerUrls['default']
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('salesView', [
      salesViewActions.setScanYourProductsDialogStatus,
    ]),
    ...mapActions('app', [appActions.setShowScanYourProductsDialogStatus]),
    closeDialog() {
      this[salesViewActions.setScanYourProductsDialogStatus](false)
    },
    onClickAccept() {
      if (this.noLongerAppear) {
        this[appActions.setShowScanYourProductsDialogStatus](false)
        rendererEventsService.send(USER_INFORMATION_DB_API_EVENTS.channel, {
          event:
            USER_INFORMATION_DB_API_EVENTS.events
              .updateScanYourProductsDialogCounter.name,
          data: { stopShow: true },
        })
      }
      this.closeDialog()
    },
  },
}
</script>
