<template>
  <div>
    <div v-show="false" ref="tourFirstSaleThirdStep">
      <div class="tour-third-step-content">
        <h2>
          {{ getTranslatedText('tour.firstSaleTour.thirdStep.firstText') }}
        </h2>
        <h3>
          {{ getTranslatedText('tour.firstSaleTour.thirdStep.secondText') }}
        </h3>
      </div>
    </div>
    <div v-show="false" ref="tourFirstSaleSeventhStep">
      <div class="tour-seventh-step-content">
        <v-icon size="90" color="success" class="mb-6">
          mdi-trophy-outline
        </v-icon>
        <h1>
          {{ getTranslatedText('tour.firstSaleTour.seventhStep.firstText') }}
        </h1>
        <h2>
          {{ getTranslatedText('tour.firstSaleTour.seventhStep.secondText') }}
        </h2>
        <h2>
          {{ getTranslatedText('tour.firstSaleTour.seventhStep.thirdText') }}
        </h2>
      </div>
    </div>
    <div v-show="false" ref="tourSaleFirstStep">
      <div class="tour-first-step-content">
        <v-icon size="90" class="mb-6">
          mdi-cart
        </v-icon>
        <h1>
          {{ getTranslatedText('tour.firstSaleTour.secondStep.firstText') }}
        </h1>
        <h2>
          {{ getTranslatedText('tour.firstSaleTour.secondStep.secondText') }}
        </h2>
      </div>
    </div>
  </div>
</template>

<script>
import { mapActions, mapGetters, mapState } from 'vuex'

import USER_EVENTS from '@/config/events/databaseAPI/usersEvents'
import salesTour from '@/config/tours/salesTour'

import { getTranslatedText } from '@/tools/data'

import tourTrackTools from '@/tools/tourTrack'

import rendererEventsService from '@/services/renderer/rendererEvents'
import tourService from '@/services/renderer/tour'

import salesViewActions from '@/store/salesView/actions.types'
import appActions from '@/store/app/actions.types'
import usersViewActions from '@/store/usersView/actions.types'

export default {
  name: 'SalesTour',
  data() {
    return { tour: null }
  },
  computed: {
    ...mapState('usersView', ['selectedUser']),
    ...mapState('salesView', ['tourEnabled']),
    ...mapGetters('salesView', ['getFilteredProducts']),
    ...mapState('products', {
      mlpProducts: state => state.data.mlp,
    }),
  },
  methods: {
    ...mapActions('salesView', [
      salesViewActions.setTourEnabled,
      salesViewActions.setSearchTermFilter,
    ]),
    ...mapActions('app', [appActions.setConfirmCancelTourDialogStatus]),
    ...mapActions('usersView', [usersViewActions.setSelectedUser]),
    getTranslatedText,
    createAndStartTour() {
      this.tour = tourService.createTour(this, salesTour.tourOptions)
      tourService.addSteps(this, salesTour.steps)
      tourService.addCancelFunctionToSteps(this, this.confirmCancelTour)
      this.tour.steps[1].once('show', () => {
        setTimeout(
          () => document.getElementById('sales-input-search').click(),
          400
        )
      })
      tourTrackTools.initTracks.call(this, 'Sales')
      this.tour.on('cancel', () => {
        this.disabledSalesTour()
      })
      this.tour.on('complete', () => {
        this.disabledSalesTour()
      })
      this.tour.start()
    },
    goToHelpCenter() {
      this.tour.next()
      this.$router.push({ path: '/app/helpCenter' })
    },
    confirmCancelTour() {
      this[appActions.setConfirmCancelTourDialogStatus]({
        isOpen: true,
        tour: this.tour,
      })
    },
    disabledSalesTour() {
      const selectedUser = Object.assign(this.selectedUser)
      rendererEventsService.send(USER_EVENTS.channel, {
        event: USER_EVENTS.events.update.name,
        data: {
          userId: selectedUser.id,
          values: { sales_tour_disabled: 1 },
        },
      })
      this[salesViewActions.setTourEnabled](false)
      selectedUser.salesTourDisabled = 1
      this[usersViewActions.setSelectedUser](selectedUser)
    },
  },
  watch: {
    mlpProducts: function(value) {
      if (this.tourEnabled) {
        const currentStep = this.tour.getCurrentStep().id
        if (
          currentStep === 'onboardingFirstSaleThirdStep' &&
          value.length !== 0
        )
          this.tour.next()
      }
    },
  },
  beforeMount() {
    this[salesViewActions.setTourEnabled](
      this.selectedUser.salesTourDisabled === 0
    )
  },
  mounted() {
    if (this.tourEnabled) this.createAndStartTour()
    this.$root.$on('product-added-tour', () => {
      if (!this.tour) return
      const currentStep = this.tour.getCurrentStep().id
      if (this.tourEnabled && currentStep === 'onboardingFirstSaleFourthStep')
        this.tour.next()
    })
    this.$root.$on('calculate-change-cancel-tour', () => {
      if (this.tourEnabled) this.tour.back()
    })
    this.$root.$on('product-scanned-sale-tour', upc => {
      this[salesViewActions.setSearchTermFilter](upc)
      if (
        this.tour.getCurrentStep().id === 'onboardingFirstSaleThirdStep' &&
        this.getFilteredProducts.some(prod => prod.upc.includes(upc))
      ) {
        this.tour.next()
      }
    })
  },
  beforeDestroy() {
    tourTrackTools.destroyTracks.call(this, 'Sales')
    this.$root.$off('product-added-tour')
    this.$root.$off('calculate-change-cancel-tour')
    this.$root.$off('product-scanned-sale-tour')
  },
}
</script>
