const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-barcode-scan',
    title: 'salesView.scanYourProductsDialog.title',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    persistent: true,
    buttons: { accept: true, cancel: false },
    buttonTextColor: {
      accept: 'white',
    },
    buttonColor: {
      accept: 'primary',
    },
    height: 390,
    maxWidth: 750,
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.onClickAccept(),
  },
})

export default setConfig
