import { required, decimal } from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-delete',
    title:
      state.isEditForm === true
        ? 'salesView.genericProductDialog.editTitle'
        : 'salesView.genericProductDialog.addTitle',

    messages: ['salesView.genericProductDialog.message'],
    extraValuesMessages: [state.genericName],
    titleBackground: '#white',
    titleColor: 'textPrimary',
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    height: 300,
    maxWidth: 500,
    id: 'generic-product-form',
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.addToCurrentSale(),
  },
  fields: [
    {
      id: 'amount',
      type: 'input',
      valueType: 'number',
      label: 'shared.amount',
      errorMessage: 'mainLayout.user.errorAmount',
      color: 'primaryColor',
      required: true,
      autofocus: true,
      visible: true,
      validators: { required, decimal, minValue: value => value > 0 },
    },
  ],
  id: 'generic-product-form',
})

export default setConfig
