const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-delete',
    title: 'salesView.notificationDialog.title',
    messages: ['salesView.notificationDialog.message'],
    titleBackground: '#white',
    titleColor: 'textPrimary',
    buttons: { accept: true, cancel: false },
    buttonTextColor: {
      accept: 'white',
    },
    buttonColor: {
      accept: 'primary',
    },
    height: 230,
    maxWidth: 600,
    onClickAccept: () => {
      methods.setDialogStatus()
      methods.context.$root.$emit('reset')
      methods.setGroup('all')
      methods.setSelectedSuperCategories([])
    },
  },
})

export default setConfig
