<template>
  <div class="d-flex flex-column">
    <v-icon class="pb-1">mdi-cart</v-icon>
    <v-tooltip v-if="!showNameInput" bottom>
      <template v-slot:activator="{ on, attrs }">
        <span
          v-on="on"
          v-bind="attrs"
          @dblclick.prevent.stop="enableEditSaleName"
        >
          {{ sale.name }}
        </span>
      </template>
      <span>
        {{ getTranslatedText('salesView.nameEdition.tooltip') }}
      </span>
    </v-tooltip>
    <v-text-field
      v-else
      v-model="saleName"
      ref="saleNameInput"
      class="sale-name-input"
      flat
      solo
      background-color="cardBackgroundAlternative"
      dense
      hide-details
      autofocus
      :style="inputStyle"
      @keydown.enter="saveNameAndClose"
      @focus="saleNameInputWasFocused"
      @input="nameWasUpdated"
    />
    <v-btn
      icon
      absolute
      color="accent"
      class="multi-sales__tabs__close"
      v-if="hover & (sales.length > 1)"
      v-track:click="{
        category: 'Sales',
        screen: 'SaleTabs',
        name: 'Delete ticket',
      }"
      @click.prevent.stop="onClickDeleteTicket()"
    >
      <v-icon>mdi-close-circle</v-icon>
    </v-btn>
  </div>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import { deepCopy, getTranslatedText } from '@/tools/data'

import salesViewActions from '@/store/salesView/actions.types'
import salesActions from '@/store/sales/actions.types'

export default {
  name: 'SaleTab',
  props: {
    sale: {
      type: Object,
      required: true,
    },
    hover: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      showNameInput: false,
      saleName: '',
      inputStyle: { width: '70px' },
    }
  },
  computed: {
    ...mapState('sales', ['sales']),
    ticketIndex() {
      return this.sales.findIndex(sale => sale.ticketId === this.sale.ticketId)
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('sales', [salesActions.updateSaleName]),
    ...mapActions('salesView', [
      salesViewActions.setTicketIdToDelete,
      salesViewActions.setDeleteConfirmationDialogStatus,
    ]),
    enableEditSaleName() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Sales',
        screen: 'SaleTabs',
        name: 'Edit ticket name',
      })
      this.$barcodeScanner.destroy()
      this.saleName = deepCopy(this.sale.name)
      this.inputStyle.width = `${this.$el.offsetWidth}px`
      this.showNameInput = true
    },
    saleNameInputWasFocused() {
      this.$refs.saleNameInput.$el.getElementsByTagName('input')[0].select()
    },
    saveNameAndClose() {
      if (this.saleName.trim() !== '') {
        this[salesActions.updateSaleName]({
          ticketIndex: this.ticketIndex,
          name: this.saleName.trim(),
        })
      }
      this.showNameInput = false
      this.$emit('nameWasEdited')
      this.$root.$emit('enable-scanner', {})
    },
    nameWasUpdated(value) {
      this.saleName = value.substr(0, 20)
      this.$refs.saleNameInput.lazyValue = this.saleName
    },
    onClickDeleteTicket() {
      this[salesViewActions.setTicketIdToDelete](this.ticketIndex)
      this[salesViewActions.setDeleteConfirmationDialogStatus]()
    },
    handleClickOutside(event) {
      if (!this.$refs.saleNameInput) return
      const el = this.$refs.saleNameInput.$el
      if (el && !el.contains(event.target)) {
        this.saveNameAndClose()
      }
    },
  },
  mounted() {
    document.addEventListener('click', this.handleClickOutside)
  },
  beforeDestroy() {
    document.removeEventListener('click', this.handleClickOutside)
  },
}
</script>

<style scoped lang="scss">
.multi-sales__tabs__close {
  top: 0;
  right: 0;
}
.sale-name-input {
  font-size: 0.875rem;
  font-weight: normal;
  :deep(.v-input__control) {
    min-height: 18px !important;
    height: 18px;
    .v-input__slot {
      padding: 0 4px !important;
    }
    input {
      text-align: center;
      text-transform: uppercase;
    }
  }
}
</style>
