import paymentMethods from '@/config/paymentMethods'
import { promotions } from '@/config/promotions'

const setConfig = (state, methods) => ({
  state,
  methods,
  paymentType: {
    id: 'paymentType',
    type: 'radioGroup',
    value: state.data.payOption,
    subValue: state.data.paySubOption,
    disabled: option => disabledOption(state, methods, option),
    onChangeValue: methods.changePayOption,
    options: getPaymentMethods(state.paymentProvidersByType, state.tourEnabled),
  },
  fields: [
    {
      id: 'print',
      type: 'switch',
      label: 'salesView.ticket.title',
      color: 'primary',
      value: state.data.print,
      hideDetails: true,
      inset: true,
      onChangeValue: methods.changePrintStatus,
    },
    {
      id: 'paymentType',
      type: 'text-body-2',
      class: 'mr-6',
      intl: false,
      className: '',
      color: 'unitTypeTicket',
      value: getPaymentMethodText(state, methods.getTranslatedText),
    },
    {
      id: 'calculator',
      type: 'icon',
      icon: 'mdi-calculator',
      color: 'primary',
      size: 30,
      disabled: state.disabledCalculator,
      onClick: () => methods.openFinishSaleDialog(),
    },
  ],
})

const getPaymentMethods = (paymentProvidersByType, tourEnabled) => {
  const paymentMethodsList = getDefaultPaymentMethods(tourEnabled)
  addProvidersPaymentMethods(
    paymentProvidersByType,
    paymentMethodsList,
    tourEnabled
  )
  addOwnerPaymentMethods(paymentMethodsList, tourEnabled)
  return paymentMethodsList
}

const getDefaultPaymentMethods = tourEnabled => {
  const defaultPaymentMethods = [
    paymentMethods.cashKey,
    paymentMethods.creditKey,
  ]
  return defaultPaymentMethods.map(method => ({
    id: method,
    label: `salesView.ticket.${method}`,
    value: method,
    disabled: method === paymentMethods.creditKey && tourEnabled,
  }))
}

const addProvidersPaymentMethods = (
  paymentProvidersByType,
  paymentMethodsList,
  tourEnabled
) => {
  const defaultExternalPayments = [paymentMethods.qrKey, paymentMethods.cardKey]
  defaultExternalPayments.forEach(method => {
    if (paymentProvidersByType[method]) {
      paymentMethodsList.push({
        id: method,
        label: `salesView.ticket.${method}`,
        value: method,
        options: [...paymentProvidersByType[method]],
        disabled: tourEnabled,
      })
    }
  })
  const otherPayments = []
  Object.keys(paymentProvidersByType).forEach(type => {
    if (!defaultExternalPayments.includes(type)) {
      otherPayments.push(...paymentProvidersByType[type])
    }
  })
  if (otherPayments.length) {
    paymentMethodsList.push({
      id: paymentMethods.others,
      label: `salesView.ticket.${paymentMethods.others}`,
      value: paymentMethods.others,
      options: otherPayments,
      disabled: tourEnabled,
    })
  }
}

const addOwnerPaymentMethods = (paymentMethodsList, tourEnabled) => {
  paymentMethodsList.push({
    id: paymentMethods.ownerKey,
    label: `salesView.ticket.${paymentMethods.ownerKey}`,
    value: paymentMethods.ownerKey,
    disabled: tourEnabled,
  })
}

const getPaymentMethodText = (state, getTranslatedText) => {
  if (!state.paymentProvidersByType[state.data.payOption]) {
    return getTranslatedText(`salesView.ticket.${state.data.payOption}`)
  }
  const paySubOptionFound = state.paymentProvidersByType[
    state.data.payOption
  ].find(method => method.value === state.data.paySubOption)
  if (!paymentMethods.defaultPaymentMethods.includes(state.data.payOption)) {
    return paySubOptionFound.label
  }
  const commission = hasCommissions(paySubOptionFound)
    ? `(+${paySubOptionFound.commissions}%)`
    : ''
  return `${getTranslatedText(`salesView.ticket.${state.data.payOption}`)}: ${
    paySubOptionFound.label
  } ${commission}`
}

const hasCommissions = paymentMethod => {
  return (
    paymentMethod &&
    paymentMethods.isCardSale(paymentMethod.type) &&
    paymentMethod.commissions > 0
  )
}

const disabledOption = (state, methods, option) => {
  if (state.data.items.length <= 0 && state.data.promotions.length <= 0) {
    return true
  }
  if (methods.getPrice() === 0) {
    return !(
      option === 'owner' && allProductsHasFreePromotion(state.data.items)
    )
  }
  return false
}

const allProductsHasFreePromotion = products => {
  const freeProductPromotion = [
    promotions.PURCHASE_ITEM_FREE_PRODUCT,
    promotions.SALE_ITEM_FREE_PRODUCT,
  ]
  return !products.some(
    item => !freeProductPromotion.includes(item.promotionTypeId)
  )
}
export default setConfig
