<template>
  <div>
    <!-- By weight form -->
    <div v-if="product !== undefined">
      <div>
        <FormattedText :value="productName" type="text-h6" />
      </div>
      <div class="d-flex align-center pb-4">
        <div class="d-flex align-center pt-2" v-if="product.isGramaje === 0">
          <v-icon color="salesPrimary"> mdi-barcode-scan </v-icon>
          <div class="px-2">
            <FormattedText :value="product.upc" type="text-subtitle-1" />
          </div>
        </div>
        <v-spacer></v-spacer>
        <div class="show-dbprice" v-if="showDBPrice">
          <v-btn
            @click="setPriceFromDB"
            depressed
            class="d-flex align-center database-price"
          >
            <span class="text-subtitle-1">{{
              getTranslatedText('salesView.form.storeInventory')
            }}</span>
            <div class="pl-2 text-subtitle-1">
              <span class="font-weight-bold">{{ dbPrice }}</span>
            </div>
          </v-btn>
        </div>
        <div class="reset-dbprice" v-if="alertConfig.type === 'error'">
          <v-btn
            @click="resetForm"
            depressed
            class="d-flex align-center database-price"
          >
            <span class="text-subtitle-1">
              {{ getTranslatedText('salesView.form.reset') }}
            </span>
          </v-btn>
        </div>
      </div>
      <v-row>
        <v-col cols="12" class="py-0">
          <v-radio-group
            v-if="showOpenProductOptions(product)"
            v-model="radio"
            class="mt-0"
            row
          >
            <template v-slot:label>
              <div>
                {{
                  getTranslatedText(
                    'salesView.productTriangulationDialog.salesBy'
                  )
                }}
              </div>
            </template>
            <v-radio value="0">
              <template v-slot:label>
                <div>
                  {{
                    getTranslatedText(
                      'salesView.productTriangulationDialog.byPackage'
                    )
                  }}
                </div>
              </template>
            </v-radio>
            <v-radio value="1">
              <template v-slot:label>
                <div>
                  {{
                    getTranslatedText(
                      'salesView.productTriangulationDialog.byPiece'
                    )
                  }}
                </div>
              </template>
            </v-radio>
          </v-radio-group>
        </v-col>
        <v-col cols="4" class="d-flex">
          <v-text-field
            id="quantity-input"
            ref="quantity"
            v-model.number="inputs.quantity"
            class="custom-text-field-large"
            filled
            rounded
            color="primary"
            :label="
              getTranslatedText(
                product.isGramaje === 1
                  ? 'salesView.ticket.grams'
                  : openProductType === 0
                  ? 'salesView.ticket.packages'
                  : 'salesView.ticket.pieces'
              )
            "
            :error-messages="onValidateFields('quantity')"
            @focus="currentFocus = 'quantity'"
            @input="onQuantityInput"
            @blur="$v.inputs.quantity.$touch()"
            @keydown.enter="onEnterEvent"
          ></v-text-field>
        </v-col>
        <v-col cols="4" class="d-flex">
          <MoneyTextField
            ref="price"
            v-model.number="inputs.price"
            :config="{
              fieldName: 'price',
              label: getPriceLabel(),
              color: 'primary',
              filled: true,
              rounded: true,
              class: 'custom-text-field-large',
              errorMessage: onValidateFields,
            }"
            :options="moneyInputsConfig"
            @focus="currentFocus = 'price'"
            @input="onPriceInput"
            @blur="$v.inputs.price.$touch()"
            @enter="onEnterEvent"
          />
        </v-col>
        <v-col cols="4">
          <MoneyTextField
            ref="total"
            v-model.number="inputs.total"
            :config="{
              fieldName: 'total',
              color: 'white',
              filled: true,
              rounded: true,
              class: hasProductPromotion
                ? 'total-text-field product-promotion'
                : 'total-text-field',
              suffix: 'Total',
              backgroundColor: 'primary',
              errorMessage: onValidateFields,
            }"
            :options="moneyInputsConfig"
            @focus="currentFocus = 'total'"
            @input="onTotalInput"
            @blur="onTotalInputBlur"
            @enter="onEnterEvent"
          />
        </v-col>
      </v-row>
    </div>
    <!-- Form alerts -->
    <div class="by-weight-alerts">
      <Alert
        v-if="product !== null"
        :config="alertConfig"
        :show="showAlert"
        class="mb-4"
      >
        <FormattedText
          v-if="!!alertPromotion"
          intl
          :value="alertPromotion"
          color="textPrimary"
          className="ml-4"
        />
      </Alert>
    </div>
  </div>
</template>

<script>
import { isNil } from 'ramda'

import WEIGHT_SCALE_EVENTS from '@/config/events/weightScaleEvents'

import { getTranslatedText } from '@/tools/data'
import {
  decimal,
  formatNumberFromDb,
  formatNumberFromDbToCurrency,
} from '@/tools/numbersFormat'

import rendererEventsService from '@/services/renderer/rendererEvents'

import methods from '@/components/SalesView/MultiSalesTabs/ProductTriangulationForm/config'
import MoneyTextField from '@/components/shared/MoneyTextField'
import FormattedText from '@/components/shared/FormattedText'
import Alert from '@/components/shared/Alert'

export default {
  name: 'ProductTriangulationForm',
  components: { MoneyTextField, FormattedText, Alert },
  props: {
    product: {
      type: Object,
      required: true,
    },
    onEnterEvent: {
      type: Function,
    },
    alertPromotion: {
      type: String,
      default: null,
    },
    hasProductPromotion: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      inputs: {
        quantity: 0,
        price: 0,
        total: 0,
      },
      currentFocus: '',
      alertConfig: {},
      showAlert: false,
      priceChanged: false,
      showDBPrice: false,
      salesByRadioOption: null,
      openProductType: null,
      productType: null,
      productDbPrice: null,
      edit: false,
      moneyInputsConfig: this.getMoneyInputsConfig(),
    }
  },
  computed: {
    productName() {
      return `Producto: ${this.product.name}`
    },
    dbPrice() {
      return formatNumberFromDbToCurrency(this.productDbPrice)
    },
    radio: {
      get() {
        return this.salesByRadioOption === null ? '0' : this.salesByRadioOption
      },
      set(newValue) {
        this.salesByRadioOption = newValue
      },
    },
  },
  validations() {
    return this.setFormValidators()
  },
  methods: {
    ...methods,
    getTranslatedText,
    weightScaleListener(event, payload) {
      const replies = {
        [WEIGHT_SCALE_EVENTS.events.getWeight.replies.success]: () => {
          this.inputs.quantity = payload.data.weight
          this.showDBPrice = this.checkIfShowDbPrice()
          this.inputs.total = decimal(
            this.product.isGramaje === 1
              ? ((this.inputs.quantity || 0) / 1000) * this.inputs.price
              : (this.inputs.quantity || 0) * this.inputs.price,
            4
          )
          setTimeout(() => {
            this.showAlerts()
          }, 0)
          this.emitValues()
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  watch: {
    salesByRadioOption(newValue) {
      if (this.product.factor < 0) return
      this.getInitialFocus()
      switch (newValue) {
        case '0':
          this.openProductType = 0
          this.product.factorSalesBy = 0
          this.productType = 'isOpenProductPackage'
          this.inputs.price =
            this.edit === true && this.product.openProductType === 0
              ? formatNumberFromDb(this.product.unitPrice)
              : formatNumberFromDb(this.product.openProductDbPrices.package)

          this.productDbPrice = this.product.openProductDbPrices.package
          break
        case '1':
          this.openProductType = 1
          this.product.factorSalesBy = 1
          this.productType = 'isOpenProductPiece'

          this.inputs.price =
            this.edit === true && this.product.openProductType === 1
              ? formatNumberFromDb(this.product.unitPrice)
              : formatNumberFromDb(this.product.openProductDbPrices.piece)

          this.productDbPrice = this.product.openProductDbPrices.piece
          break
      }
      this.initTotal()
      this.showAlerts()
    },
    'inputs.quantity': function() {
      if (this.currentFocus === 'quantity') this.onQuantityInput()
    },
    'inputs.price': function() {
      if (this.currentFocus === 'price') this.onPriceInput()
    },
    'inputs.total': function() {
      if (this.currentFocus === 'total') this.onTotalInput()
    },
  },
  beforeMount() {
    this.initQuantity()
    if (this.product.isGramaje === 1) {
      rendererEventsService.send(WEIGHT_SCALE_EVENTS.channel, {
        event: WEIGHT_SCALE_EVENTS.events.getWeight.name,
      })
    }
    rendererEventsService.subscribe(
      WEIGHT_SCALE_EVENTS.replyChannel,
      this.weightScaleListener
    )
  },
  mounted() {
    this.edit = !isNil(this.product.uniqueId)
    this.productType = this.setProductType(this.product)
    this.openProductType = !isNil(this.product.openProductType)
      ? this.product.openProductType.toString()
      : this.product.factorSalesBy
    this.productDbPrice = !isNil(this.product.dbPrice)
      ? this.product.dbPrice
      : this.product.price
    this.inputs.price =
      formatNumberFromDb(this.product.price) ||
      formatNumberFromDb(this.product.unitPrice)
    if (this.product.isGramaje !== 1) {
      this.salesByRadioOption = !isNil(this.product.openProductType)
        ? this.openProductType.toString()
        : this.product.factorSalesBy.toString()
    }
    this.showDBPrice = this.checkIfShowDbPrice()
    this.priceChanged = this.checkIfShowDbPrice()
    this.initTotal()
    this.getInitialFocus()
    this.showAlerts()
  },
  updated() {
    this.emitValues()
  },
  beforeDestroy() {
    rendererEventsService.send(WEIGHT_SCALE_EVENTS.channel, {
      event: WEIGHT_SCALE_EVENTS.events.stop.name,
    })
    rendererEventsService.removeListener(
      WEIGHT_SCALE_EVENTS.replyChannel,
      this.weightScaleListener
    )
  },
}
</script>

<style lang="scss" scoped>
.database-price {
  color: var(--v-salesPrimary-base);
}
</style>
