<template>
  <div>
    <div class="d-flex pb-2">
      <v-icon class="mr-4">mdi-hand-heart-outline</v-icon>
      <FormattedText
        type="text-h6"
        value="salesView.finishSaleDialog.title1"
        intl
      />
    </div>
    <FormattedText
      type="text-body-1"
      value="salesView.finishSaleDialog.message1"
      intl
      class="pb-2"
    />
    <v-autocomplete
      v-model="selectedEnrolledCustomer"
      :items="approvedEnrolledCustomers"
      item-text="customer.name"
      item-value="customerId"
      rounded
      filled
      flat
      clearable
      hide-details
      color="salesPrimary"
      item-color="salesPrimary"
      class="custom-text-field"
      :label="getTranslatedText('salesView.ticket.client')"
      :placeholder="getTranslatedText('salesView.ticket.search')"
      :no-data-text="
        getTranslatedText('salesView.finishSaleDialog.notEnrolledCustomer')
      "
      append-icon="mdi-account-multiple"
      @change="emitValue"
    />
    <v-chip-group
      class="py-2"
      active-class="primary--text"
      column
      v-model="selectedEnrolledCustomer"
      @change="emitValue"
    >
      <v-chip
        filter
        v-for="enrolledCustomer in top5EnrolledCustomers"
        :key="enrolledCustomer.customerId"
        :value="enrolledCustomer.customerId"
      >
        {{ getTruncatedText(enrolledCustomer.customer.name, 10) }}
      </v-chip>
    </v-chip-group>
  </div>
</template>

<script>
import { isNil } from 'ramda'
import { mapActions, mapGetters } from 'vuex'

import { getTranslatedText, getTruncatedText } from '@/tools/data'

import salesViewActions from '@/store/salesView/actions.types'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'EnrolledCustomerSelector',
  components: { FormattedText },
  data() {
    return {
      selectedEnrolledCustomer: null,
    }
  },
  computed: {
    ...mapGetters('loyaltyProgram', ['approvedEnrolledCustomers']),
    top5EnrolledCustomers() {
      return this.approvedEnrolledCustomers.slice(0, 5)
    },
  },
  methods: {
    getTranslatedText,
    getTruncatedText,
    ...mapActions('salesView', [salesViewActions.setEnrolledCustomer]),
    getEnrolledCustomer(customerId) {
      return this.approvedEnrolledCustomers.find(
        customer => customer.customerId === customerId
      )
    },
    resetValue() {
      this.selectedEnrolledCustomer = null
    },
    emitValue() {
      if (isNil(this.selectedEnrolledCustomer)) {
        this[salesViewActions.setEnrolledCustomer]('')
      } else {
        const enrolledCustomer = this.getEnrolledCustomer(
          this.selectedEnrolledCustomer
        )
        this[salesViewActions.setEnrolledCustomer](enrolledCustomer)
      }
      this.$emit('enrolled-customer-selected')
    },
  },
}
</script>
