<template>
  <ToolBar :config="componentConfig" />
</template>

<script>
import { mapActions, mapState, mapGetters } from 'vuex'
import { isNil } from 'ramda'

import { testMode, isDevelopment } from '@/config/env'
import MLP_DB_API_EVENTS from '@/config/events/databaseAPI/mlpEvents'
import AIRTIME_EVENTS from '@/config/events/airtime'

import rendererEvents from '@/services/renderer/rendererEvents'
import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import appActions from '@/store/app/actions.types'
import salesActions from '@/store/sales/actions.types'
import salesViewActions from '@/store/salesView/actions.types'
import productsActions from '@/store/products/actions.types'
import productsViewActions from '@/store/productsView/action.types'
import airtimeActions from '@/store/airtimeServices/actions.types'

import config from '@/components/SalesView/MultiSalesTabs/ProductsFilterToolBar/ProductsFilter/config'
import ToolBar from '@/components/shared/ToolBar'

export default {
  name: 'SalesFilter',
  components: {
    ToolBar,
  },
  data() {
    return {
      config,
    }
  },
  timer: null,
  computed: {
    ...mapState('app', {
      isScannerActive: state => state.scanner.isActive,
      defaultProductsFilter: state => state.defaultProductsFilter,
    }),
    ...mapState('account', { accountData: state => state.data }),
    ...mapState('products', ['data']),
    ...mapState('sales', {
      sales: state => state.sales,
    }),
    ...mapState('salesView', {
      currentSale: state => state.currentSale.saleIndex,
      filters: state => state.filters,
      tourEnabled: state => state.tourEnabled,
    }),
    ...mapGetters('salesView', ['getFilteredProducts']),
    componentConfig: function() {
      return config(
        {
          data: this.data,
          filters: this.filters,
          currentSale: this.currentSale,
          isScannerActive: this.isScannerActive,
          sales: this.sales,
          products: this.data.products,
          defaultProductsFilter: this.defaultProductsFilter,
          posData: JSON.parse(JSON.stringify(this.accountData)),
        },
        {
          track: this.$track,
          setSearchTerm: this[salesViewActions.setSearchTermFilter],
          setGroup: this[salesViewActions.setGroupFilter],
          setSelectedSuperCategories: this[
            salesViewActions.setSuperCategoriesFilter
          ],
          onReset: this.onReset,
          addProductToCurrentSale: this.addProductToCurrentSale,
          context: this,
          setNotificationDialogStatus: this[
            salesViewActions.setNotificationDialogStatus
          ],
          resetScannerStatus: this.resetScannerStatus,
          updateScannerStatus: this[appActions.updateScannerStatus],
          toggleProductTriangulationDialogStatus: this[
            salesViewActions.toggleProductTriangulationDialogStatus
          ],
          setSelectedProduct: this[salesViewActions.setSelectedProduct],
          onChange: this.onChange,
          onEnter: this.onEnter,
          setBalanceFetching: this[airtimeActions.setBalanceFetching],
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.updateScannerStatus]),
    ...mapActions('sales', [salesActions.addProductToCurrentSale]),
    ...mapActions('salesView', [
      salesViewActions.setNotificationDialogStatus,
      salesViewActions.setGroupFilter,
      salesViewActions.setSearchTermFilter,
      salesViewActions.setSuperCategoriesFilter,
      salesViewActions.toggleProductTriangulationDialogStatus,
      salesViewActions.setSelectedProduct,
    ]),
    ...mapActions('products', [productsActions.resetMlpFilteredProducts]),
    ...mapActions('productsView', [productsViewActions.toggleAddProductDialog]),
    ...mapActions('airtimeServices', [
      airtimeActions.setBalance,
      airtimeActions.setBalanceFetching,
      airtimeActions.setBalanceFetchingError,
    ]),
    onReset: function() {
      this.$root.$emit('reset')
    },
    resetScannerStatus(group) {
      switch (group) {
        case 'search-control':
          if (this.isScannerActive === false)
            this[appActions.updateScannerStatus]()
          break
        case 'clear':
          this[salesViewActions.setSearchTermFilter](null)
          this[salesViewActions.setGroupFilter](this.defaultProductsFilter)
          if (!this.isScannerActive) this[appActions.updateScannerStatus]()
          break
        default:
          group === 'superCategories'
            ? this[salesViewActions.setGroupFilter]('superCategories')
            : this[salesViewActions.setGroupFilter](group)
          if (!this.isScannerActive) this[appActions.updateScannerStatus]()
          break
      }
    },
    onChange(value) {
      const parsedValue = value === '' ? null : value
      if (this.filters.group === 'search' && !this.isScannerActive) {
        this[salesViewActions.setSearchTermFilter](parsedValue)
      }
    },
    onEnter(value) {
      const parsedValue = value === '' ? null : value
      if (isDevelopment === false || value.length > 24) return
      if (
        this.getFilteredProducts.length === 0 &&
        this.data.mlp.length === 0 &&
        !isNil(parsedValue)
      ) {
        this.resetScannerStatus('search-control')
        this[salesViewActions.setSearchTermFilter](parsedValue)
      }
    },
    onClick: resetSelector => {
      this.isScannerActive === true
        ? this[appActions.updateScannerStatus]()
        : null
      resetSelector()
      this[salesViewActions.setGroupFilter]('search')
      this[salesViewActions.setSuperCategoriesFilter]([])
    },
  },
  watch: {
    'filters.searchTerm'(newValue) {
      const parsedValue = newValue === '' ? null : newValue
      if (this.timer) clearTimeout(this.timer)
      if (isNil(parsedValue)) {
        this[productsActions.resetMlpFilteredProducts]([])
        return
      }
      if (this.filters.group === 'search') {
        this.timer = setTimeout(() => {
          rendererEventsService.send(MLP_DB_API_EVENTS.channel, {
            event: MLP_DB_API_EVENTS.events.findByPropertiesLikes.name,
            data: [
              { key: 'upc_code', value: parsedValue },
              { key: 'prod_name', value: parsedValue },
            ],
          })
        }, 500)
      }
    },
  },
  created() {
    rendererEventsService.subscribe(
      AIRTIME_EVENTS.replyChannel,
      async (evet, payload) => {
        const replies = {
          [AIRTIME_EVENTS.events.getBalance.replies.success]: () => {
            const balance = payload.data.airtimeBalance.balance
            this[airtimeActions.setBalance](balance)
            this[airtimeActions.setBalanceFetching](false)
          },
          [AIRTIME_EVENTS.events.getBalance.replies.error]: () => {
            this[airtimeActions.setBalance](0)
            this[airtimeActions.setBalanceFetching](false)
            this[airtimeActions.setBalanceFetchingError]()
            notificationsService.showError(
              'notification.airtime.balance.error',
              this.$vuetify.lang,
              { timeout: 5000 }
            )
          },
        }

        if (payload.event in replies) replies[payload.event]()
      }
    )
  },
  mounted() {
    if (isNil(testMode))
      rendererEvents.subscribe('sales-menu-channel', (event, arg) => {
        switch (arg) {
          case 'products-search':
            document.getElementById('sales-input-search').click()
            break
          case 'products-all':
            document.getElementById('all-button-control').click()
            break
          case 'products-byWeight':
            document.getElementById('weight-button-control').click()
            break
          case 'products-favorites':
            document.getElementById('favorites-button-control').click()
            break
          case 'products-generics':
            document.getElementById('prices-button-control').click()
            break
          case 'products-clear':
            document.getElementById('clear-button-control').click()
            break
        }
      })
    if (this.tourEnabled)
      setTimeout(
        () => document.getElementById('sales-input-search').click(),
        500
      )
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners(AIRTIME_EVENTS.replyChannel)
  },
}
</script>
