<template>
  <DialogCard :config="dialogConfig.dialogData" />
</template>

<script>
import { mapActions, mapState } from 'vuex'

import salesActions from '@/store/sales/actions.types'
import salesViewActions from '@/store/salesView/actions.types'

import setConfig from '@/components/SalesView/MultiSalesTabs/DeleteConfirmationDialog/config'
import DialogCard from '@/components/shared/DialogCard'

export default {
  name: 'DeleteConfirmationDialog',
  components: { DialogCard },
  data() {
    return {
      deletingTicket: false,
    }
  },
  computed: {
    ...mapState('salesView', {
      deleteConfirmationDialogStatus: state =>
        state.deleteConfirmationDialog.isOpen,
      tickedIdToDelete: state => state.deleteConfirmationDialog.ticketId,
    }),
    dialogConfig() {
      return setConfig(
        {
          isOpen: this.deleteConfirmationDialogStatus,
        },
        {
          setDialogStatus: () => this.setDeleteConfirmationDialogStatus(),
          deleteTicket: async () => {
            this.$track({
              type: 'interaction',
              action: 'click',
              category: 'Sales',
              screen: 'SaleTabs',
              name: 'Confirm delete ticket',
            })
            if (this.deletingTicket === true) return
            this.deletingTicket = true
            await this.removeSale(this.tickedIdToDelete)
            await this.setDeleteConfirmationDialogStatus()
            this.deletingTicket = false
          },
        }
      )
    },
  },
  methods: {
    ...mapActions('salesView', [
      salesViewActions.setDeleteConfirmationDialogStatus,
    ]),
    ...mapActions('sales', [salesActions.removeSale]),
  },
}
</script>
