<template>
  <v-row v-if="showPromotion">
    <v-col cols="12" class="pb-0">
      <FormattedText
        intl
        value="salesView.productTriangulationDialog.promotions.title"
        type="text-h6"
      />
    </v-col>
    <v-col cols="8" class="py-0">
      <v-checkbox
        v-model="giftProduct"
        :label="
          getTranslatedText(
            'salesView.productTriangulationDialog.promotions.giftProduct'
          )
        "
        :true-value="giftProductValue"
        :false-value="0"
      />
    </v-col>
    <v-col cols="4" class="py-0">
      <MoneyTextField
        v-if="giftProduct"
        ref="total"
        v-model.number="total"
        :config="{
          fieldName: 'total',
          color: 'white',
          filled: true,
          rounded: true,
          class: 'total-text-field',
          suffix: 'Total',
          backgroundColor: 'primary',
          errorMessage: () => {},
          readonly: true,
        }"
        :options="moneyTextFieldCountryConfig()"
      />
    </v-col>
  </v-row>
</template>

<script>
import { mapState } from 'vuex'

import { promotions } from '@/config/promotions'

import { moneyTextFieldCountryConfig } from '@/tools/numbersFormat'
import { getTranslatedText } from '@/tools/data'
import salesTools from '@/tools/sales'

import MoneyTextField from '@/components/shared/MoneyTextField'
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'ProductPromotion',
  components: { FormattedText, MoneyTextField },
  props: {
    value: {
      type: Number,
      required: true,
    },
    ticketIndex: {
      type: Number,
      required: true,
    },
  },
  data() {
    return {
      total: 0,
    }
  },
  computed: {
    ...mapState('sales', ['sales']),
    showPromotion() {
      return !salesTools.isOwnerSale(this.sales[this.ticketIndex].payOption)
    },
    giftProductValue() {
      return promotions.SALE_ITEM_FREE_PRODUCT
    },
    giftProduct: {
      get() {
        return this.value
      },
      set(newValue) {
        this.$emit('input', newValue)
      },
    },
  },
  methods: {
    getTranslatedText,
    moneyTextFieldCountryConfig,
  },
}
</script>
