<template>
  <DialogCard :config="componentConfig.dialogData">
    <!-- TODO: Render the provider logo -->
    <Form :config="componentConfig" />
  </DialogCard>
</template>

<script>
import { mapState, mapActions } from 'vuex'
import uniqid from 'uniqid'

import priceFrom from '@/config/itemAddedFrom'
import AIRTIME_API_EVENTS from '@/config/events/airtime'

import { getNow } from '@/tools/dates'
import { cleanObjectObserver } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import salesActions from '@/store/sales/actions.types'
import salesViewActions from '@/store/salesView/actions.types'

import setConfig from '@/components/SalesView/MultiSalesTabs/AitimeProductsDialog/config'
import DialogCard from '@/components/shared/DialogCard'
import Form from '@/components/shared/Form'

export default {
  name: 'AddAirtimeProductDialog',
  components: { DialogCard, Form },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
      recharging: false,
    }
  },
  computed: {
    ...mapState('salesView', [
      'airtimeProductDialog',
      'currentSale',
      'selectedProduct',
    ]),
    ...mapState('sales', ['sales']),
    ...mapState('app', ['defaultProductsFilter']),
    ...mapState('account', { accountData: state => state.data }),
    componentConfig() {
      return setConfig(
        {
          isOpen: this.airtimeProductDialog.isOpen,
          inputs: this.inputs,
          v: this.$v.inputs,
          providerServices: this.selectedProduct.services,
          providerName: this.selectedProduct.name,
          isAcceptButtonDisabled: this.$v.inputs.$invalid,
        },
        {
          closeDialog: () => this.closeDialog(),
          sendRechargeService: () => this.sendRechargeService(),
        }
      )
    },
    providerName() {
      return this.selectedProduct.name
    },
  },
  methods: {
    ...mapActions('salesView', [
      salesViewActions.toggleAirtimeProductDialogStatus,
      salesViewActions.setSelectedProduct,
      salesViewActions.setGroupFilter,
    ]),
    ...mapActions('sales', [salesActions.addProductToCurrentSale]),
    setProperties: function() {
      this.componentConfig.fields.forEach(field => {
        this.$set(this.inputs, field.id, '')
        if (field.validators)
          this.$set(this.validators.inputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
      })
    },
    resetState() {
      this.$root.$emit('reset')
      this[salesViewActions.setGroupFilter](this.defaultProductsFilter)
      this[salesViewActions.setSelectedProduct](null)
    },
    closeDialog() {
      Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$reset())
      Object.keys(this.inputs).forEach(key => (this.inputs[key] = ''))
      this[salesViewActions.toggleAirtimeProductDialogStatus]()
      this.resetState()
    },
    sendRechargeService() {
      if (this.recharging === true) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Sales',
        screen: 'AirtimeProductDialog',
        name: 'Send recharge service',
      })
      this.recharging = true
      const posData = JSON.parse(JSON.stringify(this.accountData))
      delete posData.country
      rendererEventsService.send(AIRTIME_API_EVENTS.channel, {
        event: AIRTIME_API_EVENTS.events.sendAirtimeRechargeRequest.name,
        data: {
          inputs: this.inputs,
          selectedProduct: this.selectedProduct,
          posData: posData,
          country: this.accountData.country.phoneCode,
        },
      })
    },
    addToCurrentSale(data) {
      const { airtimeProduct, result } = data
      const selectedProduct = this.selectedProduct
      const serviceSelected = selectedProduct.services.find(
        service => service.id == this.inputs.service
      )
      const saleItem = {
        currentSale: this.currentSale.saleIndex,
        product: {
          uniqueId: uniqid(),
          id: airtimeProduct._id,
          isGramaje: 0,
          isOpenProduct: 0,
          isGeneric: 0,
          isAirtime: 1,
          name: `Tiempo Aire ${selectedProduct.name}`,
          quantity: 1,
          unitPrice: serviceSelected.price,
          dbPrice: serviceSelected.price,
          cost: airtimeProduct.prod_cost,
          upc: airtimeProduct.upc,
          timeAdded: getNow(false),
          priceFrom: priceFrom.FROM_AIRTIME_OR_SERVICES,
          reference: result.authorization_code,
          phoneNumber: this.inputs.phoneNumber,
          promotionTypeId: 0,
        },
      }
      this[salesActions.addProductToCurrentSale](saleItem)
      this.recharging = false
      this.closeDialog()
      this.resetState()
    },
    sendAirtimeRechargeRequestListeners(event, payload) {
      const replies = {
        [AIRTIME_API_EVENTS.events.sendAirtimeRechargeRequest.replies
          .success]: () => {
          notificationsService.showSuccess(
            'notification.sales.rechargeSuccess',
            this.$vuetify.lang,
            {
              timeout: 10000,
            },
            [this.inputs.phoneNumber, payload.data.result.authorization_code]
          )

          this.addToCurrentSale(payload.data)
        },
        [AIRTIME_API_EVENTS.events.sendAirtimeRechargeRequest.replies
          .error]: () => {
          notificationsService.showError(payload.data.error)
          this.recharging = false
          this.closeDialog()
          this.resetState()
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  validations() {
    return this.validators
  },
  created() {
    rendererEventsService.subscribe(
      AIRTIME_API_EVENTS.replyChannel,
      this.sendAirtimeRechargeRequestListeners
    )
  },
  mounted() {
    this.$barcodeScanner.destroy()
    this.setProperties()
  },
  beforeDestroy() {
    this.$root.$emit('enable-scanner', {})
    rendererEventsService.removeListener(
      AIRTIME_API_EVENTS.replyChannel,
      this.sendAirtimeRechargeRequestListeners
    )
  },
}
</script>
