<template>
  <DialogCard :config="config.dialogData" />
</template>

<script>
import { mapActions, mapState } from 'vuex'

import { promotions } from '@/config/promotions'

import { discountTypes } from '@/tools/promotions'

import salesViewActions from '@/store/salesView/actions.types'
import salesActions from '@/store/sales/actions.types'

import DialogCard from '@/components/shared/DialogCard'
import setConfig from '@/components/SalesView/MultiSalesTabs/Ticket/TicketFooter/RestorePromotionDialog/config'

export default {
  name: 'RestorePromotionDialog',
  components: { DialogCard },
  props: {
    ticketIndex: {
      type: Number,
      required: true,
    },
  },
  computed: {
    ...mapState('salesView', ['restorePromotionDialog']),
    config() {
      return setConfig(
        { opened: this.restorePromotionDialog.isOpen },
        {
          closeDialog: () =>
            this.closeDialog(this.restorePromotionDialog.fromPayOption),
          acceptRestorePromotions: this.acceptRestorePromotions,
        }
      )
    },
  },
  methods: {
    ...mapActions('sales', [
      salesActions.resetSaleProductsPromotion,
      salesActions.updatePromotionTicket,
    ]),
    ...mapActions('salesView', [
      salesViewActions.setRestorePromotionDialogStatus,
    ]),
    closeDialog() {
      this[salesViewActions.setRestorePromotionDialogStatus]({
        isOpen: false,
        fromPayOption: null,
        toPayOption: null,
      })
    },
    acceptRestorePromotions() {
      this[salesActions.updatePromotionTicket]({
        discount: 0,
        type: discountTypes.percent,
        promotionTicketId: promotions.NONE,
        ticketIndex: this.ticketIndex,
      })
      this[salesActions.resetSaleProductsPromotion](this.ticketIndex)
      this.$emit(
        'changePayOption',
        this.restorePromotionDialog.toPayOption,
        this.restorePromotionDialog.toPayOption,
        true
      )
      this.closeDialog()
    },
  },
}
</script>
