<template>
  <DialogCard v-if="showDialog" :config="dialogConfig.dialogData">
    <EnrolledCustomerSelector
      class="pt-4"
      ref="enrolledCustomerSelectorRef"
      v-if="loyaltyProgramIsEnabled"
      v-on:enrolled-customer-selected="onSelectEnrolledCustomer"
    />
    <div
      v-if="showCashIncomeAndChange()"
      :class="{ 'pt-4': !loyaltyProgramIsEnabled }"
    >
      <div class="d-flex pb-2">
        <v-icon class="mr-4">mdi-calculator</v-icon>
        <FormattedText
          type="text-h6"
          value="salesView.finishSaleDialog.title2"
          intl
        />
      </div>
      <FormattedText
        type="text-body-1"
        value="salesView.finishSaleDialog.message2"
        intl
        class="pb-2"
      />
      <Form :config="dialogConfig" />
      <div class="d-flex flex-column extra-data">
        <div>
          <FormattedText
            type="text-body-1"
            class="pb-2"
            :value="
              `${getTranslatedText('salesView.finishSaleDialog.resultTitle')}:`
            "
          />
          <div class="change-container">
            <FormattedText
              v-if="changeResult > 0"
              type="text-h4"
              className="font-weight-bold"
              class="text-center"
              :value="formatNumberToCurrency(changeResult)"
            />
          </div>
        </div>
        <div
          v-if="forceChangeStatus && loyaltyProgramIsEnabled === false"
          class="mt-auto"
        >
          <v-checkbox
            v-model="forceChangeCheckbox"
            hide-details
            :label="
              getTranslatedText('salesView.finishSaleDialog.forceChangeDialog')
            "
            @change="updateForceChangeDialogStatus"
          />
        </div>
      </div>
    </div>
  </DialogCard>
</template>

<script>
import { mapState, mapActions, mapGetters } from 'vuex'

import { testMode } from '@/config/env'
import PREFERENCES_DB_API_EVENTS from '@/config/events/databaseAPI/preferencesEvents'
import paymentMethods from '@/config/paymentMethods'

import { cleanObjectObserver, getTranslatedText } from '@/tools/data'
import { formatNumberToCurrency, formatNumberToDb } from '@/tools/numbersFormat'

import rendererEventsService from '@/services/renderer/rendererEvents'

import appActions from '@/store/app/actions.types'
import salesViewActions from '@/store/salesView/actions.types'
import salesActions from '@/store/sales/actions.types'

import setDialogConfig from '@/components/SalesView/MultiSalesTabs/FinishSaleDialog/config'
import EnrolledCustomerSelector from '@/components/SalesView/MultiSalesTabs/FinishSaleDialog/EnrolledCustomerSelector'
import DialogCard from '@/components/shared/DialogCard'
import Form from '@/components/shared/Form'
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'FinishSaleDialog',
  components: { DialogCard, Form, FormattedText, EnrolledCustomerSelector },
  props: {
    finalPrice: {
      type: Number,
      required: true,
    },
    paySaleCallback: {
      type: Function,
      required: true,
    },
    fromPayButton: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
      forceChangeStatus: false,
      forceChangeCheckbox: false,
      selectedEnrolledCustomer: null,
    }
  },
  computed: {
    ...mapState('sales', ['sales']),
    ...mapState('salesView', [
      'finishSaleDialog',
      'currentSale',
      'tourEnabled',
    ]),
    ...mapState('app', ['forceChangeDialog']),
    ...mapState('customers', {
      customers: state => state.data.customers,
    }),
    ...mapGetters('account', ['getLoyaltyProgram']),
    showDialog() {
      const saleHasItems =
        !!this.sales[this.currentSale.saleIndex] &&
        (this.sales[this.currentSale.saleIndex].items.length > 0 ||
          this.sales[this.currentSale.saleIndex].promotions.length > 0)
      const isPayCashOp = paymentMethods.isCashSale(
        this.sales[this.currentSale.saleIndex]
          ? this.sales[this.currentSale.saleIndex].payOption
          : ''
      )
      if (
        !saleHasItems ||
        this.currentSale.isFinished ||
        (!isPayCashOp && !this.fromPayButton) ||
        (!isPayCashOp && !this.loyaltyProgramIsEnabled)
      ) {
        this[salesViewActions.setFinishSaleDialogStatus]({
          isOpen: false,
          fromPayButton: false,
        })
      }
      return (
        this.finishSaleDialog.isOpen &&
        saleHasItems &&
        !this.currentSale.isFinished
      )
    },
    setDialogHeight() {
      if (this.showCashIncomeAndChange()) {
        return this.loyaltyProgramIsEnabled ? 630 : 420
      } else {
        return this.loyaltyProgramIsEnabled ? 330 : undefined
      }
    },
    dialogConfig() {
      return setDialogConfig(
        {
          opened: this.showDialog,
          inputs: this.inputs,
          v: this.$v.inputs,
          finalPrice: this.finalPrice,
          persistent: this.tourEnabled,
          dialogHeight: this.setDialogHeight,
        },
        {
          closeDialog: !this.tourEnabled
            ? this.closeDialog
            : () => {
                this.$root.$emit('calculate-change-cancel-tour')
                this.closeDialog()
              },
          paySale: this.paySale,
          amountWasChanged: this.amountWasChanged,
        }
      )
    },
    changeResult() {
      return this.inputs['amount'] - this.finalPrice
    },
    loyaltyProgramIsEnabled() {
      return !!this.getLoyaltyProgram.loyaltyProgramActived
    },
  },
  methods: {
    getTranslatedText,
    formatNumberToCurrency,
    ...mapActions('salesView', [
      salesViewActions.setFinishSaleDialogStatus,
      salesViewActions.setSaleStatus,
      salesViewActions.setEnrolledCustomer,
    ]),
    ...mapActions('sales', [
      salesActions.updateCustomerSelected,
      salesActions.addCashAmount,
    ]),
    ...mapActions('app', [appActions.setForceChangeDialog]),
    setProperties: function() {
      this.dialogConfig.fields.forEach(field => {
        this.$set(this.inputs, field.id, '')
        if (field.validators)
          this.$set(this.validators.inputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
      })
    },
    showCashIncomeAndChange() {
      if (
        this.currentSale.saleIndex === undefined ||
        !this.sales[this.currentSale.saleIndex]
      ) {
        return false
      }
      return (
        (this.forceChangeDialog || !this.fromPayButton) &&
        paymentMethods.isCashSale(
          this.sales[this.currentSale.saleIndex].payOption
        )
      )
    },
    updateForceChangeDialogStatus() {
      rendererEventsService.send(PREFERENCES_DB_API_EVENTS.channel, {
        event: PREFERENCES_DB_API_EVENTS.events.updateByName.name,
        data: {
          property: 'preference_name',
          propertyValue: 'forceChangeDialog',
          dataValue: { preference_value: 'false' },
        },
      })
    },
    paySale() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Sales',
        screen: 'FinishSaleDialog',
        name: 'Finish sale',
      })
      this.paySaleCallback()
      this.closeDialog()
    },
    closeDialog() {
      Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$reset())
      Object.keys(this.inputs).forEach(key => (this.inputs[key] = ''))
      if (this.loyaltyProgramIsEnabled)
        this.$refs.enrolledCustomerSelectorRef.$data.selectedEnrolledCustomer = null
      this[salesViewActions.setFinishSaleDialogStatus]({
        isOpen: false,
        fromPayButton: false,
      })
      this[salesViewActions.setEnrolledCustomer]('')
      this[salesActions.updateCustomerSelected]({
        customer: '',
        enrolledCustomer: '',
        ticketIndex: this.currentSale.saleIndex,
      })
      this[salesViewActions.setSaleStatus](false)
    },
    onSelectEnrolledCustomer() {
      const form = document.getElementById('calculate-change-form')
      if (form) {
        const amountInput = form.querySelector('input[type="number"]')
        amountInput.focus()
      }
      this.setCustomerToSale()
    },
    getCustomer(customerId) {
      return this.customers.find(item => item.id === customerId) || ''
    },
    setCustomerToSale() {
      this[salesActions.updateCustomerSelected]({
        customer: this.getCustomer(
          this.finishSaleDialog.selectedEnrolledCustomer?.customerId
        ),
        enrolledCustomer: this.finishSaleDialog.selectedEnrolledCustomer,
        ticketIndex: this.currentSale.saleIndex,
      })
    },
    amountWasChanged(value) {
      this[salesActions.addCashAmount]({
        ticketIndex: this.currentSale.saleIndex,
        cashAmount: this.changeResult >= 0 ? formatNumberToDb(value) : null,
      })
    },
  },
  validations() {
    return this.validators
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      PREFERENCES_DB_API_EVENTS.replyChannel,
      async (event, payload) => {
        const events = PREFERENCES_DB_API_EVENTS.events
        const replies = {
          [events.updateByName.replies.success]: () =>
            this[appActions.setForceChangeDialog]({ status: false }),
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
  },
  mounted() {
    this.setProperties()
    this.forceChangeStatus = this.forceChangeDialog && this.fromPayButton
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners(
      PREFERENCES_DB_API_EVENTS.replyChannel
    )
  },
}
</script>

<style lang="scss" scoped>
.extra-data {
  height: 118px;
}
.change-container {
  background-color: var(--v-cardBackgroundSecondary-base);
  border-radius: 16px;
  padding: 4px;
  height: 86px;
  display: flex;
  justify-content: center;
  align-items: center;
}
:deep(.v-slide-group__content) {
  justify-content: center;
}
</style>
