<template>
  <ToolBar :config="componentConfig" />
</template>

<script>
import { mapActions, mapState, mapGetters } from 'vuex'
import { isNil } from 'ramda'

import { testMode } from '@/config/env'
import helpCategories from '@/config/helpCategories'

import rendererEvents from '@/services/renderer/rendererEvents'

import helpCenterViewActions from '@/store/helpCenterView/actions.types'
import salesViewActions from '@/store/salesView/actions.types'
import appActions from '@/store/app/actions.types'

import config from '@/components/SalesView/MultiSalesTabs/ProductsFilterToolBar/SalesTools/config'
import ToolBar from '@/components/shared/ToolBar'

export default {
  name: 'SalesTools',
  components: {
    ToolBar,
  },
  data() {
    return {
      config,
    }
  },
  computed: {
    ...mapState('app', {
      isScannerActive: state => state.scanner.isActive,
    }),
    ...mapState('products', ['data', 'view']),
    ...mapState('salesView', {
      filters: state => state.filters,
      listType: state => state.component,
      currentSale: state => state.currentSale.saleIndex,
    }),
    ...mapState('sales', ['sales']),
    ...mapGetters('helpCenter', ['getFilteredData']),
    componentConfig: function() {
      return config(
        {
          data: this.data,
          filters: this.filters,
          listType: this.listType,
          isScannerActive: this.isScannerActive,
          sale: this.sales[this.currentSale],
          videos: this.getFilteredData,
        },
        {
          setSearchTerm: this[salesViewActions.setSearchTermFilter],
          setGroup: this[salesViewActions.setGroupFilter],
          setSelectedSuperCategories: this[
            salesViewActions.setSuperCategoriesFilter
          ],
          onReset: this.onReset,
          setViewComponent: this[salesViewActions.setViewType],
          updateScannerStatus: this[appActions.updateScannerStatus],
          resetScannerStatus: this.resetScannerStatus,
          openAssignCustomerDialog: this.openAssignCustomerDialog,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.updateScannerStatus]),
    ...mapActions('salesView', [
      salesViewActions.setSearchTermFilter,
      salesViewActions.setGroupFilter,
      salesViewActions.setSuperCategoriesFilter,
      salesViewActions.setViewType,
      salesViewActions.setAssignCustomerDialogStatus,
    ]),
    ...mapActions('helpCenterView', [helpCenterViewActions.setVideoTypeFilter]),
    onReset: function() {
      this.$root.$emit('reset')
    },
    resetScannerStatus() {
      const searchInput = document.getElementById('sales-input-search')
      this.isScannerActive ? searchInput.focus() : searchInput.blur()
      this[appActions.updateScannerStatus]()
    },
    openAssignCustomerDialog() {
      this[salesViewActions.setAssignCustomerDialogStatus](true)
    },
  },
  mounted() {
    if (isNil(testMode))
      rendererEvents.subscribe('sales-menu-channel', (event, arg) => {
        switch (arg) {
          case 'link-customer':
            document.getElementById('customer-button-control').click()
            break
        }
      })
    this[helpCenterViewActions.setVideoTypeFilter]([helpCategories.sales])
  },
  beforeDestroy() {
    this[helpCenterViewActions.setVideoTypeFilter]([])
  },
}
</script>
