import { required, sameAs, maxLength } from 'vuelidate/lib/validators'

import { numericAccount } from '@/tools/customValidations'

const setConfig = (state, methods) => ({
  state,
  methods,
  id: 'add-airtime-product-form',
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-credit-card-wireless',
    title: 'salesView.airtimeProductDialog.title',
    messages: ['salesView.airtimeProductDialog.message'],
    extraValuesMessages: [state.providerName],
    titleBackground: '#white',
    titleColor: 'textPrimary',
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    height: 450,
    maxWidth: 500,
    isAcceptButtonDisabled: state.isAcceptButtonDisabled,
    id: 'add-airtime-product-form',
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.sendRechargeService(),
  },
  fields: [
    {
      id: 'service',
      type: 'select',
      label: 'salesView.airtimeProductDialog.services',
      items: state.providerServices,
      itemText: 'description',
      errorMessage: 'salesView.airtimeProductDialog.errorMessages.services',
      color: 'primaryColor',
      validators: { required },
    },
    {
      id: 'phoneNumber',
      type: 'input',
      valueType: 'string',
      step: 1,
      label: 'salesView.airtimeProductDialog.phoneNumber',
      errorMessage: 'salesView.airtimeProductDialog.errorMessages.phoneNumber',
      color: 'primaryColor',
      required: true,
      validators: { required, numericAccount, maxLength: maxLength(10) },
    },
    {
      id: 'phoneNumberTest',
      type: 'input',
      valueType: 'string',
      step: 1,
      label: 'salesView.airtimeProductDialog.phoneNumberTest',
      errorMessage:
        'salesView.airtimeProductDialog.errorMessages.phoneNumberTest',
      color: 'primaryColor',
      required: true,
      validators: { required, sameAs: sameAs('phoneNumber') },
    },
  ],
})

export default setConfig
