const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-account',
    title: 'salesView.assignCustomerDialog.title',
    titleBackground: '',
    titleColor: 'textPrimary',
    messages: ['salesView.assignCustomerDialog.message'],
    buttons: {
      accept: true,
      cancel: true,
    },
    buttonTextColor: {
      accept: 'white',
      cancel: 'white',
    },
    buttonColor: {
      accept: 'primary',
      cancel: 'accent',
    },
    height: 390,
    maxWidth: 500,
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.assignCustomer(),
  },
})

export default setConfig
