const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-delete',
    title: 'salesView.deleteConfirmationDialog.title',
    messages: ['salesView.deleteConfirmationDialog.message'],
    titleBackground: '#white',
    titleColor: 'textPrimary',
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    height: 205,
    maxWidth: 500,
    onClickCancel: () => methods.setDialogStatus(),
    onClickAccept: () => methods.deleteTicket(),
  },
})

export default setConfig
