<template>
  <div v-if="ticketIndex in sales" class="ticket-container">
    <ProductTriangulationDialog
      v-if="
        productTriangulationDialog.isOpen &&
          sales[ticketIndex].ticketId === saleId
      "
    />
    <ListProductPromotionsDialog
      v-if="
        listProductPromotionsDialog.isOpen &&
          sales[ticketIndex].ticketId === saleId
      "
      :ticketIndex="ticketIndex"
    />
    <v-card
      flat
      color="cardBackgroundSecondary"
      height="100%"
      style="border-radius: 10px"
      class="d-flex flex-column pt-3 pb-4"
      id="sales-ticket"
    >
      <ScrollContainer
        class="mb-4 pr-5"
        :scroll-active-style="{ 'padding-right': '0 !important' }"
      >
        <TicketProduct
          v-for="product in productsToList"
          :key="product.uniqueId"
          :ticketIndex="ticketIndex"
          :product="product"
        />
        <template v-for="combo in comboPromotionsToList">
          <ComboPromotion
            :key="combo.id"
            :ticket-index="ticketIndex"
            :promotion="combo"
          />
        </template>
      </ScrollContainer>
      <TicketFooter
        class="mt-auto px-6"
        :ticketIndex="ticketIndex"
        :saleId="saleId"
      />
    </v-card>
  </div>
</template>

<script>
import { mapState } from 'vuex'

import TicketFooter from '@/components/SalesView/MultiSalesTabs/Ticket/TicketFooter'
import ProductTriangulationDialog from '@/components/SalesView/MultiSalesTabs/ProductTriangulationDialog'
import ListProductPromotionsDialog from '@/components/SalesView/MultiSalesTabs/Promotions/ListProductPromotionsDialog'
import ScrollContainer from '@/components/shared/ScrollContainer'
import TicketProduct from '@/components/SalesView/MultiSalesTabs/Ticket/TicketProduct'
import ComboPromotion from '@/components/shared/Ticket/ComboPromotion'

export default {
  name: 'Ticket',
  components: {
    ComboPromotion,
    TicketProduct,
    ScrollContainer,
    ListProductPromotionsDialog,
    TicketFooter,
    ProductTriangulationDialog,
  },
  props: {
    ticketIndex: {
      type: Number,
      default: 0,
    },
    ticketCols: {
      type: Number,
      default: 4,
    },
    saleId: {
      type: Number,
      default: 0,
    },
  },
  computed: {
    ...mapState('sales', ['sales']),
    ...mapState('salesView', [
      'productTriangulationDialog',
      'listProductPromotionsDialog',
    ]),
    productsToList() {
      return this.sales[this.ticketIndex].items
        .filter(item => item.name !== 'commission')
        .slice()
        .reverse()
    },
    comboPromotionsToList() {
      if (!this.sales[this.ticketIndex].promotions) return []
      return this.sales[this.ticketIndex].promotions.slice().reverse()
    },
  },
}
</script>

<style lang="scss" scoped>
.ticket-container {
  background: var(--v-mainBackground-base);
  height: calc(100vh - 268px);
}
</style>
