<template>
  <div>
    <div class="d-flex">
      <PaymentType :config="config.paymentType" />
      <Promotion
        v-if="sales[ticketIndex].ticketId === saleId"
        :ticket="sales[ticketIndex]"
        :cost="Number(getPrice(sales[ticketIndex].items))"
        :disabled-button="disabledTicketPromotionBtn"
        :promotionsOptions="ticketPromotionsOptions"
        :default-type="defaultTypePromotionTicket"
        @applyPromotion="applyTicketPromotion"
      />
    </div>
    <PayButton
      :get-price="getPrice"
      :ticket="sales[ticketIndex]"
      @payButtonWasClicked="onClickPayButton"
    />
    <div class="d-flex mt-2 justify-space-between align-center">
      <div
        v-for="field in config.fields"
        :key="field.id"
        :class="field.class ? field.class : ''"
      >
        <v-switch
          v-if="field.type === 'switch'"
          :input-value="field.value"
          @change="field.onChangeValue"
          :label="getTranslatedText(field.label)"
          :color="field.color"
          :inset="field.inset"
          :hide-details="field.hideDetails"
          class="mt-0"
          v-track:click="{
            category: 'Sales',
            screen: 'TicketFooter',
            name: 'Change ticket printed status',
          }"
        />
        <FormattedText v-if="field.id === 'paymentType'" v-bind="field" />
        <v-icon
          v-if="field.type === 'icon'"
          :size="field.size"
          :color="field.color"
          :disabled="field.disabled"
          @click="field.onClick()"
          v-track:click="{
            category: 'Sales',
            screen: 'TicketFooter',
            name: 'Show finish sale dialog',
          }"
        >
          {{ field.icon }}
        </v-icon>
      </div>
    </div>
    <div v-if="notInTestMode" id="ticket-to-print" v-show="false">
      <TicketToPrint
        :products="products"
        :operationType="operationType"
        :details="details"
        :operationDate="ticketDate"
        :ticketPromotion="ticketPromotion"
        :combos="sales[ticketIndex].promotions"
      />
    </div>
    <RestorePromotionDialog
      v-if="
        sales[ticketIndex].ticketId === saleId && restorePromotionDialog.isOpen
      "
      :ticket-index="ticketIndex"
      @changePayOption="changePayOption"
    />
  </div>
</template>

<script>
import { mapState, mapActions, mapGetters } from 'vuex'

import SALES_DB_API_EVENTS from '@/config/events/databaseAPI/salesEvents'
import { testMode } from '@/config/env'
import paymentMethods from '@/config/paymentMethods'
import { promotions } from '@/config/promotions'

import { formatNumberToDb, roundToNearestMultiple } from '@/tools/numbersFormat'
import { discountTypes, getPromotionTicketToDB } from '@/tools/promotions'
import salesTools from '@/tools/sales'

import rendererEventsService from '@/services/renderer/rendererEvents'

import salesActions from '@/store/sales/actions.types'
import salesViewActions from '@/store/salesView/actions.types'

import Promotion from '@/components/shared/Ticket/Promotion'
import FormattedText from '@/components/shared/FormattedText'
import TicketToPrint from '@/components/TicketToPrint'
import PaymentType from '@/components/shared/PaymentType'
import setConfig from '@/components/SalesView/MultiSalesTabs/Ticket/TicketFooter/config'
import PayButton from '@/components/shared/PayButton'
import RestorePromotionDialog from '@/components/SalesView/MultiSalesTabs/Ticket/TicketFooter/RestorePromotionDialog'
import tools from '@/components/SalesView/MultiSalesTabs/Ticket/TicketFooter/ticketFooter.tools'

export default {
  name: 'TicketFooter',
  components: {
    RestorePromotionDialog,
    PayButton,
    Promotion,
    PaymentType,
    FormattedText,
    TicketToPrint,
  },
  props: {
    ticketIndex: {
      type: Number,
      required: true,
    },
    saleId: {
      type: Number,
      required: true,
    },
  },
  data() {
    return {
      ticketId: null,
      finishingSale: false,
      ticketDate: '',
    }
  },
  computed: {
    ...mapState('sales', ['sales']),
    ...mapState('salesView', {
      saleStatus: state => state.currentSale.isFinished,
      paymentProvidersByType: state => state.paymentProvidersByType,
      restorePromotionDialog: state => state.restorePromotionDialog,
      tourEnabled: state => state.tourEnabled,
    }),
    ...mapState('usersView', ['selectedUser', 'estimatedCash']),
    ...mapState('app', ['forceChangeDialog', 'printTicketDefault']),
    ...mapGetters('account', ['getLoyaltyProgram']),
    ...mapState('products', {
      productStored: state => state.data.products,
    }),
    disabledTicketPromotionBtn() {
      return (
        this.sales[this.ticketIndex].payOption === 'owner' ||
        (!this.sales[this.ticketIndex].items.length &&
          !this.sales[this.ticketIndex].promotions.length) ||
        this.getPrice(this.sales[this.ticketIndex].items) <= 0
      )
    },
    ticketPromotionsOptions() {
      return [
        {
          value: promotions.NONE,
          text: this.getTranslatedText('promotion.ticket.options.none'),
        },
        {
          value: promotions.SALE_TICKET_DISCOUNT,
          text: this.getTranslatedText('promotion.ticket.options.discount'),
        },
        {
          value: promotions.SALE_TICKET_AT_COST,
          text: this.getTranslatedText('promotion.ticket.options.saleAtCost'),
        },
      ]
    },
    defaultTypePromotionTicket() {
      return discountTypes.percent
    },
    products() {
      return this.sales[this.ticketIndex].items.map(item => ({
        ...item,
        price: tools.getProductPriceForTicketToPrint.call(this, item),
        priceWithoutPromotion: item.unitPrice,
        promotionTypeId: tools.getProductPromotionForTicketToPrint.call(
          this,
          item
        ),
      }))
    },
    operationType() {
      return paymentMethods.getIdOperationFromKey(
        this.sales[this.ticketIndex].payOption
      )
    },
    details() {
      const { customer, payOption, paySubOption, cashAmount } = this.sales[
        this.ticketIndex
      ]
      return {
        customer,
        payment_method: paymentMethods.getPaymentMethodIdFromKey(payOption),
        payment_method_provider: paymentMethods.isExternalPaymentSale(payOption)
          ? paySubOption
          : null,
        cash_amount: cashAmount,
      }
    },
    disabledCalculator() {
      return (
        !paymentMethods.isCashSale(this.sales[this.ticketIndex].payOption) ||
        !tools.saleCanBeFinished.call(this)
      )
    },
    config() {
      return setConfig(
        {
          data: this.sales[this.ticketIndex],
          paymentProvidersByType: this.paymentProvidersByType,
          disabledCalculator: this.disabledCalculator,
          tourEnabled: this.tourEnabled,
        },
        {
          changePayOption: (option, paySubOption) =>
            this.changePayOption(option, paySubOption),
          changePrintStatus: () =>
            this.updatePrintTicketStatus(this.ticketIndex),
          openFinishSaleDialog: this.openFinishSaleDialog,
          getTranslatedText: this.getTranslatedText,
          getPrice: () => this.getPrice(this.sales[this.ticketIndex].items),
        }
      )
    },
    notInTestMode() {
      return !testMode
    },
    ticketPromotion() {
      if (this.sales[this.ticketIndex].promotionTicketId === promotions.NONE) {
        return null
      }
      return {
        promotion: this.sales[this.ticketIndex].promotion,
        promotionType: this.sales[this.ticketIndex].promotion_type,
        promotionTicketId: this.sales[this.ticketIndex].promotionTicketId,
      }
    },
  },
  methods: {
    ...mapActions('sales', [
      salesActions.updatePayOptionStatus,
      salesActions.updatePrintTicketStatus,
      salesActions.updateCustomerSelected,
      salesActions.updatePromotionTicket,
      salesActions.addProductToCurrentSale,
      salesActions.removeProductFromSale,
    ]),
    ...mapActions('salesView', [
      salesViewActions.setAssignCustomerDialogStatus,
      salesViewActions.setOverCreditLimitDialogStatus,
      salesViewActions.setFinishSaleDialogStatus,
      salesViewActions.setSaleStatus,
      salesViewActions.setRestorePromotionDialogStatus,
    ]),
    getTranslatedText(translateString) {
      return this.$vuetify.lang.t(`$vuetify.${translateString}`)
    },
    changePayOption(option, paySubOption, restorePromotionsAccepted = false) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Sales',
        screen: 'TicketFooter',
        name: `Change pay option to ${option}`,
      })
      if (
        this.mustShowRestorePromotionsAlert(option, restorePromotionsAccepted)
      ) {
        this[salesViewActions.setRestorePromotionDialogStatus]({
          isOpen: true,
          fromPayOption: this.sales[this.ticketIndex].payOption,
          toPayOption: option,
        })
        return
      }
      tools.updatePayOptionStore.call(this, option, paySubOption)
      tools.manageCommission.call(this, option, paySubOption)
      if (tools.isCreditSaleWithoutCustomer.call(this, option)) {
        tools.openAssignCustomerDialog.call(this)
        return
      }
      tools.showOwnerSaleNotificationIfIsNeeded.call(this, option)
      tools.updateCustomerSelectedStore.call(this)
    },
    mustShowRestorePromotionsAlert(option, restorePromotionsAccepted) {
      return (
        option === 'owner' &&
        !restorePromotionsAccepted &&
        (this.sales[this.ticketIndex].promotionTicketId !== promotions.NONE ||
          this.sales[this.ticketIndex].items.some(
            item =>
              item.promotionTypeId !== promotions.NONE ||
              item.promotions.length > 0
          ) ||
          this.sales[this.ticketIndex].promotions.length > 0)
      )
    },
    openFinishSaleDialog() {
      if (this.disabledCalculator) return
      this[salesViewActions.setFinishSaleDialogStatus]({
        isOpen: true,
        fromPayButton: false,
      })
    },
    async onClickPayButton() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Sales',
        screen: 'PayButton',
        name: 'Finish sale',
      })
      if (!tools.saleCanBeFinished.call(this)) return
      if (tools.isSaleBeingFinished.call(this)) return
      tools.setTicketData.call(this)
      const saleData = this.sales[this.ticketIndex]
      this.finishingSale = false
      if (tools.isCreditSaleWithDebtLimitExceeded.call(this, saleData)) {
        this[salesViewActions.setOverCreditLimitDialogStatus](true)
        this[salesViewActions.setSaleStatus](false)
        return
      }
      if (tools.saleFinishDialogMustBeDisplayed.call(this, saleData)) {
        this[salesViewActions.setFinishSaleDialogStatus]({
          isOpen: true,
          fromPayButton: true,
        })
        this[salesViewActions.setSaleStatus](false)
        return
      }
      await this.finishSelectedSale()
    },
    getPrice(products, forceUseUnitPrice = false) {
      const toPay = tools.getSaleTotalPrice.call(
        this,
        products,
        forceUseUnitPrice
      )
      return roundToNearestMultiple(parseInt(toPay.toFixed(0)))
    },
    getEstimatedCash() {
      const stateEstimatedCash =
        this.estimatedCash === null || this.estimatedCash === undefined
          ? 0
          : this.estimatedCash
      return formatNumberToDb(stateEstimatedCash)
    },
    finishSelectedSale() {
      this.$loading.show('finishSale')
      const { items, totalPrice } = salesTools.getTotalPriceAndItemsWithCombos(
        this.sales[this.ticketIndex],
        this.getPrice(this.sales[this.ticketIndex].items, true),
        this.productStored
      )
      rendererEventsService.send(SALES_DB_API_EVENTS.channel, {
        event: SALES_DB_API_EVENTS.events.finishSale.name,
        data: {
          saleData: {
            ...this.sales[this.ticketIndex],
            promotion: getPromotionTicketToDB({
              ...this.sales[this.ticketIndex],
              cost: this.getPrice(this.sales[this.ticketIndex].items, true),
            }),
            items,
          },
          userId: this.selectedUser.id,
          username: this.selectedUser.name,
          totalPrice,
          estimatedCash: this.getEstimatedCash(),
          loyaltyProgram: this.getLoyaltyProgram,
          cashOpExtraInfo: tools.getSaleCashOpExtraInfo.call(
            this,
            this.sales[this.ticketIndex].payOption,
            this.sales[this.ticketIndex].paySubOption
          ),
        },
      })
    },
    applyTicketPromotion(promotion) {
      if (promotion.promotionTicketId !== 0) {
        this.$track({
          type: 'interaction',
          action: 'click',
          category: 'Sales',
          screen: 'TicketProduct',
          name: `Apply ticket ${
            promotions.SALE_TICKET_DISCOUNT === promotion.promotionTicketId
              ? 'discount'
              : 'at cost'
          }`,
        })
      }
      this[salesActions.updatePromotionTicket]({
        ...promotion,
        ticketIndex: this.ticketIndex,
      })
    },
    shortcutListener() {
      this.onClickPayButton()
    },
    setSaleTicketDate(date) {
      this.ticketDate = date
    },
  },
  created() {
    this.ticketId = this.sales[this.ticketIndex].ticketId
    this.$root.$on(`click-pay-sale-${this.ticketId}`, this.shortcutListener)
    this.$root.$on('setSaleTicketDate', this.setSaleTicketDate)
    this.sales[this.ticketIndex].print = this.printTicketDefault
  },
  beforeDestroy() {
    this.$root.$off(`click-pay-sale-${this.ticketId}`, this.shortcutListener)
    this.$root.$off('setSaleTicketDate', this.setSaleTicketDate)
  },
}
</script>
