<template>
  <v-dialog
    v-model="showDialog"
    :overlay-opacity="0.15"
    max-width="500"
    content-class="default-dialog"
    @click:outside="closeDialog()"
    @keydown.esc="closeDialog()"
  >
    <v-card class="dialog-style">
      <v-card-title class="simple-title">
        <h5 class="font-weight-medium d-flex align-center">
          <v-icon>mdi-sale</v-icon>
          {{ dialogTitle }}
        </h5>
      </v-card-title>
      <v-card-text>
        <ComboList
          v-if="comboPromotions.length > 0"
          :ticket-index="ticketIndex"
          :promotions="comboPromotions"
        />
        <v-divider
          v-if="comboPromotions.length > 0 && moreForLessPromotions.length > 0"
          class="my-4"
        />
        <MoreForLessList
          v-if="moreForLessPromotions.length > 0"
          :ticket-index="ticketIndex"
          :promotions="moreForLessPromotions"
        />
      </v-card-text>
      <v-card-actions class="px-6 pb-6 pt-2">
        <v-spacer />
        <v-btn color="accent" @click="closeDialog()">
          <v-icon>mdi-close-circle-outline</v-icon>
          {{ getTranslatedText('close') }}
        </v-btn>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script>
import { mapActions, mapGetters, mapState } from 'vuex'

import { promotions } from '@/config/promotions'

import { getTranslatedText } from '@/tools/data'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'
import { customPromotion } from '@/tools/customPromotions'

import salesViewActions from '@/store/salesView/actions.types'

import MoreForLessList from '@/components/SalesView/MultiSalesTabs/Promotions/ListProductPromotionsDialog/MoreForLessList'
import ComboList from '@/components/SalesView/MultiSalesTabs/Promotions/ListProductPromotionsDialog/ComboList'

export default {
  name: 'ListProductPromotionsDialog',
  components: { ComboList, MoreForLessList },
  props: {
    ticketIndex: {
      type: Number,
      required: true,
    },
  },
  data() {
    return {
      moreForLessPromotions: [],
      comboPromotions: [],
    }
  },
  computed: {
    ...mapState('sales', ['sales']),
    ...mapState('salesView', ['listProductPromotionsDialog']),
    ...mapGetters('customPromotions', [
      'getCustomPromotionsByProductAndTypeWithFilters',
    ]),
    showDialog: {
      get() {
        return this.listProductPromotionsDialog.isOpen
      },
      set() {
        this.closeDialog()
      },
    },
    dialogTitle() {
      return this.getTranslatedText(
        'customPromotionsView.inSale.dialogPromotion.title',
        this.listProductPromotionsDialog.product.name
      )
    },
    promotionsFilters() {
      return {
        isActive: true,
        product: this.listProductPromotionsDialog.product,
        sale: true,
      }
    },
  },
  methods: {
    formatNumberFromDbToCurrency,
    ...mapActions('salesView', [
      salesViewActions.setListProductPromotionsDialogStatus,
    ]),
    getTranslatedText,
    closeDialog() {
      this[salesViewActions.setListProductPromotionsDialogStatus]({
        isOpen: false,
      })
    },
    getMoreForLessPromotions() {
      const moreForLess = this.getCustomPromotionsByProductAndTypeWithFilters(
        promotions.SALE_ITEM_MORE_FOR_LESS,
        this.promotionsFilters
      )[this.listProductPromotionsDialog.product.id]
      if (!moreForLess || !customPromotion.isActive(moreForLess)) return []
      return moreForLess.promotions.sort(
        (promo1, promo2) => promo1.quantity - promo2.quantity
      )
    },
    getComboPromotions() {
      const combos = this.getCustomPromotionsByProductAndTypeWithFilters(
        promotions.SALE_ITEM_COMBO,
        this.promotionsFilters
      )[this.listProductPromotionsDialog.product.id]
      if (!combos) return []
      return combos
    },
  },
  beforeMount() {
    this.moreForLessPromotions = this.getMoreForLessPromotions()
    this.comboPromotions = this.getComboPromotions()
  },
  destroyed() {
    this.closeDialog()
  },
}
</script>

<style scoped lang="scss">
.simple-title {
  h5 {
    text-overflow: ellipsis;
    white-space: nowrap;
    overflow: hidden;
    max-width: 100%;
    box-sizing: border-box;
  }
}
</style>
