import uniqid from 'uniqid'

import paymentMethods from '@/config/paymentMethods'
import priceFrom from '@/config/itemAddedFrom'
import { promotions } from '@/config/promotions'

import salesTools from '@/tools/sales'
import { getNow } from '@/tools/dates'
import {
  getTotalProductPrice,
  getTotalTicketPriceOwnerSale,
} from '@/tools/ticket'

import notificationsService from '@/services/renderer/notifications'

import salesViewActions from '@/store/salesView/actions.types'
import salesActions from '@/store/sales/actions.types'

const updatePayOptionStore = function(option, paySubOption) {
  this[salesActions.updatePayOptionStatus]({
    ticketIndex: this.ticketIndex,
    option,
    paySubOption: paySubOption,
  })
}

const manageCommission = function(option, paySubOption) {
  deleteSaleProductAsCommission.call(this)
  if (!paymentMethods.isCardSale(option)) {
    return
  }
  const paymentMethod = this.paymentProvidersByType[option].find(
    provider => provider.id === paySubOption
  )
  if (!paymentMethod || paymentMethod.commissions <= 0) return
  const totalPrice = getSaleTotalPrice.call(
    this,
    this.sales[this.ticketIndex].items,
    true
  )
  this[salesActions.addProductToCurrentSale]({
    currentSale: this.ticketIndex,
    product: generateGenericProductCommission(paymentMethod, totalPrice),
  })
}

const deleteSaleProductAsCommission = function() {
  const commissionFound = this.sales[this.ticketIndex].items.find(
    item => item.name === 'commission'
  )
  if (!commissionFound) {
    return
  }
  this[salesActions.removeProductFromSale]({
    ticketIndex: this.ticketIndex,
    uniqueId: commissionFound.uniqueId,
  })
}

const generateGenericProductCommission = (paymentMethod, totalPrice) => {
  return {
    uniqueId: uniqid(),
    id: -1,
    stock: -999999,
    isGramaje: 0,
    isOpenProduct: 0,
    isGeneric: 1,
    name: 'commission',
    quantity: 1,
    unitPrice: Math.round((totalPrice * paymentMethod.commissions) / 100),
    cost: -1,
    upc: '00000000',
    timeAdded: getNow(false),
    priceFrom: priceFrom.FROM_PRICE,
    levelWarning: 0,
  }
}

const isCreditSaleWithoutCustomer = function(option) {
  return (
    paymentMethods.isCreditSale(option) &&
    this.sales[this.ticketIndex].customer === ''
  )
}
const openAssignCustomerDialog = function() {
  this[salesViewActions.setAssignCustomerDialogStatus](true)
}

const showOwnerSaleNotificationIfIsNeeded = function(option) {
  if (paymentMethods.isOwnerSale(option)) {
    notificationsService.showInfo(
      'notification.sales.showCost',
      this.$vuetify.lang
    )
  }
}

const updateCustomerSelectedStore = function() {
  this[salesActions.updateCustomerSelected]({
    customer: '',
    enrolledCustomer: '',
    ticketIndex: this.ticketIndex,
  })
}

const saleCanBeFinished = function() {
  return (
    !!this.sales[this.ticketIndex] &&
    (this.sales[this.ticketIndex].items.length > 0 ||
      this.sales[this.ticketIndex].promotions.length > 0) &&
    this.getPrice(this.sales[this.ticketIndex].items) > 0
  )
}

const isSaleBeingFinished = function() {
  if (this.finishingSale || this.saleStatus) {
    return true
  }
  this.finishingSale = true
  this[salesViewActions.setSaleStatus](true)
  return false
}
const setTicketData = function() {
  this.ticketDate = getNow()
}
const isCreditSaleWithDebtLimitExceeded = function(saleData) {
  return (
    paymentMethods.isCreditSale(saleData.payOption) &&
    saleData.customer.debtLimit !== 0 &&
    saleData.customer.debt + this.getPrice(saleData.items) >
      saleData.customer.debtLimit
  )
}
const saleFinishDialogMustBeDisplayed = function(saleData) {
  return (
    (paymentMethods.isCashSale(saleData.payOption) && this.forceChangeDialog) ||
    (!paymentMethods.isOwnerSale(saleData.payOption) &&
      !paymentMethods.isCreditSale(saleData.payOption) &&
      this.getLoyaltyProgram.loyaltyProgramActived)
  )
}

const getSaleTotalPrice = function(products, forceUseUnitPrice) {
  if (
    !forceUseUnitPrice &&
    salesTools.isOwnerSale(this.sales[this.ticketIndex].payOption)
  ) {
    return getTotalTicketPriceOwnerSale(products, 'unitPrice')
  }
  const totalCombo = getTotalComboPrice.call(this)
  const totalProductsPrice = products.reduce((total, product) => {
    return (
      total +
      getTotalProductPrice(
        {
          ...product,
          unitPrice: salesTools.getProductPrice(
            this.sales[this.ticketIndex],
            product
          ),
        },
        'unitPrice'
      )
    )
  }, 0)
  return totalProductsPrice + totalCombo
}

const getTotalComboPrice = function() {
  return this.sales[this.ticketIndex].promotions.reduce((total, promo) => {
    total += promo.quantity * promo.promotions.total
    return total
  }, 0)
}

const getSaleCashOpExtraInfo = function(payOption, paySubOption) {
  if (!paymentMethods.isExternalPaymentSale(payOption)) return null
  const providerFound = this.paymentProvidersByType[payOption].find(
    provider => provider.id === paySubOption
  )
  if (!providerFound) return null
  if (!paymentMethods.defaultPaymentMethods.includes(payOption)) {
    return providerFound.label
  }
  return `${this.getTranslatedText(`salesView.ticket.${payOption}`)} (${
    providerFound.label
  })`
}

const getProductPriceForTicketToPrint = function(product) {
  if (salesTools.isOwnerSale(this.operationType)) {
    return salesTools.getProductCost(product)
  }
  if (product.promotionTypeId === promotions.SALE_ITEM_FREE_PRODUCT) return 0
  if (product.promotions && product.promotions.length > 0) {
    return salesTools.getProductPriceWithMoreForLessPromo(product)
  }
  if (
    salesTools.canApplyTicketAtCost(
      this.sales[this.ticketIndex].promotionTicketId,
      product
    )
  ) {
    if (product.openProductType === 1 && product.isOpenProduct === 1) {
      return Number((product.cost / product.factor).toFixed(0))
    }
    return product.cost
  }
  return product.unitPrice
}

const getProductPromotionForTicketToPrint = function(product) {
  if (product.promotionTypeId !== promotions.NONE) {
    return product.promotionTypeId
  }
  if (product.promotions && product.promotions.length) {
    return product.promotions[0].type
  }
  if (
    this.sales[this.ticketIndex].promotionTicketId ===
    promotions.SALE_TICKET_AT_COST
  ) {
    return promotions.SALE_TICKET_AT_COST
  }
  return 0
}

export default {
  updatePayOptionStore,
  manageCommission,
  isCreditSaleWithoutCustomer,
  showOwnerSaleNotificationIfIsNeeded,
  openAssignCustomerDialog,
  updateCustomerSelectedStore,
  saleCanBeFinished,
  isSaleBeingFinished,
  setTicketData,
  isCreditSaleWithDebtLimitExceeded,
  saleFinishDialogMustBeDisplayed,
  getSaleTotalPrice,
  getTotalComboPrice,
  getSaleCashOpExtraInfo,
  getProductPriceForTicketToPrint,
  getProductPromotionForTicketToPrint,
}
