<template>
  <Product
    :product="{ ...product, price: productPrice }"
    :actions="cardActions"
    :pay-option="sales[this.ticketIndex].payOption"
    :promotion-ticket-id="this.sales[this.ticketIndex].promotionTicketId"
    price-key="price"
    price-without-promotion-key="unitPrice"
    @productCardWasClicked="editProduct"
  />
</template>

<script>
import { mapActions, mapState } from 'vuex'

import salesTools from '@/tools/sales'

import salesViewActions from '@/store/salesView/actions.types'
import salesActions from '@/store/sales/actions.types'

import Product from '@/components/shared/Ticket/Product'

export default {
  name: 'TicketProduct',
  components: { Product },
  props: {
    ticketIndex: {
      type: Number,
      required: true,
    },
    product: {
      type: Object,
      required: true,
    },
  },
  computed: {
    ...mapState('sales', ['sales']),
    cardActions() {
      return {
        add: {
          on: { click: () => this.changeQuantity(1) },
          show: this.product.isAirtime !== 1 && this.product.isGeneric !== 1,
        },
        subtract: {
          on: { click: () => this.changeQuantity(-1) },
          show: this.product.isAirtime !== 1 && this.product.isGeneric !== 1,
        },
        delete: {
          on: { click: this.deleteProduct },
          show: this.product.isAirtime !== 1,
        },
        edit: {
          on: { click: this.editProduct },
          show: this.product.isAirtime !== 1,
        },
      }
    },
    productPrice() {
      return salesTools.getProductPrice(
        this.sales[this.ticketIndex],
        this.product
      )
    },
  },
  methods: {
    ...mapActions('sales', [
      salesActions.updateProductQuantity,
      salesActions.removeProductFromSale,
    ]),
    ...mapActions('salesView', [
      salesViewActions.setSelectedProduct,
      salesViewActions.toggleProductTriangulationDialogStatus,
      salesViewActions.toggleGenericProductDialogStatus,
    ]),
    trackActions(action) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Sales',
        screen: 'TicketProduct',
        name: action,
      })
    },
    changeQuantity(unit) {
      if (unit < 0 && this.product.quantity <= 1) return
      this.trackActions(`${unit > 0 ? 'Add' : 'Subtract'} product quantity`)
      this[salesActions.updateProductQuantity]({
        ticketIndex: this.ticketIndex,
        upcProduct: this.product.upc,
        quantity: this.product.quantity + unit,
      })
    },
    deleteProduct() {
      this.trackActions('Remove product')
      this[salesActions.removeProductFromSale]({
        ticketIndex: this.ticketIndex,
        upcProduct: this.product.upc,
      })
    },
    editProduct() {
      this.trackActions(
        this.product.isGeneric === 1
          ? 'Show generic product dialog'
          : 'Show product triangulation dialog'
      )
      if (this.product.isAirtime === 1) return
      this[salesViewActions.setSelectedProduct]({
        ticketIndex: this.ticketIndex,
        product: this.product,
      })
      this.product.isGeneric === 1
        ? this[salesViewActions.toggleGenericProductDialogStatus]()
        : this[salesViewActions.toggleProductTriangulationDialogStatus]()
    },
  },
}
</script>
