const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-alert-circle',
    title: 'salesView.restorePromotionDialog.title',
    titleBackground: '',
    titleColor: 'textPrimary',
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    messages: ['salesView.restorePromotionDialog.message'],
    height: 225,
    maxWidth: 500,
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.acceptRestorePromotions(),
  },
})

export default setConfig
