<template>
  <DialogCard :config="dialogConfig.dialogData" />
</template>

<script>
import { mapState, mapActions } from 'vuex'

import salesViewActions from '@/store/salesView/actions.types'

import DialogCard from '@/components/shared/DialogCard'
import setConfig from '@/components/SalesView/MultiSalesTabs/NotificationDialog/config'

export default {
  name: 'NotificationDialog',
  components: { DialogCard },
  computed: {
    ...mapState('salesView', {
      notificationDialogStaus: state => state.notificationDialog.isOpen,
    }),
    dialogConfig() {
      return setConfig(
        { isOpen: this.notificationDialogStaus },
        {
          setDialogStatus: this[salesViewActions.setNotificationDialogStatus],
          setGroup: this[salesViewActions.setGroupFilter],
          setSelectedSuperCategories: this[
            salesViewActions.setSuperCategoriesFilter
          ],
          context: this,
        }
      )
    },
  },
  methods: {
    ...mapActions('salesView', [
      salesViewActions.setNotificationDialogStatus,
      salesViewActions.setGroupFilter,
      salesViewActions.setSuperCategoriesFilter,
    ]),
  },
}
</script>
